CREATE OR REPLACE FUNCTION public.proteger_os_historica_migrada()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if old.migracao_referencia is not null
     and coalesce(current_setting('app.permitir_alterar_os_migrada', true), '') <> 'on' then
    raise exception 'A OS % e historica e somente leitura.', old.id
      using errcode = '55000';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.trg_os_status_estornar()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Rejeicao do orcamento e cancelamento definitivo devolvem qualquer baixa existente.
  IF new.status IN ('ORCAMENTO_RECUSADO', 'CANCELADO')
     AND old.status IS DISTINCT FROM new.status THEN
    PERFORM public.estornar_baixa_estoque_os(new.id);
    PERFORM public.estornar_consumos_os(new.id);
  END IF;
  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.registrar_finalizacao_os()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_novo_final boolean := new.status::text in ('CONCLUIDO', 'SEM_COBRANCA', 'CANCELADO');
  v_antigo_final boolean := false;
begin
  if tg_op = 'INSERT' then
    new.finalizado_em := case when v_novo_final then coalesce(new.finalizado_em, now()) else null end;
    return new;
  end if;

  v_antigo_final := old.status::text in ('CONCLUIDO', 'SEM_COBRANCA', 'CANCELADO');
  if old.status is distinct from new.status then
    if v_novo_final then
      new.finalizado_em := case when v_antigo_final then now() else coalesce(new.finalizado_em, now()) end;
    elsif v_antigo_final then
      new.finalizado_em := null;
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.chat_get_or_create_direct(p_usuario_atual uuid, p_destinatario uuid)
 RETURNS TABLE(conversa_id uuid, criada boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_conversa_id uuid;
  v_criada boolean := false;
  v_direct_key text;
begin
  if p_usuario_atual is null or p_destinatario is null or p_usuario_atual = p_destinatario then
    raise exception using errcode = '22023', message = 'CHAT_INVALID_RECIPIENT';
  end if;

  if not exists (
    select 1 from public.usuario
    where id = p_usuario_atual and ativo = true
  ) then
    raise exception using errcode = '42501', message = 'INACTIVE_USER';
  end if;

  if not exists (
    select 1 from public.usuario
    where id = p_destinatario and ativo = true
  ) then
    raise exception using errcode = '22023', message = 'CHAT_RECIPIENT_UNAVAILABLE';
  end if;

  v_direct_key := public.chat_direct_key(p_usuario_atual, p_destinatario);

  insert into public.chat_conversa(tipo, direct_key)
  values ('DIRECT', v_direct_key)
  on conflict (direct_key) do nothing
  returning id into v_conversa_id;

  if v_conversa_id is null then
    select id into strict v_conversa_id
    from public.chat_conversa
    where direct_key = v_direct_key;
  else
    v_criada := true;
  end if;

  insert into public.chat_participante(conversa_id, usuario_id)
  values
    (v_conversa_id, p_usuario_atual),
    (v_conversa_id, p_destinatario)
  on conflict on constraint chat_participante_pkey do nothing;

  -- O payload e apenas uma invalidacao. Dados do chat continuam restritos as APIs.
  perform realtime.send(
    jsonb_build_object('kind', 'conversation', 'conversationId', v_conversa_id),
    'chat_changed',
    'chat:user:' || p_usuario_atual::text,
    true
  );
  perform realtime.send(
    jsonb_build_object('kind', 'conversation', 'conversationId', v_conversa_id),
    'chat_changed',
    'chat:user:' || p_destinatario::text,
    true
  );

  return query select v_conversa_id, v_criada;
end;
$function$

CREATE OR REPLACE FUNCTION public.propagar_nome_plano_de_conta()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.nome IS DISTINCT FROM OLD.nome THEN
    UPDATE public.transacao
    SET plano_de_conta = NEW.nome
    WHERE plano_de_conta_id = NEW.id;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.propagar_nome_centro_custo()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.nome IS DISTINCT FROM OLD.nome THEN
    UPDATE public.transacao
    SET centro_custo = NEW.nome
    WHERE centro_custo_id = NEW.id;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.chat_mark_read(p_usuario_id uuid, p_conversa_id uuid, p_last_message_id uuid)
 RETURNS TABLE(last_read_message_id uuid, last_read_at timestamp with time zone, alterada boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_atual_id uuid;
  v_atual_at timestamptz;
  v_alvo_at timestamptz;
  v_read_at timestamptz;
  v_alterada boolean := false;
begin
  select p.last_read_message_id, p.last_read_at, atual.created_at
  into v_atual_id, v_read_at, v_atual_at
  from public.chat_participante p
  left join public.chat_mensagem atual on atual.id = p.last_read_message_id
  where p.conversa_id = p_conversa_id and p.usuario_id = p_usuario_id
  for update of p;

  if not found then
    raise exception using errcode = '42501', message = 'CHAT_FORBIDDEN';
  end if;

  select msg.created_at into v_alvo_at
  from public.chat_mensagem msg
  where msg.id = p_last_message_id and msg.conversa_id = p_conversa_id;

  if not found then
    raise exception using errcode = '22023', message = 'CHAT_INVALID_READ_MESSAGE';
  end if;

  if v_atual_id is null or (v_alvo_at, p_last_message_id) > (v_atual_at, v_atual_id) then
    v_read_at := clock_timestamp();
    update public.chat_participante participante
    set last_read_message_id = p_last_message_id,
        last_read_at = v_read_at
    where participante.conversa_id = p_conversa_id
      and participante.usuario_id = p_usuario_id;
    v_atual_id := p_last_message_id;
    v_alterada := true;
  end if;

  return query select v_atual_id, v_read_at, v_alterada;
end;
$function$

CREATE OR REPLACE FUNCTION public.criar_item_usoconsumo(p_item jsonb, p_estoque_inicial integer DEFAULT 0, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS usoconsumo_item
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item public.usoconsumo_item%ROWTYPE;
  v_entrada_id bigint;
  v_entrada_item_id bigint;
  v_escopo text := upper(btrim(coalesce(p_item->>'escopo','USOCONSUMO')));
BEGIN
  IF nullif(btrim(p_item->>'titulo'),'') IS NULL THEN
    RAISE EXCEPTION 'Informe o titulo.' USING ERRCODE='22023';
  END IF;
  IF v_escopo NOT IN ('USOCONSUMO','GERAL') THEN
    RAISE EXCEPTION 'Escopo de estoque invalido: %.', v_escopo USING ERRCODE='22023';
  END IF;
  IF p_estoque_inicial IS NULL OR p_estoque_inicial < 0 THEN
    RAISE EXCEPTION 'Estoque inicial invalido.' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.usoconsumo_item (
    escopo,titulo,descricao,referencia,fabricante,grupo_id,unidade,conservacao,codigobarras,etiqueta,local,
    estoque,estoqueminimo,precocompra,ultimovalordecompra,ncm,cest,cfop_entrada,origem_mercadoria,
    csosn,cst,aliquotaicms,cst_pis,aliquota_pis,modo_pis,aliquota_por_unidade_pis,cst_cofins,
    aliquota_cofins,modo_cofins,aliquota_por_unidade_cofins,cst_ibscbs,cclass_trib,aliquota_ibs_uf,
    aliquota_ibs_municipio,aliquota_cbs,created_by,updated_by
  ) VALUES (
    v_escopo,
    btrim(p_item->>'titulo'),nullif(btrim(p_item->>'descricao'),''),nullif(btrim(p_item->>'referencia'),''),
    nullif(btrim(p_item->>'fabricante'),''),nullif(p_item->>'grupo_id','')::integer,
    coalesce(nullif(p_item->>'unidade','')::public.unidade_medida,'UN'),coalesce(nullif(p_item->>'conservacao',''),'NOVO'),
    nullif(btrim(p_item->>'codigobarras'),''),nullif(btrim(p_item->>'etiqueta'),''),nullif(btrim(p_item->>'local'),''),
    p_estoque_inicial,coalesce(nullif(p_item->>'estoqueminimo','')::integer,0),
    coalesce(nullif(p_item->>'precocompra','')::numeric,0),
    CASE WHEN p_estoque_inicial>0 THEN coalesce(nullif(p_item->>'precocompra','')::numeric,0) ELSE NULL END,
    nullif(btrim(p_item->>'ncm'),''),nullif(btrim(p_item->>'cest'),''),nullif(btrim(p_item->>'cfop_entrada'),''),
    nullif(btrim(p_item->>'origem_mercadoria'),''),nullif(btrim(p_item->>'csosn'),''),nullif(btrim(p_item->>'cst'),''),
    nullif(p_item->>'aliquotaicms','')::numeric,nullif(btrim(p_item->>'cst_pis'),''),nullif(p_item->>'aliquota_pis','')::numeric,
    nullif(btrim(p_item->>'modo_pis'),''),nullif(p_item->>'aliquota_por_unidade_pis','')::numeric,
    nullif(btrim(p_item->>'cst_cofins'),''),nullif(p_item->>'aliquota_cofins','')::numeric,
    nullif(btrim(p_item->>'modo_cofins'),''),nullif(p_item->>'aliquota_por_unidade_cofins','')::numeric,
    nullif(btrim(p_item->>'cst_ibscbs'),''),nullif(btrim(p_item->>'cclass_trib'),''),
    nullif(p_item->>'aliquota_ibs_uf','')::numeric,nullif(p_item->>'aliquota_ibs_municipio','')::numeric,
    nullif(p_item->>'aliquota_cbs','')::numeric,p_created_by,p_created_by
  ) RETURNING * INTO v_item;
  IF p_estoque_inicial>0 THEN
    INSERT INTO public.usoconsumo_entrada(escopo,tipo,origem,valor_total,created_by)
      VALUES(v_escopo,'SALDO_INICIAL','AJUSTE_RAPIDO',round(p_estoque_inicial*v_item.precocompra,2),p_created_by)
      RETURNING id INTO v_entrada_id;
    INSERT INTO public.usoconsumo_entrada_item(
      entrada_id,item_id,quantidade,unidade,valor_unitario_compra,valor_total,saldo_anterior,saldo_resultante,titulo
    ) VALUES(v_entrada_id,v_item.id,p_estoque_inicial,v_item.unidade,v_item.precocompra,
      round(p_estoque_inicial*v_item.precocompra,2),0,p_estoque_inicial,v_item.titulo)
    RETURNING id INTO v_entrada_item_id;
    INSERT INTO public.usoconsumo_movimento_entrada(
      entrada_id,entrada_item_id,item_id,tipo,quantidade,saldo_anterior,saldo_resultante,valor_unitario_compra,created_by
    ) VALUES(v_entrada_id,v_entrada_item_id,v_item.id,'ENTRADA',p_estoque_inicial,0,p_estoque_inicial,v_item.precocompra,p_created_by);
  END IF;
  RETURN v_item;
END $function$

CREATE OR REPLACE FUNCTION public.registrar_saida_usoconsumo(p_saida jsonb, p_itens jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_saida_id bigint; v_json jsonb; v_item public.usoconsumo_item%ROWTYPE;
  v_item_id integer; v_qtd integer; v_user uuid; v_motivo text;
  v_escopo text := upper(btrim(coalesce(p_saida->>'escopo','USOCONSUMO')));
BEGIN
  IF jsonb_typeof(p_itens)<>'array' OR jsonb_array_length(p_itens)=0 THEN
    RAISE EXCEPTION 'Informe ao menos um item.' USING ERRCODE='22023';
  END IF;
  IF v_escopo NOT IN ('USOCONSUMO','GERAL') THEN
    RAISE EXCEPTION 'Escopo de estoque invalido: %.', v_escopo USING ERRCODE='22023';
  END IF;
  v_motivo := upper(btrim(coalesce(p_saida->>'motivo','')));
  IF NOT EXISTS (
    SELECT 1 FROM public.tipos_motivo_saida
    WHERE codigo = v_motivo AND ativo AND escopo IN ('USOCONSUMO', 'AMBOS')
  ) THEN RAISE EXCEPTION 'Motivo invalido.' USING ERRCODE='22023'; END IF;
  IF v_motivo='OUTRO' AND nullif(btrim(p_saida->>'observacao'),'') IS NULL THEN
    RAISE EXCEPTION 'Informe a observacao.' USING ERRCODE='22023';
  END IF;
  v_user:=nullif(p_saida->>'created_by','')::uuid;
  INSERT INTO public.usoconsumo_saida(escopo,motivo,observacao,setor,funcionario,centro_custo_id,created_by)
  VALUES(v_escopo,v_motivo,nullif(btrim(p_saida->>'observacao'),''),nullif(btrim(p_saida->>'setor'),''),
    nullif(btrim(p_saida->>'funcionario'),''),nullif(p_saida->>'centro_custo_id','')::integer,v_user)
  RETURNING id INTO v_saida_id;
  FOR v_json IN SELECT value FROM jsonb_array_elements(p_itens) LOOP
    v_item_id:=nullif(v_json->>'item_id','')::integer; v_qtd:=nullif(v_json->>'quantidade','')::integer;
    IF v_item_id IS NULL OR v_qtd IS NULL OR v_qtd<=0 THEN
      RAISE EXCEPTION 'Item ou quantidade invalida.' USING ERRCODE='22023';
    END IF;
    SELECT * INTO v_item FROM public.usoconsumo_item WHERE id=v_item_id AND ativo AND escopo=v_escopo FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Item % nao encontrado neste estoque.',v_item_id USING ERRCODE='P0002';
    END IF;
    IF v_item.estoque<v_qtd THEN
      RAISE EXCEPTION 'Estoque insuficiente para o item %.',v_item_id USING ERRCODE='23514';
    END IF;
    INSERT INTO public.usoconsumo_saida_item(saida_id,item_id,quantidade,saldo_anterior,saldo_resultante,valor_custo_aplicado)
      VALUES(v_saida_id,v_item_id,v_qtd,v_item.estoque,v_item.estoque-v_qtd,coalesce(v_item.ultimovalordecompra,v_item.precocompra,0));
    PERFORM set_config('app.usoconsumo_movimento','permitido',true);
    UPDATE public.usoconsumo_item SET estoque=estoque-v_qtd,updated_by=v_user WHERE id=v_item_id;
  END LOOP;
  RETURN jsonb_build_object('saida_id',v_saida_id,'escopo',v_escopo);
END $function$

CREATE OR REPLACE FUNCTION public.ajustar_inventario_usoconsumo(p_item_id integer, p_novo_saldo integer, p_observacao text, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_item public.usoconsumo_item%ROWTYPE; v_diferenca integer; v_result jsonb;
BEGIN
  IF p_novo_saldo IS NULL OR p_novo_saldo<0 THEN RAISE EXCEPTION 'Novo saldo invalido.' USING ERRCODE='22023'; END IF;
  IF nullif(btrim(p_observacao),'') IS NULL THEN RAISE EXCEPTION 'Informe a justificativa do inventario.' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_item FROM public.usoconsumo_item WHERE id=p_item_id AND ativo FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Item nao encontrado.' USING ERRCODE='P0002'; END IF;
  v_diferenca:=p_novo_saldo-v_item.estoque;
  IF v_diferenca=0 THEN RETURN jsonb_build_object('item_id',p_item_id,'saldo',p_novo_saldo,'alterado',false); END IF;
  IF v_diferenca>0 THEN
    SELECT public.registrar_entrada_usoconsumo(
      jsonb_build_object('fiscal',false,'origem','INVENTARIO','tipo','DEVOLUCAO','escopo',v_item.escopo,'created_by',p_created_by),
      jsonb_build_array(jsonb_build_object('item_id',p_item_id,'quantidade',v_diferenca,'valor_unitario_compra',coalesce(v_item.ultimovalordecompra,v_item.precocompra,0))),
      '[]'::jsonb
    ) INTO v_result;
  ELSE
    SELECT public.registrar_saida_usoconsumo(
      jsonb_build_object('motivo','AJUSTE_INVENTARIO','observacao',p_observacao,'escopo',v_item.escopo,'created_by',p_created_by),
      jsonb_build_array(jsonb_build_object('item_id',p_item_id,'quantidade',abs(v_diferenca)))
    ) INTO v_result;
  END IF;
  RETURN v_result || jsonb_build_object('item_id',p_item_id,'saldo',p_novo_saldo,'alterado',true);
END $function$

CREATE OR REPLACE FUNCTION public.usoconsumo_validar_escopo_movimento()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_escopo_item text;
  v_escopo_cabecalho text;
BEGIN
  SELECT escopo INTO v_escopo_item
    FROM public.usoconsumo_item WHERE id = NEW.item_id;

  IF TG_ARGV[0] = 'ENTRADA' THEN
    SELECT escopo INTO v_escopo_cabecalho
      FROM public.usoconsumo_entrada WHERE id = NEW.entrada_id;
  ELSE
    SELECT escopo INTO v_escopo_cabecalho
      FROM public.usoconsumo_saida WHERE id = NEW.saida_id;
  END IF;

  IF v_escopo_cabecalho = 'MISTO' THEN
    IF v_escopo_item NOT IN ('USOCONSUMO', 'GERAL') THEN
      RAISE EXCEPTION 'O item % nao pertence a nenhum estoque simples valido.', NEW.item_id
        USING ERRCODE = '22023';
    END IF;
    RETURN NEW;
  END IF;

  IF v_escopo_item IS DISTINCT FROM v_escopo_cabecalho THEN
    RAISE EXCEPTION
      'O item % pertence ao estoque % e nao pode entrar em um movimento do estoque %.',
      NEW.item_id, v_escopo_item, v_escopo_cabecalho USING ERRCODE = '22023';
  END IF;

  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.chat_broadcast_reaction_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_mensagem_id uuid := case when tg_op = 'DELETE' then old.mensagem_id else new.mensagem_id end;
  v_conversa_id uuid;
begin
  select msg.conversa_id into v_conversa_id
  from public.chat_mensagem msg
  where msg.id = v_mensagem_id;

  if found then
    perform public.chat_broadcast_para_participantes(
      v_conversa_id,
      jsonb_build_object(
        'kind', 'reaction',
        'conversationId', v_conversa_id,
        'messageId', v_mensagem_id
      )
    );
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end;
$function$

CREATE OR REPLACE FUNCTION public.normalize_placa()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.placa := upper(regexp_replace(new.placa, '[^A-Za-z0-9]', '', 'g'));
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.criar_nfe_de_os(p_ordemservicoid integer)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$DECLARE
  v_nfe_id      bigint;
  v_numero      int;
  v_serie       int;
  v_modelo      public.enum_modelo_nfe;
  v_ambiente    public.enum_ambiente_nfe;
  v_chave       char(44);
  v_dataemissao timestamptz := now();
  v_cod_uf      text;
  v_cnpj_emit   text;
  v_ano         text;
  v_mes         text;
  v_mod         text;
  v_serie_str   text;
  v_numero_str  text;
  v_tp_emis     text;
  v_cod_nf      text;
  v_cdv         text;

  -- por enquanto fixo; depois você pode amarrar a empresa da OS
  v_empresaid   bigint := 1;

  v_cfg         nfe_config%ROWTYPE;
  v_emp         empresa%ROWTYPE;
BEGIN
  --------------------------------------------------------------------
  -- 1) Validar se a OS existe
  --------------------------------------------------------------------
  IF NOT EXISTS (SELECT 1 FROM ordemservico WHERE id = p_ordemservicoid) THEN
    RAISE EXCEPTION 'OS % não encontrada', p_ordemservicoid;
  END IF;

  --------------------------------------------------------------------
  -- 2) Carregar EMPRESA e NFE_CONFIG da empresa
  --------------------------------------------------------------------
  SELECT *
    INTO v_emp
  FROM empresa
  WHERE id = v_empresaid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Empresa % não encontrada na tabela EMPRESA', v_empresaid;
  END IF;

  SELECT *
    INTO v_cfg
  FROM nfe_config
  WHERE empresaid = v_empresaid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Configuração de NF-e (nfe_config) não encontrada para empresa %', v_empresaid;
  END IF;

  --------------------------------------------------------------------
  -- 3) Puxar parâmetros da config
  --------------------------------------------------------------------
  v_modelo   := v_cfg.modelo;
  v_serie    := v_cfg.serie;
  v_ambiente := v_cfg.ambiente;
  v_tp_emis  := v_cfg.tp_emis::text;   -- tp_emis é smallint na config

  -- cUF = 2 primeiros dígitos do código do município
  v_cod_uf := substring(coalesce(v_emp.codigomunicipio, '') FROM 1 FOR 2);

  IF v_cod_uf IS NULL OR length(v_cod_uf) <> 2 THEN
    RAISE EXCEPTION 'Código de município inválido para empresa % (codigomunicipio=%)',
      v_empresaid, v_emp.codigomunicipio;
  END IF;

  -- CNPJ somente números
  v_cnpj_emit := regexp_replace(coalesce(v_emp.cnpj, ''), '\D', '', 'g');

  IF length(v_cnpj_emit) <> 14 THEN
    RAISE EXCEPTION 'CNPJ da empresa % inválido (%). Deve ter 14 dígitos numéricos.',
      v_empresaid, v_emp.cnpj;
  END IF;

  v_ano := to_char(v_dataemissao, 'YY');
  v_mes := to_char(v_dataemissao, 'MM');
  v_mod := '55';  -- NF-e

  --------------------------------------------------------------------
  -- 4) Descobrir próximo número da NF-e a partir do nfe_config
  --    (ultimo_numero + 1)
  --------------------------------------------------------------------
  v_numero := v_cfg.ultimo_numero + 1;

  v_serie_str  := lpad(v_serie::text, 3, '0');
  v_numero_str := lpad(v_numero::text, 9, '0');

  --------------------------------------------------------------------
  -- 5) Gerar cNF (8 dígitos) aleatório
  --------------------------------------------------------------------
  v_cod_nf := lpad((floor(random() * 99999999))::int::text, 8, '0');

  --------------------------------------------------------------------
  -- 6) Montar chave de acesso SEM o DV
  --    cUF(2) + AAMM(4) + CNPJ(14) + mod(2) + série(3)
  --    + nNF(9) + tpEmis(1) + cNF(8)
  --------------------------------------------------------------------
  v_chave :=
    (v_cod_uf || v_ano || v_mes || v_cnpj_emit || v_mod ||
     v_serie_str || v_numero_str || v_tp_emis || v_cod_nf);

  --------------------------------------------------------------------
  -- 7) Calcular dígito verificador (módulo 11)
  --------------------------------------------------------------------
  DECLARE
    soma int := 0;
    peso int := 2;
    i    int;
    dig  int;
    ch_sem_dv text := v_chave;
  BEGIN
    FOR i IN REVERSE length(ch_sem_dv)..1 LOOP
      soma := soma + (substr(ch_sem_dv, i, 1)::int * peso);
      peso := peso + 1;
      IF peso > 9 THEN
        peso := 2;
      END IF;
    END LOOP;

    dig := 11 - (soma % 11);

    -- mantém a mesma regra que você já estava usando
    IF dig = 0 OR dig = 1 THEN
      dig := 0;
    END IF;

    v_cdv := dig::text;
  END;

  v_chave := v_chave || v_cdv;

  --------------------------------------------------------------------
  -- 8) Inserir na tabela NFE (RASCUNHO)
  --------------------------------------------------------------------
  INSERT INTO nfe (
    modelo,
    serie,
    numero,
    chave_acesso,
    ambiente,
    status,
    ordemservicoid,
    vendaid,
    clienteid,
    empresaid,
    dataemissao,
    total_produtos,
    total_servicos,
    total_nfe,
    xml_assinado,
    xml_autorizado
  )
  SELECT
    v_modelo,
    v_serie,
    v_numero,
    v_chave,
    v_ambiente,
    'RASCUNHO',
    os.id,
    NULL,
    os.clienteid,
    v_empresaid,          -- antes era 3 fixo
    v_dataemissao,
    0,
    0,
    0,
    NULL,
    NULL
  FROM ordemservico os
  WHERE os.id = p_ordemservicoid
  RETURNING id INTO v_nfe_id;

  --------------------------------------------------------------------
  -- 9) Atualizar nfe_config.ultimo_numero
  --------------------------------------------------------------------
  UPDATE nfe_config
     SET ultimo_numero = v_numero,
         updatedat     = now()
   WHERE id = v_cfg.id;

  RETURN v_nfe_id;
END;$function$

CREATE OR REPLACE FUNCTION public.criar_nfe_de_venda(p_vendaid integer)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$declare
  v_nfe_id      bigint;
  v_numero      int;
  v_serie       int;
  v_modelo      public.enum_modelo_nfe;
  v_ambiente    public.enum_ambiente_nfe;
  v_chave       char(44);
  v_dataemissao timestamptz := now();
  v_cod_uf      text;
  v_cnpj_emit   text;
  v_ano         text;
  v_mes         text;
  v_mod         text;
  v_serie_str   text;
  v_numero_str  text;
  v_tp_emis     text;
  v_cod_nf      text;
  v_cdv         text;

  -- por enquanto fixo; você pode amarrar depois
  v_empresaid   bigint := 1;

  v_cfg         public.nfe_config%rowtype;
  v_emp         public.empresa%rowtype;
  v_venda       public.venda%rowtype;
begin
  -- 1) Validar se a VENDA existe
  select * into v_venda
  from public.venda
  where id = p_vendaid;

  if not found then
    raise exception 'Venda % não encontrada', p_vendaid;
  end if;

  -- 2) Carregar EMPRESA e NFE_CONFIG
  select * into v_emp
  from public.empresa
  where id = v_empresaid;

  if not found then
    raise exception 'Empresa % não encontrada na tabela EMPRESA', v_empresaid;
  end if;

  select * into v_cfg
  from public.nfe_config
  where empresaid = v_empresaid;

  if not found then
    raise exception 'Configuração de NF-e (nfe_config) não encontrada para empresa %', v_empresaid;
  end if;

  -- 3) Puxar parâmetros da config
  v_modelo   := v_cfg.modelo;
  v_serie    := v_cfg.serie;
  v_ambiente := v_cfg.ambiente;
  v_tp_emis  := v_cfg.tp_emis::text;

  -- cUF = 2 primeiros dígitos do código do município
  v_cod_uf := substring(coalesce(v_emp.codigomunicipio, '') from 1 for 2);

  if v_cod_uf is null or length(v_cod_uf) <> 2 then
    raise exception 'Código de município inválido para empresa % (codigomunicipio=%)',
      v_empresaid, v_emp.codigomunicipio;
  end if;

  -- CNPJ somente números
  v_cnpj_emit := regexp_replace(coalesce(v_emp.cnpj, ''), '\D', '', 'g');

  if length(v_cnpj_emit) <> 14 then
    raise exception 'CNPJ da empresa % inválido (%). Deve ter 14 dígitos numéricos.',
      v_empresaid, v_emp.cnpj;
  end if;

  v_ano := to_char(v_dataemissao, 'YY');
  v_mes := to_char(v_dataemissao, 'MM');
  v_mod := '55';

  -- 4) Próximo número (ultimo_numero + 1)
  v_numero := v_cfg.ultimo_numero + 1;

  v_serie_str  := lpad(v_serie::text, 3, '0');
  v_numero_str := lpad(v_numero::text, 9, '0');

  -- 5) cNF (8 dígitos)
  v_cod_nf := lpad((floor(random() * 99999999))::int::text, 8, '0');

  -- 6) chave sem DV
  v_chave :=
    (v_cod_uf || v_ano || v_mes || v_cnpj_emit || v_mod ||
     v_serie_str || v_numero_str || v_tp_emis || v_cod_nf);

  -- 7) DV (módulo 11)
  declare
    soma int := 0;
    peso int := 2;
    i    int;
    dig  int;
    ch_sem_dv text := v_chave;
  begin
    for i in reverse length(ch_sem_dv)..1 loop
      soma := soma + (substr(ch_sem_dv, i, 1)::int * peso);
      peso := peso + 1;
      if peso > 9 then
        peso := 2;
      end if;
    end loop;

    dig := 11 - (soma % 11);

    if dig = 0 or dig = 1 then
      dig := 0;
    end if;

    v_cdv := dig::text;
  end;

  v_chave := v_chave || v_cdv;

  -- 8) Inserir NFE (RASCUNHO) vinculada à VENDA
  insert into public.nfe (
    modelo,
    serie,
    numero,
    chave_acesso,
    ambiente,
    status,
    ordemservicoid,
    vendaid,
    clienteid,
    empresaid,
    dataemissao,
    total_produtos,
    total_servicos,
    total_nfe,
    xml_assinado,
    xml_autorizado
  )
  values (
    v_modelo,
    v_serie,
    v_numero,
    v_chave,
    v_ambiente,
    'RASCUNHO',
    null,
    v_venda.id,
    v_venda.clienteid,
    v_empresaid,
    v_dataemissao,
    0,
    0,
    0,
    null,
    null
  )
  returning id into v_nfe_id;

  -- 9) Atualizar nfe_config.ultimo_numero
  update public.nfe_config
     set ultimo_numero = v_numero,
         updatedat     = now()
   where id = v_cfg.id;

  return v_nfe_id;
end;$function$

CREATE OR REPLACE FUNCTION public.chat_send_message(p_conversa_id uuid, p_remetente_id uuid, p_conteudo text, p_client_message_id uuid, p_tipo text DEFAULT 'TEXT'::text, p_reply_to_message_id uuid DEFAULT NULL::uuid, p_audio_path text DEFAULT NULL::text, p_audio_mime text DEFAULT NULL::text, p_audio_bytes integer DEFAULT NULL::integer, p_audio_duracao_ms integer DEFAULT NULL::integer)
 RETURNS TABLE(mensagem_id uuid, conversa_id uuid, remetente_id uuid, tipo text, conteudo text, client_message_id uuid, created_at timestamp with time zone, editada_em timestamp with time zone, excluida_para_todos_em timestamp with time zone, reply_to_message_id uuid, reply_snapshot_tipo text, reply_snapshot_conteudo text, reply_snapshot_remetente_nome text, audio_mime text, audio_bytes integer, audio_duracao_ms integer, criada boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_mensagem public.chat_mensagem%rowtype;
  v_criada boolean := false;
  v_tipo text := coalesce(nullif(btrim(p_tipo), ''), 'TEXT');
  v_conteudo text := coalesce(btrim(p_conteudo), '');
  v_reply public.chat_mensagem%rowtype;
  v_reply_tipo text;
  v_reply_conteudo text;
  v_reply_nome text;
begin
  if v_tipo not in ('TEXT', 'VOICE') then
    raise exception using errcode = '22023', message = 'CHAT_INVALID_MESSAGE_TYPE';
  end if;
  if p_client_message_id is null then
    raise exception using errcode = '22023', message = 'CHAT_INVALID_CLIENT_MESSAGE_ID';
  end if;

  if v_tipo = 'TEXT' then
    if length(v_conteudo) = 0 then
      raise exception using errcode = '22023', message = 'CHAT_EMPTY_MESSAGE';
    end if;
    if length(v_conteudo) > 5000 then
      raise exception using errcode = '22001', message = 'CHAT_MESSAGE_TOO_LONG';
    end if;
  else
    v_conteudo := '';
    if p_audio_path is null or btrim(p_audio_path) = '' or p_audio_mime is null then
      raise exception using errcode = '22023', message = 'CHAT_INVALID_AUDIO';
    end if;
    if p_audio_bytes is null or p_audio_bytes < 1 or p_audio_bytes > 10485760 then
      raise exception using errcode = '22023', message = 'CHAT_AUDIO_TOO_LARGE';
    end if;
    if p_audio_duracao_ms is null or p_audio_duracao_ms < 1 or p_audio_duracao_ms > 300000 then
      raise exception using errcode = '22023', message = 'CHAT_AUDIO_TOO_LONG';
    end if;
  end if;

  if not exists (
    select 1 from public.usuario where id = p_remetente_id and ativo = true
  ) then
    raise exception using errcode = '42501', message = 'INACTIVE_USER';
  end if;

  if not exists (
    select 1 from public.chat_participante participante
    where participante.conversa_id = p_conversa_id
      and participante.usuario_id = p_remetente_id
  ) then
    raise exception using errcode = '42501', message = 'CHAT_FORBIDDEN';
  end if;

  -- A citacao so pode apontar para uma mensagem viva da mesma conversa e
  -- visivel para quem responde. O recorte historico e montado aqui, no
  -- servidor: o navegador nunca informa autor nem conteudo citado.
  if p_reply_to_message_id is not null then
    select * into v_reply
    from public.chat_mensagem
    where id = p_reply_to_message_id;

    if not found or v_reply.conversa_id <> p_conversa_id then
      raise exception using errcode = '22023', message = 'CHAT_INVALID_REPLY_TARGET';
    end if;
    if v_reply.excluida_para_todos_em is not null then
      raise exception using errcode = '22023', message = 'CHAT_INVALID_REPLY_TARGET';
    end if;
    if exists (
      select 1 from public.chat_mensagem_oculta oculta
      where oculta.mensagem_id = v_reply.id and oculta.usuario_id = p_remetente_id
    ) then
      raise exception using errcode = '22023', message = 'CHAT_INVALID_REPLY_TARGET';
    end if;

    select u.nome::text into v_reply_nome
    from public.usuario u
    where u.id = v_reply.remetente_id;

    v_reply_tipo := v_reply.tipo;
    v_reply_conteudo := case
      when v_reply.tipo = 'VOICE' then ''
      else left(regexp_replace(v_reply.conteudo, '\s+', ' ', 'g'), 160)
    end;
  end if;

  insert into public.chat_mensagem(
    conversa_id,
    remetente_id,
    tipo,
    conteudo,
    client_message_id,
    reply_to_message_id,
    reply_snapshot_tipo,
    reply_snapshot_conteudo,
    reply_snapshot_remetente_nome,
    audio_path,
    audio_mime,
    audio_bytes,
    audio_duracao_ms
  ) values (
    p_conversa_id,
    p_remetente_id,
    v_tipo,
    v_conteudo,
    p_client_message_id,
    p_reply_to_message_id,
    v_reply_tipo,
    v_reply_conteudo,
    v_reply_nome,
    case when v_tipo = 'VOICE' then btrim(p_audio_path) end,
    case when v_tipo = 'VOICE' then p_audio_mime end,
    case when v_tipo = 'VOICE' then p_audio_bytes end,
    case when v_tipo = 'VOICE' then p_audio_duracao_ms end
  )
  on conflict on constraint chat_mensagem_idempotencia_key do nothing
  returning * into v_mensagem;

  if v_mensagem.id is null then
    select * into strict v_mensagem
    from public.chat_mensagem
    where chat_mensagem.conversa_id = p_conversa_id
      and chat_mensagem.remetente_id = p_remetente_id
      and chat_mensagem.client_message_id = p_client_message_id;
  else
    v_criada := true;
    update public.chat_conversa
    set last_message_at = v_mensagem.created_at,
        updated_at = v_mensagem.created_at
    where id = p_conversa_id;
  end if;

  return query
  select
    v_mensagem.id,
    v_mensagem.conversa_id,
    v_mensagem.remetente_id,
    v_mensagem.tipo,
    v_mensagem.conteudo,
    v_mensagem.client_message_id,
    v_mensagem.created_at,
    v_mensagem.editada_em,
    v_mensagem.excluida_para_todos_em,
    v_mensagem.reply_to_message_id,
    v_mensagem.reply_snapshot_tipo,
    v_mensagem.reply_snapshot_conteudo,
    v_mensagem.reply_snapshot_remetente_nome,
    v_mensagem.audio_mime,
    v_mensagem.audio_bytes,
    v_mensagem.audio_duracao_ms,
    v_criada;
end;
$function$

CREATE OR REPLACE FUNCTION public.chat_edit_message(p_usuario_id uuid, p_mensagem_id uuid, p_conteudo text, p_janela_segundos integer DEFAULT 900)
 RETURNS TABLE(mensagem_id uuid, conversa_id uuid, conteudo text, editada_em timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_mensagem public.chat_mensagem%rowtype;
  v_conteudo text := coalesce(btrim(p_conteudo), '');
  v_agora timestamptz := clock_timestamp();
begin
  if length(v_conteudo) = 0 then
    raise exception using errcode = '22023', message = 'CHAT_EMPTY_MESSAGE';
  end if;
  if length(v_conteudo) > 5000 then
    raise exception using errcode = '22001', message = 'CHAT_MESSAGE_TOO_LONG';
  end if;

  select * into v_mensagem
  from public.chat_mensagem
  where id = p_mensagem_id
  for update;

  if not found then
    raise exception using errcode = '22023', message = 'CHAT_MESSAGE_NOT_FOUND';
  end if;
  if v_mensagem.remetente_id <> p_usuario_id then
    raise exception using errcode = '42501', message = 'CHAT_FORBIDDEN';
  end if;
  if v_mensagem.tipo <> 'TEXT' then
    raise exception using errcode = '22023', message = 'CHAT_MESSAGE_NOT_EDITABLE';
  end if;
  if v_mensagem.excluida_para_todos_em is not null then
    raise exception using errcode = '22023', message = 'CHAT_MESSAGE_NOT_EDITABLE';
  end if;
  if v_agora > v_mensagem.created_at + make_interval(secs => greatest(0, p_janela_segundos)) then
    raise exception using errcode = '22023', message = 'CHAT_EDIT_WINDOW_EXPIRED';
  end if;

  if v_mensagem.conteudo = v_conteudo then
    return query select v_mensagem.id, v_mensagem.conversa_id, v_mensagem.conteudo, v_mensagem.editada_em;
    return;
  end if;

  insert into public.chat_mensagem_edicao(mensagem_id, conteudo_anterior, editado_por)
  values (v_mensagem.id, v_mensagem.conteudo, p_usuario_id);

  -- created_at nao muda: a edicao nunca reordena a timeline nem move a
  -- conversa para o topo como se fosse mensagem nova.
  update public.chat_mensagem
  set conteudo = v_conteudo,
      editada_em = v_agora
  where id = v_mensagem.id
  returning * into v_mensagem;

  return query select v_mensagem.id, v_mensagem.conversa_id, v_mensagem.conteudo, v_mensagem.editada_em;
end;
$function$

CREATE OR REPLACE FUNCTION public.chat_delete_message_for_me(p_usuario_id uuid, p_mensagem_id uuid)
 RETURNS TABLE(mensagem_id uuid, conversa_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_conversa_id uuid;
begin
  select msg.conversa_id into v_conversa_id
  from public.chat_mensagem msg
  where msg.id = p_mensagem_id;

  if not found then
    raise exception using errcode = '22023', message = 'CHAT_MESSAGE_NOT_FOUND';
  end if;

  if not exists (
    select 1 from public.chat_participante p
    where p.conversa_id = v_conversa_id and p.usuario_id = p_usuario_id
  ) then
    raise exception using errcode = '42501', message = 'CHAT_FORBIDDEN';
  end if;

  insert into public.chat_mensagem_oculta(mensagem_id, usuario_id)
  values (p_mensagem_id, p_usuario_id)
  on conflict do nothing;

  -- Somente as sessoes do proprio usuario precisam saber.
  perform public.chat_broadcast_para_participantes(
    v_conversa_id,
    jsonb_build_object(
      'kind', 'message-updated',
      'conversationId', v_conversa_id,
      'messageId', p_mensagem_id
    ),
    p_usuario_id
  );

  return query select p_mensagem_id, v_conversa_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.chat_delete_message_for_everyone(p_usuario_id uuid, p_mensagem_id uuid, p_janela_segundos integer DEFAULT 900)
 RETURNS TABLE(mensagem_id uuid, conversa_id uuid, excluida_para_todos_em timestamp with time zone, audio_path text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_mensagem public.chat_mensagem%rowtype;
  v_agora timestamptz := clock_timestamp();
  v_audio_path text;
begin
  select * into v_mensagem
  from public.chat_mensagem
  where id = p_mensagem_id
  for update;

  if not found then
    raise exception using errcode = '22023', message = 'CHAT_MESSAGE_NOT_FOUND';
  end if;
  if v_mensagem.remetente_id <> p_usuario_id then
    raise exception using errcode = '42501', message = 'CHAT_FORBIDDEN';
  end if;
  if v_mensagem.excluida_para_todos_em is not null then
    return query
    select v_mensagem.id, v_mensagem.conversa_id, v_mensagem.excluida_para_todos_em, null::text;
    return;
  end if;
  if v_agora > v_mensagem.created_at + make_interval(secs => greatest(0, p_janela_segundos)) then
    raise exception using errcode = '22023', message = 'CHAT_DELETE_WINDOW_EXPIRED';
  end if;

  v_audio_path := v_mensagem.audio_path;

  if v_audio_path is not null then
    insert into public.chat_audio_pendente_remocao(path, conversa_id)
    values (v_audio_path, v_mensagem.conversa_id)
    on conflict (path) do nothing;
  end if;

  -- Exclusao logica: a linha continua para nao quebrar cursor de leitura,
  -- paginacao nem respostas que citem esta mensagem.
  update public.chat_mensagem
  set conteudo = '',
      excluida_para_todos_em = v_agora,
      excluida_para_todos_por = p_usuario_id,
      editada_em = null,
      reply_snapshot_tipo = null,
      reply_snapshot_conteudo = null,
      reply_snapshot_remetente_nome = null,
      audio_path = null,
      audio_mime = null,
      audio_bytes = null,
      audio_duracao_ms = null
  where id = v_mensagem.id
  returning * into v_mensagem;

  -- Decisao: as reacoes de uma mensagem excluida para todos sao removidas.
  delete from public.chat_reacao where chat_reacao.mensagem_id = v_mensagem.id;

  return query
  select v_mensagem.id, v_mensagem.conversa_id, v_mensagem.excluida_para_todos_em, v_audio_path;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_radio_station_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.chat_set_reaction(p_usuario_id uuid, p_mensagem_id uuid, p_reacao text)
 RETURNS TABLE(mensagem_id uuid, conversa_id uuid, reacoes jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_mensagem public.chat_mensagem%rowtype;
  v_reacao text := upper(coalesce(btrim(p_reacao), ''));
begin
  if v_reacao not in ('CORACAO', 'LEGAL', 'FELIZ', 'TRISTE') then
    raise exception using errcode = '22023', message = 'CHAT_INVALID_REACTION';
  end if;

  select * into v_mensagem from public.chat_mensagem where id = p_mensagem_id;
  if not found then
    raise exception using errcode = '22023', message = 'CHAT_MESSAGE_NOT_FOUND';
  end if;

  if not exists (
    select 1 from public.chat_participante p
    where p.conversa_id = v_mensagem.conversa_id and p.usuario_id = p_usuario_id
  ) then
    raise exception using errcode = '42501', message = 'CHAT_FORBIDDEN';
  end if;

  if v_mensagem.excluida_para_todos_em is not null then
    raise exception using errcode = '22023', message = 'CHAT_MESSAGE_UNAVAILABLE';
  end if;

  if exists (
    select 1 from public.chat_mensagem_oculta oculta
    where oculta.mensagem_id = p_mensagem_id and oculta.usuario_id = p_usuario_id
  ) then
    raise exception using errcode = '22023', message = 'CHAT_MESSAGE_UNAVAILABLE';
  end if;

  insert into public.chat_reacao(mensagem_id, usuario_id, reacao)
  values (p_mensagem_id, p_usuario_id, v_reacao)
  on conflict on constraint chat_reacao_unica_key do update
  set reacao = excluded.reacao,
      updated_at = clock_timestamp();

  return query
  select p_mensagem_id,
         v_mensagem.conversa_id,
         public.chat_reacoes_da_mensagem(p_mensagem_id, p_usuario_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.chat_clear_reaction(p_usuario_id uuid, p_mensagem_id uuid)
 RETURNS TABLE(mensagem_id uuid, conversa_id uuid, reacoes jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_conversa_id uuid;
begin
  select msg.conversa_id into v_conversa_id
  from public.chat_mensagem msg
  where msg.id = p_mensagem_id;

  if not found then
    raise exception using errcode = '22023', message = 'CHAT_MESSAGE_NOT_FOUND';
  end if;

  if not exists (
    select 1 from public.chat_participante p
    where p.conversa_id = v_conversa_id and p.usuario_id = p_usuario_id
  ) then
    raise exception using errcode = '42501', message = 'CHAT_FORBIDDEN';
  end if;

  delete from public.chat_reacao
  where chat_reacao.mensagem_id = p_mensagem_id
    and chat_reacao.usuario_id = p_usuario_id;

  return query
  select p_mensagem_id,
         v_conversa_id,
         public.chat_reacoes_da_mensagem(p_mensagem_id, p_usuario_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.chat_audio_access(p_usuario_id uuid, p_mensagem_id uuid)
 RETURNS TABLE(conversa_id uuid, audio_path text, audio_mime text, audio_duracao_ms integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_mensagem public.chat_mensagem%rowtype;
begin
  select * into v_mensagem from public.chat_mensagem where id = p_mensagem_id;
  if not found then
    raise exception using errcode = '22023', message = 'CHAT_MESSAGE_NOT_FOUND';
  end if;

  if not exists (
    select 1 from public.chat_participante p
    where p.conversa_id = v_mensagem.conversa_id and p.usuario_id = p_usuario_id
  ) then
    raise exception using errcode = '42501', message = 'CHAT_FORBIDDEN';
  end if;

  if v_mensagem.excluida_para_todos_em is not null
    or v_mensagem.tipo <> 'VOICE'
    or v_mensagem.audio_path is null
    or exists (
      select 1 from public.chat_mensagem_oculta oculta
      where oculta.mensagem_id = p_mensagem_id and oculta.usuario_id = p_usuario_id
    )
  then
    raise exception using errcode = '22023', message = 'CHAT_AUDIO_UNAVAILABLE';
  end if;

  return query
  select v_mensagem.conversa_id,
         v_mensagem.audio_path,
         v_mensagem.audio_mime,
         v_mensagem.audio_duracao_ms;
end;
$function$

