CREATE OR REPLACE FUNCTION public.registrar_lancamento_de_eventos(p_payload jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_os_id integer := nullif(p_payload->>'ordemservicoid', '')::integer;
  v_created_by uuid := nullif(p_payload->>'created_by', '')::uuid;
  v_pendente boolean := coalesce((p_payload->>'pendente')::boolean, true);
  v_data timestamptz := coalesce(nullif(p_payload->>'data', '')::timestamptz, now());
  v_metodo public.metodo_pagamento := nullif(p_payload->>'metodopagamento', '')::public.metodo_pagamento;
  v_categoria text := coalesce(nullif(p_payload->>'categoria', ''), 'NAO RELACIONADO');
  v_categoria_id integer := nullif(p_payload->>'categoria_id', '')::integer;
  v_plano_id integer := nullif(p_payload->>'plano_de_conta_id', '')::integer;
  v_centro_id integer := nullif(p_payload->>'centro_custo_id', '')::integer;
  v_fornecedor_id integer := nullif(p_payload->>'fornecedor_id', '')::integer;
  v_banco_id bigint := nullif(p_payload->>'banco_id', '')::bigint;
  v_nome text := coalesce(nullif(btrim(p_payload->>'nomepagador'), ''), 'Despesa interna');
  v_cpfcnpj text := coalesce(nullif(btrim(p_payload->>'cpfcnpjpagador'), ''), 'NAO INFORMADO');
  v_ids bigint[];
  v_os_ids integer[];
  v_qtd_os integer;
  v_qtd_vendas integer;
  v_os_efetiva integer;
  v_qtd integer;
  v_soma_eventos numeric(14,2);
  v_soma_linhas numeric(14,2);
  v_maus text;
  v_grupo_id bigint;
  v_descricao_grupo text;
  v_descricao text;
  v_total_parcelas integer;
  v_parcela record;
BEGIN
  IF jsonb_typeof(p_payload->'eventos_ids') <> 'array'
     OR jsonb_array_length(p_payload->'eventos_ids') = 0 THEN
    RAISE EXCEPTION 'Selecione ao menos uma despesa para lancar.' USING ERRCODE = 'P0001';
  END IF;
  IF jsonb_typeof(p_payload->'linhas') <> 'array'
     OR jsonb_array_length(p_payload->'linhas') = 0 THEN
    RAISE EXCEPTION 'Informe as parcelas do lancamento.' USING ERRCODE = 'P0001';
  END IF;

  SELECT array_agg(DISTINCT item::text::bigint)
    INTO v_ids
    FROM jsonb_array_elements(p_payload->'eventos_ids') AS item;

  -- Trava todas as despesas ate o fim desta transacao: duas telas lancando
  -- grupos que dividem uma despesa serializam aqui, e a segunda encontra o
  -- vinculo ja preenchido.
  PERFORM 1 FROM public.eventos_financeiros WHERE id = ANY (v_ids) FOR UPDATE;

  SELECT count(*), round(coalesce(sum(e.valor), 0), 2)
    INTO v_qtd, v_soma_eventos
    FROM public.eventos_financeiros e WHERE e.id = ANY (v_ids);

  IF v_qtd <> coalesce(array_length(v_ids, 1), 0) THEN
    RAISE EXCEPTION 'Uma ou mais despesas selecionadas nao existem mais.' USING ERRCODE = 'P0002';
  END IF;

  SELECT string_agg(e.id::text, ', ' ORDER BY e.id) INTO v_maus
    FROM public.eventos_financeiros e
   WHERE e.id = ANY (v_ids)
     AND (e.status <> 'ATIVO' OR e.transacaoid IS NOT NULL OR e.lancamento_id IS NOT NULL);
  IF v_maus IS NOT NULL THEN
    RAISE EXCEPTION 'Despesa(s) % ja foi(ram) lancada(s) no financeiro ou cancelada(s).', v_maus
      USING ERRCODE = 'P0001';
  END IF;

  SELECT string_agg(e.id::text, ', ' ORDER BY e.id) INTO v_maus
    FROM public.eventos_financeiros e
   WHERE e.id = ANY (v_ids) AND NOT e.pode_gerar_transacao;
  IF v_maus IS NOT NULL THEN
    RAISE EXCEPTION 'Despesa(s) % e(sao) lancamento(s) automatico(s) e nao gera(m) transacao.', v_maus
      USING ERRCODE = 'P0001';
  END IF;

  SELECT string_agg(e.id::text, ', ' ORDER BY e.id) INTO v_maus
    FROM public.eventos_financeiros e
   WHERE e.id = ANY (v_ids) AND e.natureza <> 'DESPESA';
  IF v_maus IS NOT NULL THEN
    RAISE EXCEPTION 'Lancamento(s) % nao e(sao) despesa.', v_maus USING ERRCODE = 'P0001';
  END IF;

  -- Além de OS, aceita comissão de venda com documento existente.
  -- Entradas e transações avulsas continuam fora deste caminho.
  SELECT string_agg(e.id::text, ', ' ORDER BY e.id) INTO v_maus
    FROM public.eventos_financeiros e
   WHERE e.id = ANY (v_ids) AND e.ordemservicoid IS NULL
     AND NOT (e.source_type IS NOT DISTINCT FROM 'VENDA' AND e.origem = 'COMISSAO'
              AND EXISTS (SELECT 1 FROM public.venda v WHERE v.id = e.source_id));
  IF v_maus IS NOT NULL THEN
    RAISE EXCEPTION 'Despesa(s) % nao pertence(m) a uma OS ou comissao de venda.', v_maus
      USING ERRCODE = 'P0001';
  END IF;

  -- Quem informa a OS continua preso a ela. E o caminho do painel da propria OS,
  -- que sabe de qual ordem esta falando; afrouxar ali so esconderia um engano.
  IF v_os_id IS NOT NULL THEN
    SELECT string_agg(e.id::text, ', ' ORDER BY e.id) INTO v_maus
      FROM public.eventos_financeiros e
     WHERE e.id = ANY (v_ids) AND e.ordemservicoid IS DISTINCT FROM v_os_id;
    IF v_maus IS NOT NULL THEN
      RAISE EXCEPTION 'Despesa(s) % nao pertence(m) a esta OS.', v_maus USING ERRCODE = 'P0001';
    END IF;
  END IF;

  SELECT array_agg(DISTINCT e.ordemservicoid) FILTER (WHERE e.ordemservicoid IS NOT NULL),
         count(DISTINCT e.source_id) FILTER (WHERE e.source_type = 'VENDA' AND e.ordemservicoid IS NULL)
    INTO v_os_ids, v_qtd_vendas
    FROM public.eventos_financeiros e WHERE e.id = ANY (v_ids);

  v_qtd_os := coalesce(array_length(v_os_ids, 1), 0);
  -- Uma OS so: grupo e parcelas ficam carimbados com ela, como sempre foram.
  -- Varias: nao ha resposta unica, e inventar uma seria pior que a ausencia.
  v_os_efetiva := CASE WHEN v_qtd_os = 1 AND v_qtd_vendas = 0 THEN v_os_ids[1] ELSE NULL END;

  SELECT round(coalesce(sum((item->>'valor')::numeric), 0), 2)
    INTO v_soma_linhas
    FROM jsonb_array_elements(p_payload->'linhas') AS item;

  IF v_soma_linhas <> v_soma_eventos THEN
    RAISE EXCEPTION 'A soma das parcelas (%) difere da soma das despesas selecionadas (%).',
      v_soma_linhas, v_soma_eventos USING ERRCODE = 'P0001';
  END IF;

  v_descricao_grupo := coalesce(
    nullif(btrim(p_payload->>'descricao'), ''),
    CASE WHEN v_os_efetiva IS NOT NULL
      THEN 'Despesas da OS #' || v_os_efetiva
      WHEN v_qtd_os = 0 THEN 'Comissões de ' || v_qtd_vendas || ' venda(s)'
      ELSE 'Despesas de ' || v_qtd_os || ' OS e ' || v_qtd_vendas || ' venda(s)'
    END);

  INSERT INTO public.lancamento_de_eventos (ordemservicoid, descricao, created_by)
  VALUES (v_os_efetiva, v_descricao_grupo, v_created_by)
  RETURNING id INTO v_grupo_id;

  SELECT max((item->>'total_parcelas')::integer) INTO v_total_parcelas
    FROM jsonb_array_elements(p_payload->'linhas') AS item;
  v_total_parcelas := greatest(coalesce(v_total_parcelas, 1), 1);

  FOR v_parcela IN
    SELECT (item->>'parcela')::integer AS numero,
           round((item->>'valor')::numeric, 2) AS valor,
           round(coalesce((item->>'valor_liquido')::numeric,
                          (item->>'valor')::numeric), 2) AS valor_liquido,
           nullif(item->>'vencimento_em', '') AS vencimento
      FROM jsonb_array_elements(p_payload->'linhas') AS item
     ORDER BY 1
  LOOP
    v_descricao := v_descricao_grupo;
    IF v_total_parcelas > 1 THEN
      v_descricao := v_descricao || ' - Parcela ' || v_parcela.numero || '/' || v_total_parcelas;
    END IF;

    INSERT INTO public.transacao (
      descricao, valor, "valorLiquido", data, vencimento_em, metodopagamento,
      categoria, categoria_id, plano_de_conta_id, centro_custo_id, tipo,
      fornecedor_id, banco_id, nomepagador, cpfcnpjpagador, pendente, pago_em,
      ordemservicoid, lancamento_id, created_by, baixado_por
    ) VALUES (
      v_descricao,
      v_parcela.valor,
      v_parcela.valor_liquido,
      coalesce(v_parcela.vencimento::timestamptz, v_data),
      v_parcela.vencimento::timestamptz,
      v_metodo, v_categoria, v_categoria_id, v_plano_id, v_centro_id,
      'DESPESA'::public.tipos_transacao,
      v_fornecedor_id,
      CASE WHEN v_pendente THEN NULL ELSE v_banco_id END,
      v_nome, v_cpfcnpj,
      v_pendente,
      CASE WHEN v_pendente THEN NULL ELSE v_data END,
      v_os_efetiva, v_grupo_id, v_created_by,
      CASE WHEN v_pendente THEN NULL ELSE v_created_by END
    );
  END LOOP;

  UPDATE public.eventos_financeiros
     SET status = 'CONVERTIDO', lancamento_id = v_grupo_id, updated_at = now()
   WHERE id = ANY (v_ids);

  RETURN v_grupo_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.excluir_lancamento_de_eventos(p_id bigint, p_deleted_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_grupo public.lancamento_de_eventos%ROWTYPE;
  v_os_finalizadas text;
  v_os_ids integer[];
  v_baixadas integer;
  v_parcelas integer;
  v_despesas integer;
BEGIN
  SELECT * INTO v_grupo FROM public.lancamento_de_eventos WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lancamento #% nao encontrado.', p_id USING ERRCODE = 'P0002';
  END IF;

  -- Guarda 1: dinheiro que ja saiu. A exclusao apaga o titulo, nao a baixa: o
  -- saldo do banco subiria sozinho, sem que nada tenha acontecido no mundo.
  -- Mesma razao da trava individual do DELETE de transacao, mas valendo para o
  -- grupo — com uma parcela paga, nem as pendentes saem.
  SELECT count(*) INTO v_baixadas
    FROM public.transacao t
   WHERE t.lancamento_id = p_id AND t.is_deleted = false AND t.pendente = false;

  IF v_baixadas > 0 THEN
    RAISE EXCEPTION
      'Este lancamento tem % parcela(s) ja paga(s). Tire a baixa do fluxo de caixa antes de excluir.',
      v_baixadas USING ERRCODE = 'P0001';
  END IF;

  -- As ordens saem dos eventos, e nao do carimbo do grupo: num lancamento
  -- multi-OS ele e nulo, e ler dali passaria batido por todas elas. Precisa vir
  -- antes do UPDATE que solta o vinculo, senao nao ha mais o que ler.
  SELECT array_agg(DISTINCT e.ordemservicoid)
    INTO v_os_ids
    FROM public.eventos_financeiros e
   WHERE e.lancamento_id = p_id AND e.ordemservicoid IS NOT NULL;

  -- Guarda 2: OS finalizada. Mesmo conjunto de status que
  -- tg_reconciliar_eventos_ao_finalizar_os trata como fim de linha.
  SELECT string_agg(o.id::text, ', ' ORDER BY o.id) INTO v_os_finalizadas
    FROM public.ordemservico o
   WHERE o.id = ANY (coalesce(v_os_ids, ARRAY[]::integer[]))
     AND o.status::text IN ('CONCLUIDO', 'SEM_COBRANCA', 'CANCELADO');

  IF v_os_finalizadas IS NOT NULL THEN
    RAISE EXCEPTION
      'A(s) OS #% ja foi(ram) finalizada(s). Reabra a OS para desfazer este lancamento.',
      v_os_finalizadas USING ERRCODE = 'P0001';
  END IF;

  SELECT count(*) INTO v_parcelas
    FROM public.transacao t WHERE t.lancamento_id = p_id;

  -- As despesas voltam a prevista ANTES de o grupo sumir. A FK e ON DELETE SET
  -- NULL, entao o vinculo cairia sozinho — mas o status nao, e uma despesa
  -- CONVERTIDO sem vinculo nenhum seria uma despesa presa para sempre.
  UPDATE public.eventos_financeiros
     SET status = 'ATIVO', lancamento_id = NULL, updated_at = now()
   WHERE lancamento_id = p_id;

  GET DIAGNOSTICS v_despesas = ROW_COUNT;

  -- As parcelas caem por CASCADE.
  DELETE FROM public.lancamento_de_eventos WHERE id = p_id;

  RETURN jsonb_build_object(
    'id', p_id,
    'ordemservicoid', v_grupo.ordemservicoid,
    'ordemservicoids', to_jsonb(coalesce(v_os_ids, ARRAY[]::integer[])),
    'parcelas_removidas', v_parcelas,
    'despesas_revertidas', v_despesas
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.ajustar_valores_transacao(p_itens jsonb, p_alterado_por uuid DEFAULT NULL::uuid, p_motivo text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET lock_timeout TO '5s'
AS $function$
DECLARE
  v_ids bigint[];
  v_total int;
  v_qtd_os int;
  v_qtd_venda int;
  v_qtd_avulsa int;
  v_os bigint;
  v_venda bigint;
  v_esperado int;
  v_soma_atual bigint;
  v_soma_nova bigint;
  v_item record;
  v_anterior public.transacao%ROWTYPE;
  v_resultado jsonb := '[]'::jsonb;
BEGIN
  IF p_itens IS NULL
     OR jsonb_typeof(p_itens) <> 'array'
     OR jsonb_array_length(p_itens) = 0 THEN
    RAISE EXCEPTION 'Informe ao menos uma transacao para ajustar.' USING ERRCODE = '22023';
  END IF;

  SELECT array_agg((item->>'id')::bigint)
    INTO v_ids
    FROM jsonb_array_elements(p_itens) AS item;

  v_total := array_length(v_ids, 1);

  IF v_total <> (SELECT count(DISTINCT x) FROM unnest(v_ids) AS x) THEN
    RAISE EXCEPTION 'A mesma transacao foi enviada mais de uma vez.' USING ERRCODE = '22023';
  END IF;

  -- Trava as linhas antes de qualquer leitura de soma, e sempre na mesma ordem:
  -- e a ordem que impede duas chamadas simultaneas de se travarem uma a outra.
  BEGIN
    PERFORM 1
       FROM public.transacao
      WHERE id = ANY(v_ids)
        AND is_deleted = false
      ORDER BY id
      FOR UPDATE;
  EXCEPTION
    WHEN lock_not_available THEN
      RAISE EXCEPTION
        'Outra pessoa esta salvando esta transacao neste momento. Espere alguns segundos e tente de novo.'
        USING ERRCODE = '55P03';
  END;

  SELECT
    count(*),
    count(DISTINCT ordemservicoid) FILTER (WHERE ordemservicoid IS NOT NULL),
    count(DISTINCT vendaid) FILTER (WHERE vendaid IS NOT NULL),
    count(*) FILTER (WHERE ordemservicoid IS NULL AND vendaid IS NULL),
    max(ordemservicoid),
    max(vendaid),
    coalesce(sum(round(valor * 100)), 0)
  INTO v_esperado, v_qtd_os, v_qtd_venda, v_qtd_avulsa, v_os, v_venda, v_soma_atual
  FROM public.transacao
  WHERE id = ANY(v_ids)
    AND is_deleted = false;

  IF v_esperado <> v_total THEN
    RAISE EXCEPTION 'Transacao nao encontrada.' USING ERRCODE = 'P0002';
  END IF;

  /*
   * Concorrencia: os valores precisam estar exatamente como estavam quando a
   * tela foi aberta. `coalesce(nullif("valorLiquido", 0), valor)` espelha o
   * `valorLiquidoEfetivo` do cliente — registro antigo com liquido nulo ou
   * zerado vale o bruto, dos dois lados, senao a comparacao acusaria conflito
   * onde nao existe.
   */
  IF EXISTS (
    SELECT 1
      FROM jsonb_array_elements(p_itens) AS item
      JOIN public.transacao t ON t.id = (item->>'id')::bigint
     WHERE item->>'valorAnterior' IS NULL
        OR item->>'valorLiquidoAnterior' IS NULL
        OR round(t.valor * 100) <> round((item->>'valorAnterior')::numeric * 100)
        OR round(coalesce(nullif(t."valorLiquido", 0), t.valor) * 100)
             <> round((item->>'valorLiquidoAnterior')::numeric * 100)
  ) THEN
    RAISE EXCEPTION
      'Os valores mudaram depois que esta tela foi aberta. Recarregue e refaca o rateio.'
      USING ERRCODE = '40001';
  END IF;

  IF v_qtd_os + v_qtd_venda > 1 OR ((v_qtd_os + v_qtd_venda) = 1 AND v_qtd_avulsa > 0) THEN
    RAISE EXCEPTION 'O ajuste precisa ficar dentro de um unico documento.' USING ERRCODE = '22023';
  END IF;

  IF v_qtd_os = 1 OR v_qtd_venda = 1 THEN
    -- Com documento: exige o grupo completo, senao a soma nao pode ser garantida.
    SELECT count(*)
      INTO v_esperado
      FROM public.transacao
     WHERE is_deleted = false
       AND upper(tipo::text) = 'RECEITA'
       AND evento_financeiro_id IS NULL
       AND ((v_qtd_os = 1 AND ordemservicoid = v_os)
         OR (v_qtd_venda = 1 AND vendaid = v_venda));

    IF v_esperado <> v_total THEN
      RAISE EXCEPTION
        'O ajuste precisa incluir os % pagamentos do documento; vieram %.', v_esperado, v_total
        USING ERRCODE = '22023';
    END IF;

    SELECT coalesce(sum(round((item->>'valor')::numeric * 100)), 0)
      INTO v_soma_nova
      FROM jsonb_array_elements(p_itens) AS item;

    IF v_soma_nova <> v_soma_atual THEN
      RAISE EXCEPTION
        'A soma dos valores brutos deve continuar em R$ %; foi informado R$ %.',
        replace(to_char(v_soma_atual / 100.0, 'FM999999990.00'), '.', ','),
        replace(to_char(v_soma_nova / 100.0, 'FM999999990.00'), '.', ',')
        USING ERRCODE = '22023';
    END IF;
  ELSIF v_total > 1 THEN
    RAISE EXCEPTION 'Lancamentos avulsos sao ajustados um a um.' USING ERRCODE = '22023';
  END IF;

  /*
   * Diminui (ou mantem) antes de aumentar.
   *
   * `validar_limite_pagamento_os` checa, a cada UPDATE de linha, a soma da OS
   * com o estado corrente das outras linhas — nao ve o resultado final do lote,
   * so o que ja foi escrito nesta transacao ate ali. Como a soma do grupo inteiro
   * e constante (checado acima), processar toda linha com `valor <= anterior`
   * primeiro banca essa folga antes de qualquer linha subir; dai em diante, uma
   * sequencia de incrementos que fecha exatamente no total nunca tem um passo
   * intermediario maior que o total. Sem isto, uma parcela subindo um centavo
   * podia ser escrita antes da parcela que desce compensar, e o gatilho recusava
   * um estado transitorio que o usuario nunca pediu.
   *
   * As linhas ja estao travadas (lock acima, em ordem de id): reordenar so estes
   * UPDATEs nao adquire lock novo, entao nao reabre o deadlock de 20260817120000.
   */
  FOR v_item IN
    SELECT (item->>'id')::bigint AS id,
           round((item->>'valor')::numeric, 2) AS valor,
           round(coalesce(item->>'valorLiquido', item->>'valor')::numeric, 2) AS valor_liquido,
           round((item->>'valor')::numeric, 2)
             - round((item->>'valorAnterior')::numeric, 2) AS delta
      FROM jsonb_array_elements(p_itens) AS item
     ORDER BY delta, id
  LOOP
    IF v_item.valor <= 0 THEN
      RAISE EXCEPTION 'O valor bruto da transacao % deve ser maior que zero.', v_item.id
        USING ERRCODE = '22023';
    END IF;

    IF v_item.valor_liquido <= 0 THEN
      RAISE EXCEPTION 'O valor liquido da transacao % deve ser maior que zero.', v_item.id
        USING ERRCODE = '22023';
    END IF;

    IF v_item.valor_liquido > v_item.valor THEN
      RAISE EXCEPTION 'O liquido da transacao % nao pode ser maior que o bruto.', v_item.id
        USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_anterior FROM public.transacao WHERE id = v_item.id;

    UPDATE public.transacao
       SET valor = v_item.valor,
           "valorLiquido" = v_item.valor_liquido,
           updated_at = now()
     WHERE id = v_item.id;

    INSERT INTO public.transacao_valor_historico (
      transacao_id, valor_anterior, valor_novo,
      valor_liquido_anterior, valor_liquido_novo, alterado_por, motivo
    ) VALUES (
      v_item.id, v_anterior.valor, v_item.valor,
      v_anterior."valorLiquido", v_item.valor_liquido, p_alterado_por, nullif(btrim(p_motivo), '')
    );

    v_resultado := v_resultado || jsonb_build_object(
      'id', v_item.id,
      'valor', v_item.valor,
      'valorLiquido', v_item.valor_liquido
    );
  END LOOP;

  /*
   * Nao revalidamos o status da OS/venda de proposito. Com documento, a soma dos
   * brutos e constante; e como toda linha precisa terminar com valor > 0, o total
   * ja baixado tambem nao pode cruzar o total devido em nenhum sentido. Ou seja,
   * o status nao tem como mudar por causa de um rateio.
   */

  RETURN jsonb_build_object('itens', v_resultado);
END;
$function$

CREATE OR REPLACE FUNCTION public.central_evento_ordemservico()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_tenant integer := public.central_operacional_tenant_id();
  v_tipo text;
  v_titulo text;
  v_prioridade text := 'INFO';
begin
  if new.is_deleted or new.migracao_referencia is not null then
    return new;
  end if;

  if tg_op = 'INSERT' then
    v_tipo := 'OS_CRIADA';
    v_titulo := 'OS #' || new.id::text || ' criada';
  elsif old.status is distinct from new.status then
    case new.status::text
      when 'EM_ANDAMENTO' then
        v_tipo := 'OS_INICIO_EXECUCAO';
        v_titulo := 'OS #' || new.id::text || ' iniciou execucao';
      when 'PAGAMENTO' then
        v_tipo := 'OS_AGUARDANDO_PAGAMENTO';
        v_titulo := 'OS #' || new.id::text || ' aguarda pagamento';
      when 'CONCLUIDO' then
        v_tipo := 'OS_FINALIZADA';
        v_titulo := 'OS #' || new.id::text || ' finalizada';
      when 'CANCELADO' then
        v_tipo := 'OS_CANCELADA';
        v_titulo := 'OS #' || new.id::text || ' cancelada';
        v_prioridade := 'ATENCAO';
      else
        return new;
    end case;
  else
    return new;
  end if;

  perform public.central_emitir_evento_operacional(
    v_tenant,
    v_tipo,
    'ORDENS',
    'ORDEM_SERVICO',
    new.id::text,
    v_titulo,
    null,
    null,
    null,
    v_prioridade,
    jsonb_build_object('status', new.status::text),
    case when tg_op = 'INSERT'
      then 'OS_CRIADA:' || new.id::text
      else v_tipo || ':' || new.id::text || ':' || txid_current()::text
    end,
    now()
  );
  return new;
exception when others then
  raise warning '[central] evento de OS ignorado: %', sqlerrm;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.registrar_transferencia_entre_contas(p_valor numeric, p_data timestamp with time zone, p_banco_origem_id bigint, p_banco_destino_id bigint, p_metodopagamento text, p_descricao text DEFAULT NULL::text, p_plano_de_conta_id integer DEFAULT NULL::integer, p_centro_custo_id integer DEFAULT NULL::integer, p_criado_por uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_metodo public.metodo_pagamento;
  v_valor numeric(14,2);
  v_origem text;
  v_destino text;
  v_categoria_id integer;
  v_transferencia_id bigint;
  v_saida_id bigint;
  v_entrada_id bigint;
  v_descricao text;
BEGIN
  IF p_valor IS NULL OR round(p_valor, 2) <= 0 THEN
    RAISE EXCEPTION 'O valor da transferencia deve ser maior que zero.'
      USING ERRCODE = '22023';
  END IF;
  v_valor := round(p_valor, 2);

  IF p_data IS NULL THEN
    RAISE EXCEPTION 'Data da transferencia obrigatoria.' USING ERRCODE = '22023';
  END IF;

  IF p_banco_origem_id IS NULL OR p_banco_destino_id IS NULL THEN
    RAISE EXCEPTION 'Informe a conta de origem e a de destino.' USING ERRCODE = '22023';
  END IF;

  IF p_banco_origem_id = p_banco_destino_id THEN
    RAISE EXCEPTION
      'A conta de origem e a de destino sao a mesma: nao ha transferencia a registrar.'
      USING ERRCODE = '22023';
  END IF;

  IF nullif(btrim(p_metodopagamento), '') IS NULL THEN
    RAISE EXCEPTION 'Metodo de pagamento obrigatorio.' USING ERRCODE = '22023';
  END IF;

  BEGIN
    v_metodo := btrim(p_metodopagamento)::public.metodo_pagamento;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'Metodo de pagamento invalido: %.', btrim(p_metodopagamento)
      USING ERRCODE = '22023';
  END;

  SELECT titulo INTO v_origem FROM public.bancoconta WHERE id = p_banco_origem_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Conta de origem nao encontrada.' USING ERRCODE = 'P0002';
  END IF;

  SELECT titulo INTO v_destino FROM public.bancoconta WHERE id = p_banco_destino_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Conta de destino nao encontrada.' USING ERRCODE = 'P0002';
  END IF;

  v_origem := coalesce(nullif(btrim(v_origem), ''), 'conta #' || p_banco_origem_id);
  v_destino := coalesce(nullif(btrim(v_destino), ''), 'conta #' || p_banco_destino_id);
  v_descricao := nullif(btrim(coalesce(p_descricao, '')), '');

  SELECT id INTO v_categoria_id
    FROM public.categoriatransacao WHERE codigo_sistema = 'TRANSFERENCIA' LIMIT 1;

  INSERT INTO public.transacao_transferencia
    (valor, data, banco_origem_id, banco_destino_id, metodopagamento,
     descricao, criado_por)
  VALUES
    (v_valor, p_data, p_banco_origem_id, p_banco_destino_id, v_metodo,
     v_descricao, p_criado_por)
  RETURNING id INTO v_transferencia_id;

  INSERT INTO public.transacao (
    descricao, valor, valor_base, "valorLiquido",
    valor_acrescimos, valor_descontos,
    data, competencia_em, vencimento_em, pago_em,
    tipo, pendente, banco_id, metodopagamento,
    nomepagador, cpfcnpjpagador,
    categoria_id, plano_de_conta_id, centro_custo_id,
    transferencia_id, created_by, baixado_por
  ) VALUES (
    coalesce(v_descricao, 'Transferencia para ' || v_destino),
    v_valor, v_valor, v_valor, 0, 0,
    p_data, p_data, p_data, p_data,
    'SAQUE'::public.tipos_transacao, false, p_banco_origem_id, v_metodo,
    v_destino, 'NAO INFORMADO',
    v_categoria_id, p_plano_de_conta_id, p_centro_custo_id,
    v_transferencia_id, p_criado_por, p_criado_por
  ) RETURNING id INTO v_saida_id;

  INSERT INTO public.transacao (
    descricao, valor, valor_base, "valorLiquido",
    valor_acrescimos, valor_descontos,
    data, competencia_em, vencimento_em, pago_em,
    tipo, pendente, banco_id, metodopagamento,
    nomepagador, cpfcnpjpagador,
    categoria_id, plano_de_conta_id, centro_custo_id,
    transferencia_id, created_by, baixado_por
  ) VALUES (
    coalesce(v_descricao, 'Transferencia de ' || v_origem),
    v_valor, v_valor, v_valor, 0, 0,
    p_data, p_data, p_data, p_data,
    'DEPOSITO'::public.tipos_transacao, false, p_banco_destino_id, v_metodo,
    v_origem, 'NAO INFORMADO',
    v_categoria_id, p_plano_de_conta_id, p_centro_custo_id,
    v_transferencia_id, p_criado_por, p_criado_por
  ) RETURNING id INTO v_entrada_id;

  RETURN jsonb_build_object(
    'transferencia_id', v_transferencia_id,
    'saida_id', v_saida_id,
    'entrada_id', v_entrada_id,
    'valor', v_valor,
    'banco_origem', v_origem,
    'banco_destino', v_destino
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.registrar_entrada_fiscal_personalizada(p_destino text, p_entrada jsonb, p_item jsonb, p_itens_fiscais jsonb, p_custo_total numeric, p_transacoes jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_destino text := upper(btrim(coalesce(p_destino, '')));
  v_documento_id bigint;
  v_resultado jsonb;
  v_entrada_id bigint;
  v_usoconsumo_entrada_id bigint;
  v_linha jsonb;
  v_numero_item integer;
  v_quantidade_fiscal numeric(14,4);
  v_numeros integer[] := ARRAY[]::integer[];
  v_created_by uuid := nullif(p_entrada->>'created_by', '')::uuid;
BEGIN
  IF v_destino NOT IN ('ESTOQUE', 'USOCONSUMO', 'GERAL') THEN
    RAISE EXCEPTION 'Destino da entrada personalizada invalido.' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_item) <> 'object' THEN
    RAISE EXCEPTION 'Informe o item consolidado da entrada personalizada.' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_itens_fiscais) <> 'array' OR jsonb_array_length(p_itens_fiscais) = 0 THEN
    RAISE EXCEPTION 'A entrada personalizada exige os itens originais da NF-e.' USING ERRCODE = '22023';
  END IF;
  IF p_custo_total IS NULL OR p_custo_total < 0 THEN
    RAISE EXCEPTION 'O custo total da entrada personalizada e invalido.' USING ERRCODE = '22023';
  END IF;

  v_documento_id := CASE
    WHEN v_destino = 'ESTOQUE'
      THEN nullif(p_entrada->>'fiscal_dfe_documento_id', '')::bigint
    ELSE nullif(p_entrada->>'documento_fiscal_recebido_id', '')::bigint
  END;
  IF v_documento_id IS NULL THEN
    RAISE EXCEPTION 'Informe o documento fiscal recebido.' USING ERRCODE = '22023';
  END IF;

  -- Serializa entradas personalizadas concorrentes da mesma NF-e. Entradas
  -- normais continuam protegidas pelo indice unico das apropriacoes.
  PERFORM 1 FROM public.fiscal_dfe_documento
    WHERE id = v_documento_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Documento fiscal recebido nao encontrado.' USING ERRCODE = 'P0002';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.fiscal_dfe_item_apropriacao
     WHERE documento_id = v_documento_id AND cancelada_at IS NULL
  ) THEN
    RAISE EXCEPTION 'A entrada personalizada exige uma NF-e ainda nao apropriada.' USING ERRCODE = '23505';
  END IF;

  -- Valida nItem e quantidade antes de criar qualquer saldo.
  FOR v_linha IN SELECT value FROM jsonb_array_elements(p_itens_fiscais)
  LOOP
    v_numero_item := nullif(v_linha->>'numero_item', '')::integer;
    v_quantidade_fiscal := nullif(v_linha->>'quantidade', '')::numeric;
    IF v_numero_item IS NULL OR v_numero_item < 1 OR v_numero_item > 990
       OR v_quantidade_fiscal IS NULL OR v_quantidade_fiscal <= 0 THEN
      RAISE EXCEPTION 'Os itens originais da NF-e sao invalidos.' USING ERRCODE = '22023';
    END IF;
    IF v_numero_item = ANY(v_numeros) THEN
      RAISE EXCEPTION 'O item fiscal % foi informado mais de uma vez.', v_numero_item
        USING ERRCODE = '22023';
    END IF;
    v_numeros := array_append(v_numeros, v_numero_item);
  END LOOP;

  IF v_destino = 'ESTOQUE' THEN
    SELECT public.registrar_entrada_confirmada(
      p_entrada,
      jsonb_build_array(p_item),
      p_transacoes
    ) INTO v_resultado;
    v_entrada_id := (v_resultado->>'entrada_id')::bigint;
  ELSE
    -- Sem o documento durante a chamada, o motor de uso/consumo nao tenta criar
    -- a apropriacao linha a linha. O vinculo volta logo abaixo, na mesma transacao.
    SELECT public.registrar_entrada_usoconsumo(
      p_entrada - 'documento_fiscal_recebido_id',
      jsonb_build_array(p_item),
      p_transacoes
    ) INTO v_resultado;
    v_usoconsumo_entrada_id := (v_resultado->>'entrada_id')::bigint;

    UPDATE public.usoconsumo_entrada
       SET documento_fiscal_recebido_id = v_documento_id
     WHERE id = v_usoconsumo_entrada_id;
  END IF;

  FOR v_linha IN SELECT value FROM jsonb_array_elements(p_itens_fiscais)
  LOOP
    INSERT INTO public.fiscal_dfe_item_apropriacao(
      documento_id, numero_item, destino, entrada_id,
      usoconsumo_entrada_id, quantidade, created_by
    ) VALUES (
      v_documento_id,
      (v_linha->>'numero_item')::integer,
      CASE WHEN v_destino = 'ESTOQUE' THEN 'PRODUTO' ELSE 'USOCONSUMO' END,
      v_entrada_id,
      v_usoconsumo_entrada_id,
      (v_linha->>'quantidade')::numeric,
      v_created_by
    );
  END LOOP;

  INSERT INTO public.entrada_fiscal_personalizada(
    documento_id, destino, entrada_id, usoconsumo_entrada_id,
    itens_originais, custo_total_estoque, created_by
  ) VALUES (
    v_documento_id, v_destino, v_entrada_id, v_usoconsumo_entrada_id,
    p_itens_fiscais, round(p_custo_total, 2), v_created_by
  );

  RETURN v_resultado || jsonb_build_object(
    'destino', v_destino,
    'entrada_id', v_entrada_id,
    'usoconsumo_entrada_id', v_usoconsumo_entrada_id,
    'custo_total_estoque', round(p_custo_total, 2)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.validar_ositem_historico()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if tg_op in ('UPDATE', 'DELETE')
     and coalesce(current_setting('app.permitir_alterar_os_migrada', true), '') <> 'on' then
    raise exception 'Itens de OS historica sao somente leitura.'
      using errcode = '55000';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  if not exists (
    select 1
      from public.ordemservico os
     where os.id = new.ordemservicoid
       and os.migracao_referencia is not null
       and os.status::text = 'CONCLUIDO'
  ) then
    raise exception 'O item historico exige uma OS migrada e concluida.'
      using errcode = '23514';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.cancelar_entrada_confirmada(p_entrada_id bigint, p_motivo text, p_cancelada_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.estoque_definir_contexto(
    'ENTRADA', p_entrada_id, 'Entrada #' || p_entrada_id || ' - cancelada', p_cancelada_by
  );
  RETURN public.cancelar_entrada_confirmada_interna(p_entrada_id, p_motivo, p_cancelada_by);
END;
$function$

CREATE OR REPLACE FUNCTION public.validar_assinatura_ultima_versao_checklist()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  doc public.checklist_documento%rowtype;
begin
  select * into doc
  from public.checklist_documento
  where id = new.documento_id;

  if not found then
    raise exception 'Documento de checklist nao encontrado.' using errcode = '23503';
  end if;

  if exists (
    select 1
    from public.checklist_documento posterior
    where posterior.ordemservico_id = doc.ordemservico_id
      and posterior.tipo = doc.tipo
      and posterior.versao > doc.versao
  ) then
    raise exception 'Somente a versao mais recente do checklist pode ser assinada.' using errcode = '55000';
  end if;

  if new.snapshot_hash is distinct from doc.snapshot_hash then
    raise exception 'A assinatura nao corresponde ao snapshot armazenado.' using errcode = '55000';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.proteger_checklist_documento()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'UPDATE' then
    -- Unico campo mutavel: o elo com a versao anterior. Comparar o resto como
    -- jsonb mantem a trava valida quando novas colunas forem adicionadas.
    if to_jsonb(new) - 'versao_anterior_id' is distinct from to_jsonb(old) - 'versao_anterior_id' then
      raise exception 'Versoes de checklist sao imutaveis.' using errcode = '55000';
    end if;
    return new;
  end if;

  -- Segunda barreira para o documento assinado: mesmo chamando a funcao de
  -- exclusao, ela precisa ter declarado a intencao na mesma transacao.
  if exists (
    select 1 from public.checklist_documento_assinatura a where a.documento_id = old.id
  ) and coalesce(current_setting('app.checklist_exclusao_assinada', true), 'off') <> 'on' then
    raise exception 'Documento assinado nao pode ser excluido.' using errcode = '55000';
  end if;

  return old;
end;
$function$

CREATE OR REPLACE FUNCTION public.proteger_registro_documental_assinado()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'UPDATE' then
    raise exception 'Registro documental imutavel.' using errcode = '55000';
