CREATE OR REPLACE FUNCTION public.excluir_checklist_documento(p_public_id uuid, p_permitir_assinado boolean DEFAULT false)
 RETURNS TABLE(documento_id bigint, codigo text, versao integer, tipo text, ordemservico_id bigint, assinado boolean, arquivo_path text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  doc public.checklist_documento%rowtype;
  v_assinado boolean;
  v_arquivo text;
begin
  select * into doc
  from public.checklist_documento
  where public_id = p_public_id;

  if not found then
    raise exception 'Versao de checklist nao encontrada.' using errcode = 'P0002';
  end if;

  select exists (
    select 1 from public.checklist_documento_assinatura a where a.documento_id = doc.id
  ) into v_assinado;

  if v_assinado and not coalesce(p_permitir_assinado, false) then
    raise exception 'Documento assinado nao pode ser excluido.' using errcode = '55000';
  end if;

  select f.storage_path into v_arquivo
  from public.checklist_documento_arquivo f
  where f.documento_id = doc.id;

  -- Quem apontava para esta versao passa a apontar para a anterior dela: o
  -- historico continua encadeado sem o elo removido.
  update public.checklist_documento
     set versao_anterior_id = doc.versao_anterior_id
   where versao_anterior_id = doc.id;

  if v_assinado then
    perform set_config('app.checklist_exclusao_assinada', 'on', true);
  end if;

  delete from public.checklist_documento where id = doc.id;

  perform set_config('app.checklist_exclusao_assinada', 'off', true);

  documento_id := doc.id;
  codigo := doc.codigo;
  versao := doc.versao;
  tipo := doc.tipo;
  ordemservico_id := doc.ordemservico_id;
  assinado := v_assinado;
  arquivo_path := v_arquivo;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.recalcular_comissao_osservico(p_ordemservicoid integer, p_servicoid integer)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_subtotal numeric;
  v_qtd int;
  v_gera_comissao boolean;
  v_total_itens numeric := 0;
  v_total_os_sem_frete numeric := 0;
  v_fator numeric := 1;
  v_base_liquida numeric;
  v_percent_maior numeric := 0;
  v_execucao_encerrada boolean := true;
BEGIN
  SELECT coalesce(s.subtotal, 0) INTO v_subtotal
    FROM public.osservico s
   WHERE s.ordemservicoid = p_ordemservicoid AND s.servicoid = p_servicoid;
  SELECT coalesce(sv.gera_comissao, true) INTO v_gera_comissao
    FROM public.servico sv WHERE sv.id = p_servicoid;
  SELECT count(*) INTO v_qtd FROM public.osservico_realizador r
   WHERE r.ordemservicoid = p_ordemservicoid AND r.servicoid = p_servicoid;
  IF v_qtd <= 0 THEN RETURN; END IF;

  SELECT greatest(coalesce(o.orcamentototal, 0) - coalesce(o.valor_frete, 0), 0),
         coalesce((SELECT sum(coalesce(op.subtotal, 0)) FROM public.osproduto op WHERE op.ordemservicoid = o.id), 0)
           + coalesce((SELECT sum(coalesce(opa.subtotal, 0)) FROM public.osproduto_avulso opa WHERE opa.ordemservicoid = o.id), 0)
           + coalesce((SELECT sum(coalesce(os.subtotal, 0)) FROM public.osservico os WHERE os.ordemservicoid = o.id), 0),
         o.execucao_fim_em IS NOT NULL
    INTO v_total_os_sem_frete, v_total_itens, v_execucao_encerrada
    FROM public.ordemservico o WHERE o.id = p_ordemservicoid;

  -- Enquanto o servico nao foi entregue, quem manda e o cadastro de hoje: a
  -- taxa que vale e a do dia da entrega, nao a do dia da atribuicao.
  IF NOT v_execucao_encerrada THEN
    PERFORM public.recarimbar_comissao_osservico(p_ordemservicoid, p_servicoid);
  END IF;

  IF v_total_itens > 0 THEN v_fator := v_total_os_sem_frete / v_total_itens; END IF;
  v_base_liquida := round(v_subtotal * v_fator / v_qtd, 2);

  -- O maior percentual entre quem executou. Com um realizador so, e a taxa dele
  -- e nada muda em relacao ao comportamento anterior.
  SELECT coalesce(max(coalesce(r.comissao_percent_aplicada, 0)), 0)
    INTO v_percent_maior
    FROM public.osservico_realizador r
   WHERE r.ordemservicoid = p_ordemservicoid AND r.servicoid = p_servicoid;

  -- Servico que nao comissiona zera a taxa efetiva, e nao so o valor: assim a
  -- linha zerada no relatorio se explica sozinha.
  IF NOT coalesce(v_gera_comissao, true) THEN
    v_percent_maior := 0;
  END IF;

  UPDATE public.osservico_realizador r
     SET valor_base = v_base_liquida,
         comissao_percent_efetiva = v_percent_maior,
         valor_comissao = round(v_base_liquida * v_percent_maior / 100.0, 2),
         updated_at = now()
   WHERE r.ordemservicoid = p_ordemservicoid AND r.servicoid = p_servicoid;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_recalc_comissao_realizadores()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_os integer;
  v_servico integer;
BEGIN
  IF tg_op = 'DELETE' THEN
    v_os := old.ordemservicoid;
    v_servico := old.servicoid;
  ELSE
    v_os := new.ordemservicoid;
    v_servico := new.servicoid;
  END IF;

  PERFORM public.recalcular_comissao_osservico(v_os, v_servico);
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.criar_convite_assinatura_checklist(p_documento_public_id uuid, p_convite_public_id uuid, p_cpf_hmac text, p_cpf_cifrado text, p_senha_hash text, p_senha_salt text, p_senha_parametros jsonb, p_expira_em timestamp with time zone, p_criado_por uuid, p_request_ip text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text)
 RETURNS TABLE(convite_id bigint, convite_public_id uuid, documento_id bigint, criado_em timestamp with time zone, expira_em timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  doc public.checklist_documento%rowtype;
  novo public.checklist_documento_convite_assinatura%rowtype;
begin
  select * into doc
  from public.checklist_documento
  where public_id = p_documento_public_id
  for update;

  if not found then
    raise exception 'Versao do checklist nao encontrada.' using errcode = 'P0002';
  end if;
  if exists (
    select 1 from public.checklist_documento posterior
    where posterior.ordemservico_id = doc.ordemservico_id
      and posterior.tipo = doc.tipo
      and posterior.versao > doc.versao
  ) then
    raise exception 'Somente a versao mais recente pode receber convite.' using errcode = '55000';
  end if;
  if exists (
    select 1 from public.checklist_documento_assinatura assinatura
    where assinatura.documento_id = doc.id
  ) then
    raise exception 'Esta versao ja foi assinada.' using errcode = '55000';
  end if;
  if p_expira_em <= now() then
    raise exception 'A validade do convite deve estar no futuro.' using errcode = '22023';
  end if;

  update public.checklist_documento_convite_assinatura convite
     set revogado_em = now(),
         revogado_por = p_criado_por,
         motivo_revogacao = 'REEMITIDO'
   where convite.documento_id = doc.id
     and convite.revogado_em is null
     and convite.consumido_em is null;

  insert into public.checklist_documento_convite_assinatura (
    public_id,
    documento_id,
    cpf_hmac,
    cpf_cifrado,
    senha_hash,
    senha_salt,
    senha_parametros,
    expira_em,
    criado_por
  ) values (
    p_convite_public_id,
    doc.id,
    p_cpf_hmac,
    p_cpf_cifrado,
    p_senha_hash,
    p_senha_salt,
    p_senha_parametros,
    p_expira_em,
    p_criado_por
  ) returning * into novo;

  insert into public.checklist_documento_evento (
    documento_id, tipo, usuario_id, request_ip, user_agent, metadados
  ) values (
    doc.id,
    'CONVITE_ASSINATURA_CRIADO',
    p_criado_por,
    case when p_request_ip is null then null else p_request_ip::inet end,
    left(p_user_agent, 1000),
    jsonb_build_object(
      'convitePublicId', novo.public_id,
      'expiraEm', novo.expira_em
    )
  );

  convite_id := novo.id;
  convite_public_id := novo.public_id;
  documento_id := novo.documento_id;
  criado_em := novo.criado_em;
  expira_em := novo.expira_em;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.revogar_convite_assinatura_checklist(p_documento_public_id uuid, p_revogado_por uuid, p_request_ip text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  doc_id bigint;
  convite_id bigint;
begin
  select id into doc_id
  from public.checklist_documento
  where public_id = p_documento_public_id;
  if not found then
    raise exception 'Versao do checklist nao encontrada.' using errcode = 'P0002';
  end if;

  select id into convite_id
  from public.checklist_documento_convite_assinatura
  where documento_id = doc_id
    and revogado_em is null
    and consumido_em is null
  order by criado_em desc, id desc
  limit 1
  for update;

  if convite_id is null then return false; end if;

  update public.checklist_documento_convite_assinatura
     set revogado_em = now(),
         revogado_por = p_revogado_por,
         motivo_revogacao = 'MANUAL'
   where id = convite_id;

  insert into public.checklist_documento_evento (
    documento_id, tipo, usuario_id, request_ip, user_agent, metadados
  ) values (
    doc_id,
    'CONVITE_ASSINATURA_REVOGADO',
    p_revogado_por,
    case when p_request_ip is null then null else p_request_ip::inet end,
    left(p_user_agent, 1000),
    jsonb_build_object('conviteId', convite_id, 'motivo', 'MANUAL')
  );
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.assinar_checklist_remotamente(p_convite_public_id uuid, p_snapshot_hash text, p_signatario_nome text, p_signatario_documento text, p_signatario_qualidade text, p_qualidade_outro text, p_declaracao text, p_declaracao_hash text, p_assinatura_path text, p_assinatura_hash text, p_assinatura_vinculo_hash text, p_request_ip text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text)
 RETURNS TABLE(assinatura_id bigint, documento_id bigint, assinado_em timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  convite public.checklist_documento_convite_assinatura%rowtype;
  doc public.checklist_documento%rowtype;
  nova_assinatura public.checklist_documento_assinatura%rowtype;
  v_documento_id bigint;
begin
  select convite_base.documento_id into v_documento_id
  from public.checklist_documento_convite_assinatura convite_base
  where convite_base.public_id = p_convite_public_id;
  if not found then
    raise exception 'Convite invalido ou indisponivel.' using errcode = 'P0002';
  end if;

  select documento.* into doc
  from public.checklist_documento documento
  where documento.id = v_documento_id
  for update;

  select convite_registro.* into convite
  from public.checklist_documento_convite_assinatura convite_registro
  where convite_registro.public_id = p_convite_public_id
    and convite_registro.documento_id = doc.id
  for update;
  if not found then
    raise exception 'Convite invalido ou indisponivel.' using errcode = 'P0002';
  end if;

  if convite.revogado_em is not null
    or convite.consumido_em is not null
    or convite.expira_em <= now() then
    raise exception 'Convite invalido ou indisponivel.' using errcode = '55000';
  end if;
  if p_snapshot_hash is distinct from doc.snapshot_hash then
    raise exception 'O snapshot do checklist foi alterado.' using errcode = '55000';
  end if;
  if exists (
    select 1 from public.checklist_documento posterior
    where posterior.ordemservico_id = doc.ordemservico_id
      and posterior.tipo = doc.tipo
      and posterior.versao > doc.versao
  ) then
    raise exception 'Existe uma versao posterior deste checklist.' using errcode = '55000';
  end if;
  if exists (
    select 1 from public.checklist_documento_assinatura assinatura
    where assinatura.documento_id = doc.id
  ) then
    raise exception 'Esta versao ja foi assinada.' using errcode = '23505';
  end if;

  insert into public.checklist_documento_assinatura (
    documento_id,
    signatario_nome,
    signatario_documento,
    signatario_qualidade,
    qualidade_outro,
    declaracao,
    declaracao_hash,
    metodo,
    assinatura_path,
    assinatura_hash,
    assinatura_vinculo_hash,
    snapshot_hash,
    operador_usuario_id,
    request_ip,
    user_agent,
    assinado_em,
    convite_assinatura_id
  ) values (
    doc.id,
    p_signatario_nome,
    p_signatario_documento,
    p_signatario_qualidade,
    p_qualidade_outro,
    p_declaracao,
    p_declaracao_hash,
    'REMOTA_DESENHADA',
    p_assinatura_path,
    p_assinatura_hash,
    p_assinatura_vinculo_hash,
    doc.snapshot_hash,
    null,
    case when p_request_ip is null then null else p_request_ip::inet end,
    left(p_user_agent, 1000),
    now(),
    convite.id
  ) returning * into nova_assinatura;

  update public.checklist_documento_convite_assinatura convite_registro
     set consumido_em = nova_assinatura.assinado_em,
         ultimo_acesso_em = coalesce(convite_registro.ultimo_acesso_em, nova_assinatura.assinado_em)
   where convite_registro.id = convite.id;

  insert into public.checklist_documento_evento (
    documento_id, tipo, request_ip, user_agent, metadados
  ) values (
    doc.id,
    'ASSINATURA_REMOTA_REGISTRADA',
    case when p_request_ip is null then null else p_request_ip::inet end,
    left(p_user_agent, 1000),
    jsonb_build_object(
      'convitePublicId', convite.public_id,
      'metodo', 'REMOTA_DESENHADA',
      'autenticacao', 'LINK_CPF_SENHA',
      'assinaturaHash', p_assinatura_hash,
      'assinaturaVinculoHash', p_assinatura_vinculo_hash
    )
  );

  assinatura_id := nova_assinatura.id;
  documento_id := doc.id;
  assinado_em := nova_assinatura.assinado_em;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.validar_tipo_entrada()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_escopo text := TG_ARGV[0];
  v_tipo text := upper(btrim(coalesce(NEW.tipo, '')));
BEGIN
  IF v_tipo = '' THEN
    RAISE EXCEPTION 'Informe o tipo da entrada.' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.tipos_entrada
    WHERE codigo = v_tipo AND ativo AND escopo IN (v_escopo, 'AMBOS')
  ) THEN
    RAISE EXCEPTION 'Tipo de entrada invalido: %.', v_tipo USING ERRCODE = '22023';
  END IF;
  NEW.tipo := v_tipo;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_notificar_telegram_nfe()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_evento text;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;
  IF coalesce(NEW.is_deleted, false) THEN
    RETURN NEW;
  END IF;
  -- Homologacao e teste: nota de teste nao vira aviso. Rascunho antigo sem
  -- ambiente gravado conta como producao para nao engolir aviso legitimo.
  IF coalesce(NEW.ambiente::text, 'PRODUCAO') <> 'PRODUCAO' THEN
    RETURN NEW;
  END IF;

  v_evento := CASE upper(btrim(coalesce(NEW.status::text, '')))
    WHEN 'AUTORIZADA' THEN 'NFE_AUTORIZADA'
    WHEN 'REJEITADA' THEN 'NFE_REJEITADA'
    WHEN 'DENEGADA' THEN 'NFE_DENEGADA'
    WHEN 'CANCELADA' THEN 'NFE_CANCELADA'
    WHEN 'RESULTADO_INCERTO' THEN 'NFE_RESULTADO_INCERTO'
    ELSE NULL
  END;

  IF v_evento IS NULL THEN
    RETURN NEW;
  END IF;

  PERFORM public.fn_enfileirar_notificacao_fiscal(
    'NFE', NEW.id::bigint, v_evento, 'NFE:' || NEW.id::text
  );
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_notificar_telegram_dfe()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_chave text;
BEGIN
  -- Evento e manifestacao entram no mesmo razao; so NF-e de terceiro vira aviso.
  IF upper(btrim(coalesce(NEW.tipo_documento, ''))) NOT IN ('RESUMO_NFE', 'PROC_NFE') THEN
    RETURN NEW;
  END IF;

  v_chave := coalesce(nullif(btrim(coalesce(NEW.chave_acesso, '')), ''), 'NSU-' || NEW.nsu);

  IF TG_OP = 'INSERT' THEN
    -- A distribuicao devolve ate 90 dias de documentos na primeira sincronizacao
    -- da empresa. Avisar sobre todos eles seria uma enxurrada de mensagens sobre
    -- notas antigas: so entra o que foi emitido nos ultimos dias, que e o caso em
    -- que alguem ainda precisa manifestar ou dar entrada.
    IF NEW.data_emissao IS NOT NULL AND NEW.data_emissao < now() - interval '3 days' THEN
      RETURN NEW;
    END IF;

    PERFORM public.fn_enfileirar_notificacao_fiscal(
      'DFE', NEW.id::bigint, 'DFE_RECEBIDA', 'DFE:' || v_chave
    );
    RETURN NEW;
  END IF;

  -- 101 cancelada, 110 denegada: a nota deixou de valer depois de ja ter sido
  -- reconhecida aqui, e quem deu entrada nela precisa saber.
  IF NEW.status IS DISTINCT FROM OLD.status
     AND btrim(coalesce(NEW.status, '')) IN ('101', '110') THEN
    PERFORM public.fn_enfileirar_notificacao_fiscal(
      'DFE', NEW.id::bigint, 'DFE_CANCELADA', 'DFE-CANC:' || v_chave
    );
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_transacao_movimento_registrado()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF (old.pendente IS DISTINCT FROM new.pendente AND new.pendente = false)
     OR (old.data IS DISTINCT FROM new.data) THEN
    new.movimento_registrado_em := now();
  END IF;

  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.entrada_fiscal_personalizada_completar_auditoria()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item record;
BEGIN
  NEW.modalidade := coalesce(nullif(NEW.modalidade, ''), 'INTEGRAL');

  IF NEW.destino = 'ESTOQUE' AND NEW.entrada_id IS NOT NULL
     AND (NEW.produto_id IS NULL OR NEW.quantidade_personalizada IS NULL
          OR NEW.custo_unitario IS NULL OR NEW.item_destino_snapshot IS NULL) THEN
    SELECT ei.produto_id, ei.quantidade, ei.valor_unitario_compra, ei.titulo,
           ei.referencia, ei.unidade, e.valor_total
      INTO v_item
      FROM public.entradaitens ei
      JOIN public.entrada e ON e.id = ei.entrada_id
     WHERE ei.entrada_id = NEW.entrada_id
     ORDER BY ei.id
     LIMIT 1;
    IF FOUND THEN
      NEW.produto_id := coalesce(NEW.produto_id, v_item.produto_id);
      NEW.quantidade_personalizada := coalesce(NEW.quantidade_personalizada, v_item.quantidade);
      NEW.custo_unitario := coalesce(NEW.custo_unitario, v_item.valor_unitario_compra);
      NEW.valor_fiscal_documento := coalesce(NEW.valor_fiscal_documento, v_item.valor_total);
      NEW.item_destino_snapshot := coalesce(
        NEW.item_destino_snapshot,
        jsonb_build_object(
          'id', v_item.produto_id,
          'titulo', v_item.titulo,
          'referencia', v_item.referencia,
          'unidade', v_item.unidade
        )
      );
    END IF;
  ELSIF NEW.destino IN ('USOCONSUMO', 'GERAL') AND NEW.usoconsumo_entrada_id IS NOT NULL
     AND (NEW.usoconsumo_item_id IS NULL OR NEW.quantidade_personalizada IS NULL
          OR NEW.custo_unitario IS NULL OR NEW.item_destino_snapshot IS NULL) THEN
    SELECT ui.item_id, ui.quantidade, ui.valor_unitario_compra, ui.titulo,
           ui.referencia, ui.unidade, ue.valor_total
      INTO v_item
      FROM public.usoconsumo_entrada_item ui
      JOIN public.usoconsumo_entrada ue ON ue.id = ui.entrada_id
     WHERE ui.entrada_id = NEW.usoconsumo_entrada_id
     ORDER BY ui.id
     LIMIT 1;
    IF FOUND THEN
      NEW.usoconsumo_item_id := coalesce(NEW.usoconsumo_item_id, v_item.item_id);
      NEW.quantidade_personalizada := coalesce(NEW.quantidade_personalizada, v_item.quantidade);
      NEW.custo_unitario := coalesce(NEW.custo_unitario, v_item.valor_unitario_compra);
      NEW.valor_fiscal_documento := coalesce(NEW.valor_fiscal_documento, v_item.valor_total);
      NEW.item_destino_snapshot := coalesce(
        NEW.item_destino_snapshot,
        jsonb_build_object(
          'id', v_item.item_id,
          'titulo', v_item.titulo,
          'referencia', v_item.referencia,
          'unidade', v_item.unidade
        )
      );
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.registrar_entrada_fiscal_hibrida(p_entrada_produto jsonb, p_itens_produto jsonb, p_entrada_usoconsumo jsonb, p_itens_usoconsumo jsonb, p_apropriacoes jsonb, p_auditoria jsonb, p_custo_total numeric, p_custo_personalizado numeric, p_total_documento numeric, p_transacoes jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tem_produto boolean := jsonb_typeof(p_itens_produto) = 'array'
    AND jsonb_array_length(p_itens_produto) > 0;
  v_tem_uso boolean := jsonb_typeof(p_itens_usoconsumo) = 'array'
    AND jsonb_array_length(p_itens_usoconsumo) > 0;
  v_documento_produto bigint := nullif(p_entrada_produto->>'fiscal_dfe_documento_id', '')::bigint;
  v_documento_uso bigint := nullif(p_entrada_usoconsumo->>'documento_fiscal_recebido_id', '')::bigint;
  v_documento_id bigint;
  v_destino_personalizado text := upper(btrim(coalesce(p_auditoria->>'destino', '')));
  v_created_by uuid := coalesce(
    nullif(p_entrada_produto->>'created_by', '')::uuid,
    nullif(p_entrada_usoconsumo->>'created_by', '')::uuid
  );
  v_resultado_produto jsonb;
  v_resultado_uso jsonb;
  v_entrada_id bigint;
  v_usoconsumo_entrada_id bigint;
  v_apropriacao jsonb;
  v_numero_item integer;
  v_quantidade numeric(14,4);
  v_destino_apropriacao text;
  v_numeros integer[] := ARRAY[]::integer[];
  v_ocorrencias integer;
  v_total_fisico numeric(14,2);
  v_total_custom_auditoria numeric(14,2);
  v_total_custom_item numeric(14,2);
  v_total_financeiro numeric(14,2);
  v_transacao jsonb;
BEGIN
  IF jsonb_typeof(p_itens_produto) <> 'array'
     OR jsonb_typeof(p_itens_usoconsumo) <> 'array' THEN
    RAISE EXCEPTION 'As listas fisicas da entrada hibrida sao invalidas.' USING ERRCODE = '22023';
  END IF;
  IF NOT v_tem_produto AND NOT v_tem_uso THEN
    RAISE EXCEPTION 'A entrada hibrida exige ao menos um item fisico.' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_apropriacoes) <> 'array' OR jsonb_array_length(p_apropriacoes) < 2 THEN
    RAISE EXCEPTION 'A entrada hibrida exige todas as linhas fiscais da NF-e.' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_auditoria) <> 'object'
     OR jsonb_typeof(p_auditoria->'itens_originais') <> 'array'
     OR jsonb_array_length(p_auditoria->'itens_originais') = 0 THEN
    RAISE EXCEPTION 'Informe as linhas consolidadas da entrada personalizada.' USING ERRCODE = '22023';
  END IF;
  IF v_destino_personalizado NOT IN ('ESTOQUE', 'USOCONSUMO', 'GERAL') THEN
    RAISE EXCEPTION 'Destino personalizado invalido.' USING ERRCODE = '22023';
  END IF;
  IF (v_destino_personalizado = 'ESTOQUE' AND NOT v_tem_produto)
     OR (v_destino_personalizado IN ('USOCONSUMO', 'GERAL') AND NOT v_tem_uso) THEN
    RAISE EXCEPTION 'O item personalizado nao pertence ao cabecalho informado.' USING ERRCODE = '22023';
  END IF;
  IF p_custo_total IS NULL OR p_custo_total < 0
     OR p_custo_personalizado IS NULL OR p_custo_personalizado < 0
     OR p_total_documento IS NULL OR p_total_documento < 0 THEN
    RAISE EXCEPTION 'Os totais da entrada hibrida sao invalidos.' USING ERRCODE = '22023';
  END IF;

  v_documento_id := coalesce(v_documento_produto, v_documento_uso);
  IF v_documento_id IS NULL
     OR (v_documento_produto IS NOT NULL AND v_documento_uso IS NOT NULL
         AND v_documento_produto <> v_documento_uso) THEN
    RAISE EXCEPTION 'Os cabecalhos nao apontam para a mesma NF-e.' USING ERRCODE = '22023';
  END IF;

  PERFORM 1 FROM public.fiscal_dfe_documento
   WHERE id = v_documento_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Documento fiscal recebido nao encontrado.' USING ERRCODE = 'P0002';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.fiscal_dfe_item_apropriacao
     WHERE documento_id = v_documento_id AND cancelada_at IS NULL
  ) THEN
    RAISE EXCEPTION 'A entrada hibrida exige uma NF-e ainda nao apropriada.' USING ERRCODE = '23505';
  END IF;

  -- Cada nItem precisa aparecer uma vez nas apropriacoes e uma vez na origem:
  -- como item fisico normal ou como linha do snapshot personalizado.
  FOR v_apropriacao IN SELECT value FROM jsonb_array_elements(p_apropriacoes)
  LOOP
    v_numero_item := nullif(v_apropriacao->>'numero_item', '')::integer;
    v_quantidade := nullif(v_apropriacao->>'quantidade', '')::numeric;
    v_destino_apropriacao := upper(btrim(coalesce(v_apropriacao->>'destino', '')));
    IF v_numero_item IS NULL OR v_numero_item < 1 OR v_numero_item > 990
       OR v_quantidade IS NULL OR v_quantidade <= 0
       OR v_destino_apropriacao NOT IN ('PRODUTO', 'USOCONSUMO') THEN
      RAISE EXCEPTION 'As apropriacoes fiscais da entrada hibrida sao invalidas.' USING ERRCODE = '22023';
    END IF;
    IF v_numero_item = ANY(v_numeros) THEN
      RAISE EXCEPTION 'O item fiscal % foi apropriado mais de uma vez.', v_numero_item
        USING ERRCODE = '22023';
    END IF;
    IF (v_destino_apropriacao = 'PRODUTO' AND NOT v_tem_produto)
       OR (v_destino_apropriacao = 'USOCONSUMO' AND NOT v_tem_uso) THEN
      RAISE EXCEPTION 'A apropriacao do item % nao possui cabecalho fisico.', v_numero_item
        USING ERRCODE = '22023';
    END IF;

    SELECT count(*) INTO v_ocorrencias FROM (
      SELECT nullif(value->>'numero_item_fiscal', '')::integer AS numero
        FROM jsonb_array_elements(p_itens_produto)
      UNION ALL
      SELECT nullif(value->>'numero_item_fiscal', '')::integer
        FROM jsonb_array_elements(p_itens_usoconsumo)
      UNION ALL
      SELECT nullif(value->>'numero_item', '')::integer
        FROM jsonb_array_elements(p_auditoria->'itens_originais')
    ) origens WHERE numero = v_numero_item;
    IF v_ocorrencias <> 1 THEN
      RAISE EXCEPTION 'O item fiscal % deve possuir exatamente uma origem.', v_numero_item
        USING ERRCODE = '22023';
    END IF;
    v_numeros := array_append(v_numeros, v_numero_item);
  END LOOP;

  SELECT count(*) INTO v_ocorrencias FROM (
    SELECT nullif(value->>'numero_item_fiscal', '')::integer AS numero
      FROM jsonb_array_elements(p_itens_produto)
    UNION ALL
    SELECT nullif(value->>'numero_item_fiscal', '')::integer
      FROM jsonb_array_elements(p_itens_usoconsumo)
    UNION ALL
    SELECT nullif(value->>'numero_item', '')::integer
      FROM jsonb_array_elements(p_auditoria->'itens_originais')
  ) origens WHERE numero IS NOT NULL;
  IF v_ocorrencias <> jsonb_array_length(p_apropriacoes) THEN
    RAISE EXCEPTION 'A entrada hibrida nao cobre todas as linhas fiscais uma unica vez.'
      USING ERRCODE = '22023';
  END IF;

  SELECT round(coalesce(sum((value->>'custo_estoque')::numeric), 0), 2)
    INTO v_total_custom_auditoria
    FROM jsonb_array_elements(p_auditoria->'itens_originais');
  IF v_total_custom_auditoria <> round(p_custo_personalizado, 2) THEN
    RAISE EXCEPTION 'O custo personalizado (%) difere da soma das linhas consolidadas (%).',
      round(p_custo_personalizado, 2), v_total_custom_auditoria USING ERRCODE = '23514';
  END IF;

  IF v_destino_personalizado = 'ESTOQUE' THEN
    SELECT round(
      (value->>'quantidade')::numeric * (value->>'valor_unitario_compra')::numeric
      - coalesce(nullif(value->>'valor_desconto', '')::numeric, 0)
      + coalesce(nullif(value->>'valor_frete', '')::numeric, 0)
      + coalesce(nullif(value->>'outras_despesas', '')::numeric, 0), 2
    ) INTO v_total_custom_item
      FROM jsonb_array_elements(p_itens_produto)
     WHERE nullif(value->>'numero_item_fiscal', '') IS NULL
       AND nullif(value->>'produto_id', '')::integer = nullif(p_auditoria->>'produto_id', '')::integer;
  ELSE
    SELECT round(
      (value->>'quantidade')::numeric * (value->>'valor_unitario_compra')::numeric
      - coalesce(nullif(value->>'valor_desconto', '')::numeric, 0)
      + coalesce(nullif(value->>'valor_frete', '')::numeric, 0)
      + coalesce(nullif(value->>'outras_despesas', '')::numeric, 0), 2
    ) INTO v_total_custom_item
      FROM jsonb_array_elements(p_itens_usoconsumo)
     WHERE nullif(value->>'numero_item_fiscal', '') IS NULL
       AND nullif(value->>'item_id', '')::integer = nullif(p_auditoria->>'usoconsumo_item_id', '')::integer;
  END IF;
  IF v_total_custom_item IS NULL OR v_total_custom_item <> round(p_custo_personalizado, 2) THEN
    RAISE EXCEPTION 'O item personalizado nao reproduz o custo consolidado.' USING ERRCODE = '23514';
  END IF;

  IF v_tem_produto THEN
    SELECT public.registrar_entrada_confirmada(
      p_entrada_produto - 'valor_total_documento',
      p_itens_produto,
      '[]'::jsonb
    ) INTO v_resultado_produto;
    v_entrada_id := (v_resultado_produto->>'entrada_id')::bigint;
  END IF;

  IF v_tem_uso THEN
    SELECT public.registrar_entrada_usoconsumo(
      (p_entrada_usoconsumo - 'documento_fiscal_recebido_id') - 'valor_total_documento',
      p_itens_usoconsumo,
      '[]'::jsonb
    ) INTO v_resultado_uso;
    v_usoconsumo_entrada_id := (v_resultado_uso->>'entrada_id')::bigint;
    UPDATE public.usoconsumo_entrada
       SET documento_fiscal_recebido_id = v_documento_id
     WHERE id = v_usoconsumo_entrada_id;
  END IF;

  v_total_fisico := round(
    coalesce((v_resultado_produto->>'valor_total')::numeric, 0)
    + coalesce((v_resultado_uso->>'valor_total')::numeric, 0), 2
  );
  IF v_total_fisico <> round(p_custo_total, 2) THEN
    RAISE EXCEPTION 'O custo fisico (%) difere do custo calculado da NF-e (%).',
      v_total_fisico, round(p_custo_total, 2) USING ERRCODE = '23514';
  END IF;

  -- Com um unico cabecalho, a tela historicamente mostra o vNF no cabecalho. Com
  -- dois, cada metade conserva seu custo fisico e o financeiro compartilhado
  -- carrega o total integral, como na entrada fiscal mista atual.
  IF v_tem_produto AND NOT v_tem_uso THEN
    UPDATE public.entrada SET valor_total = round(p_total_documento, 2)
     WHERE id = v_entrada_id;
  ELSIF v_tem_uso AND NOT v_tem_produto THEN
    UPDATE public.usoconsumo_entrada SET valor_total = round(p_total_documento, 2)
     WHERE id = v_usoconsumo_entrada_id;
  END IF;

  FOR v_apropriacao IN SELECT value FROM jsonb_array_elements(p_apropriacoes)
  LOOP
    v_destino_apropriacao := upper(v_apropriacao->>'destino');
    INSERT INTO public.fiscal_dfe_item_apropriacao(
      documento_id, numero_item, destino, entrada_id,
      usoconsumo_entrada_id, quantidade, created_by
    ) VALUES (
      v_documento_id,
      (v_apropriacao->>'numero_item')::integer,
      v_destino_apropriacao,
      CASE WHEN v_destino_apropriacao = 'PRODUTO' THEN v_entrada_id END,
      CASE WHEN v_destino_apropriacao = 'USOCONSUMO' THEN v_usoconsumo_entrada_id END,
      (v_apropriacao->>'quantidade')::numeric,
      v_created_by
    );
  END LOOP;

  INSERT INTO public.entrada_fiscal_personalizada(
    documento_id, destino, entrada_id, usoconsumo_entrada_id,
    itens_originais, custo_total_estoque, created_by, modalidade,
    produto_id, usoconsumo_item_id, quantidade_personalizada, custo_unitario,
    valor_fiscal_documento, item_destino_snapshot
  ) VALUES (
    v_documento_id,
    v_destino_personalizado,
    CASE WHEN v_destino_personalizado = 'ESTOQUE' THEN v_entrada_id END,
    CASE WHEN v_destino_personalizado IN ('USOCONSUMO', 'GERAL') THEN v_usoconsumo_entrada_id END,
    p_auditoria->'itens_originais',
    round(p_custo_personalizado, 2),
    v_created_by,
    'HIBRIDA',
    nullif(p_auditoria->>'produto_id', '')::integer,
    nullif(p_auditoria->>'usoconsumo_item_id', '')::integer,
    nullif(p_auditoria->>'quantidade_personalizada', '')::integer,
    nullif(p_auditoria->>'custo_unitario', '')::numeric,
    round(p_total_documento, 2),
    p_auditoria->'item_destino_snapshot'
  );

  IF jsonb_typeof(p_transacoes) = 'array' AND jsonb_array_length(p_transacoes) > 0 THEN
    SELECT round(coalesce(sum((value->>'valor')::numeric), 0), 2)
      INTO v_total_financeiro FROM jsonb_array_elements(p_transacoes);
    IF v_total_financeiro <> round(p_total_documento, 2) THEN
      RAISE EXCEPTION 'A soma dos lancamentos financeiros (%) difere do vNF (%).',
        v_total_financeiro, round(p_total_documento, 2) USING ERRCODE = '22023';
    END IF;

    FOR v_transacao IN SELECT value FROM jsonb_array_elements(p_transacoes)
    LOOP
      IF coalesce(nullif(v_transacao->>'valor', '')::numeric, 0) <= 0 THEN
        RAISE EXCEPTION 'O valor do lancamento financeiro deve ser positivo.' USING ERRCODE = '22023';
      END IF;
      INSERT INTO public.transacao(
        descricao, valor, "valorLiquido", data, vencimento_em, metodopagamento,
        categoria, categoria_id, tipo, cliente_id, banco_id, nomepagador,
        cpfcnpjpagador, pendente, plano_de_conta_id, plano_de_conta,
        centro_custo_id, centro_custo, entrada_id, usoconsumo_entrada_id,
        origem, created_by
      ) VALUES (
        coalesce(nullif(v_transacao->>'descricao', ''), 'Compra de mercadorias'),
        (v_transacao->>'valor')::numeric,
        (v_transacao->>'valor')::numeric,
        coalesce(nullif(v_transacao->>'data', '')::timestamptz, now()),
        nullif(v_transacao->>'vencimento_em', '')::timestamptz,
        nullif(v_transacao->>'metodopagamento', '')::public.metodo_pagamento,
        coalesce(nullif(v_transacao->>'categoria', ''), 'NAO RELACIONADO'),
        nullif(v_transacao->>'categoria_id', '')::integer,
        'DESPESA'::public.tipos_transacao,
        NULL,
        nullif(v_transacao->>'banco_id', '')::bigint,
        coalesce(nullif(v_transacao->>'nomepagador', ''), 'Fornecedor'),
        coalesce(nullif(regexp_replace(v_transacao->>'cpfcnpjpagador', '\D', '', 'g'), ''), 'NAO INFORMADO'),
        coalesce((v_transacao->>'pendente')::boolean, false),
        nullif(v_transacao->>'plano_de_conta_id', '')::integer,
        nullif(v_transacao->>'plano_de_conta', ''),
        nullif(v_transacao->>'centro_custo_id', '')::integer,
        nullif(v_transacao->>'centro_custo', ''),
        v_entrada_id,
        v_usoconsumo_entrada_id,
        'ENTRADA_FISCAL_MISTA',
        v_created_by
      );
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'entrada_id', v_entrada_id,
    'usoconsumo_entrada_id', v_usoconsumo_entrada_id,
    'valor_total', round(p_total_documento, 2),
    'custo_total_estoque', v_total_fisico,
    'custo_personalizado', round(p_custo_personalizado, 2)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_os_execucao_set_times()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  -- Quando entra em EM_ANDAMENTO, marca início (só se ainda não tiver)
  if (new.status::text = 'EM_ANDAMENTO' and old.status is distinct from new.status) then
    new.execucao_inicio_em := coalesce(old.execucao_inicio_em, now());
    new.execucao_fim_em := null; -- se voltar para andamento, reabre a execução
  end if;

  -- Quando entra em PAGAMENTO, marca fim (só se tiver início e ainda não tiver fim)
  if (new.status::text = 'PAGAMENTO' and old.status is distinct from new.status) then
    if (old.execucao_inicio_em is not null) then
      new.execucao_inicio_em := old.execucao_inicio_em;
      new.execucao_fim_em := coalesce(old.execucao_fim_em, now());
    end if;
  end if;

  -- Cancelar desfaz a conclusão: o carimbo é o que define OS concluída no
  -- sistema inteiro, e trabalho cancelado não é produção.
  if (new.status::text = 'CANCELADO') then
    new.execucao_fim_em := null;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.tg_recalc_comissao_osservico_realizador()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$begin
  perform public.recalcular_comissao_osservico(
    coalesce(new.ordemservicoid, old.ordemservicoid),
    coalesce(new.servicoid, old.servicoid)
  );

  return coalesce(new, old);
end;$function$

CREATE OR REPLACE FUNCTION public.registrar_consumo_produto_os(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_os_id       integer := nullif(p_payload->>'ordemservicoid', '')::integer;
  v_escopo      text    := upper(btrim(coalesce(p_payload->>'escopo', '')));
  v_item_id     integer := nullif(p_payload->>'item_id', '')::integer;
  v_quantidade  integer := nullif(p_payload->>'quantidade', '')::integer;
  v_observacao  text    := nullif(btrim(coalesce(p_payload->>'observacao', '')), '');
  v_descricao   text    := nullif(btrim(coalesce(p_payload->>'descricao', '')), '');
  v_detalhe     text    := nullif(btrim(coalesce(p_payload->>'detalhe', '')), '');
  v_valor       numeric(14,2) := nullif(p_payload->>'valor', '')::numeric;
  v_pode_gerar  boolean := coalesce((p_payload->>'pode_gerar_transacao')::boolean, false);
  v_user        uuid    := nullif(p_payload->>'created_by', '')::uuid;
  v_status_os   text;
  v_saida       jsonb;
  v_saida_id    bigint;
  v_custo       numeric(14,4);
  v_saldo       integer;
  v_titulo      text;
  v_unidade     text;
  v_valor_base  numeric(14,2);
  v_editado     boolean := false;
  v_evento_id   bigint;
BEGIN
  IF v_os_id IS NULL OR v_os_id <= 0 THEN
    RAISE EXCEPTION 'Informe a ordem de servico.' USING ERRCODE = '22023';
  END IF;
  IF v_escopo NOT IN ('PRODUTO', 'USOCONSUMO', 'GERAL') THEN
    RAISE EXCEPTION 'Estoque invalido: %.', v_escopo USING ERRCODE = '22023';
  END IF;
  IF v_item_id IS NULL OR v_item_id <= 0 THEN
    RAISE EXCEPTION 'Selecione o item consumido.' USING ERRCODE = '22023';
  END IF;
  IF v_quantidade IS NULL OR v_quantidade <= 0 THEN
    RAISE EXCEPTION 'A quantidade deve ser maior que zero.' USING ERRCODE = '22023';
  END IF;
  IF v_valor IS NOT NULL AND v_valor < 0 THEN
    RAISE EXCEPTION 'O valor da despesa nao pode ser negativo.' USING ERRCODE = '22023';
  END IF;

  SELECT o.status::text INTO v_status_os
    FROM public.ordemservico o
   WHERE o.id = v_os_id AND coalesce(o.is_deleted, false) = false;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OS nao encontrada.' USING ERRCODE = 'P0002';
  END IF;
  -- Os tres primeiros sao a mesma regra do POST de eventos financeiros. O quarto
  -- entra porque ORCAMENTO_RECUSADO e um estado em que o estoque esta voltando.
  IF v_status_os IN ('CONCLUIDO', 'SEM_COBRANCA', 'CANCELADO', 'ORCAMENTO_RECUSADO') THEN
    RAISE EXCEPTION 'Nao e possivel registrar consumo numa OS com status %.',
      replace(v_status_os, '_', ' ') USING ERRCODE = 'P0001';
  END IF;

  IF v_escopo = 'PRODUTO' THEN
    SELECT p.titulo, p.unidade::text INTO v_titulo, v_unidade
      FROM public.produto p
     WHERE p.id = v_item_id AND coalesce(p.is_deleted, false) = false;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Produto nao encontrado.' USING ERRCODE = 'P0002';
    END IF;

    -- A RPC inteira, e nao um recorte dela: e ela que trava a linha, confere o
    -- saldo e carimba a origem no razao.
    v_saida := public.registrar_saida_estoque(
      v_item_id, v_quantidade, 'CONSUMO_EM_OS', v_observacao, v_user
    );
    v_saida_id := (v_saida->>'saida_id')::bigint;
    v_saldo    := (v_saida->>'saldo_resultante')::integer;

    UPDATE public.estoque_saida SET ordemservicoid = v_os_id WHERE id = v_saida_id;

    SELECT i.valor_custo_aplicado INTO v_custo
      FROM public.estoque_saida_item i
     WHERE i.saida_id = v_saida_id AND i.produto_id = v_item_id;
  ELSE
    SELECT i.titulo, i.unidade::text INTO v_titulo, v_unidade
      FROM public.usoconsumo_item i
     WHERE i.id = v_item_id AND i.ativo AND i.escopo = v_escopo;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Item nao encontrado neste estoque.' USING ERRCODE = 'P0002';
    END IF;

    v_saida := public.registrar_saida_usoconsumo(
      jsonb_build_object(
        'escopo', v_escopo, 'motivo', 'CONSUMO_EM_OS',
        'observacao', v_observacao, 'created_by', v_user
      ),
      jsonb_build_array(jsonb_build_object('item_id', v_item_id, 'quantidade', v_quantidade))
    );
    v_saida_id := (v_saida->>'saida_id')::bigint;

    UPDATE public.usoconsumo_saida SET ordemservicoid = v_os_id WHERE id = v_saida_id;

    SELECT i.valor_custo_aplicado, i.saldo_resultante INTO v_custo, v_saldo
      FROM public.usoconsumo_saida_item i
     WHERE i.saida_id = v_saida_id AND i.item_id = v_item_id;
  END IF;

  -- O custo do cadastro e a base; o valor informado a mao e o escape, e ele
  -- marca a linha para a correcao nao passar despercebida.
  v_valor_base := round(coalesce(v_custo, 0) * v_quantidade, 2);
  IF v_valor IS NULL THEN
    v_valor := v_valor_base;
  ELSE
    v_valor := round(v_valor, 2);
    v_editado := v_valor IS DISTINCT FROM v_valor_base;
  END IF;

  v_titulo := coalesce(nullif(btrim(coalesce(v_titulo, '')), ''), 'Item #' || v_item_id);

  INSERT INTO public.eventos_financeiros (
    ordemservicoid, source_type, source_id, source_item_id,
    origem, natureza, natureza_dre, chave_origem,
    descricao, detalhe, valor,
    produtoid, quantidade_snapshot, valor_unitario_snapshot,
    is_manual, pode_gerar_transacao,
    consumo_saida_id, consumo_usoconsumo_saida_id,
    dados_snapshot, created_by
  ) VALUES (
    v_os_id, 'ORDEM_SERVICO', v_os_id, v_item_id,
    'CONSUMO', 'DESPESA', 'CUSTO', 'CONSUMO:' || v_saida_id,
    coalesce(v_descricao, 'Consumo - ' || v_titulo),
    coalesce(
      v_detalhe,
      v_quantidade || ' ' || coalesce(v_unidade, 'UN')
        || ' - ' || CASE v_escopo
                      WHEN 'PRODUTO'    THEN 'Estoque de produtos'
                      WHEN 'USOCONSUMO' THEN 'Uso e consumo'
                      ELSE 'Geral/Avulso'
                    END
    ),
    v_valor,
    CASE WHEN v_escopo = 'PRODUTO' THEN v_item_id END,
    v_quantidade, coalesce(v_custo, 0),
    true, v_pode_gerar,
    CASE WHEN v_escopo = 'PRODUTO' THEN v_saida_id END,
    CASE WHEN v_escopo <> 'PRODUTO' THEN v_saida_id END,
    jsonb_build_object(
      'consumo_de_estoque', true,
      'escopo', v_escopo,
      'item_id', v_item_id,
      'item_titulo', v_titulo,
      'unidade', coalesce(v_unidade, 'UN'),
      'saida_id', v_saida_id,
      'custo_unitario', coalesce(v_custo, 0),
      'valor_base', v_valor_base,
      'valor_editado', v_editado,
      'observacao', v_observacao
    ),
    v_user
  ) RETURNING id INTO v_evento_id;

  RETURN jsonb_build_object(
    'evento_id', v_evento_id,
    'saida_id', v_saida_id,
    'escopo', v_escopo,
    'valor', v_valor,
    'saldo_resultante', v_saldo
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_eventos_financeiros_venda()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'INSERT' then
    if public.venda_reconhece_receita(new.status::text) then
      perform public.sincronizar_eventos_financeiros_venda(new.id);
    end if;
    return new;
  end if;

  if new.status is distinct from old.status
     or new.valortotal is distinct from old.valortotal
     or new.desconto_valor is distinct from old.desconto_valor
     or new.valor_frete is distinct from old.valor_frete
     or new.datavenda is distinct from old.datavenda then
    perform public.sincronizar_eventos_financeiros_venda(new.id);
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.cancelar_consumo_produto_os(p_evento_id bigint, p_motivo text, p_usuario uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_evento    public.eventos_financeiros%ROWTYPE;
  v_motivo    text := nullif(btrim(coalesce(p_motivo, '')), '');
  v_status_os text;
BEGIN
  IF v_motivo IS NULL THEN
    RAISE EXCEPTION 'Informe o motivo do cancelamento.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_evento FROM public.eventos_financeiros WHERE id = p_evento_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Consumo nao encontrado.' USING ERRCODE = 'P0002';
  END IF;
  IF v_evento.origem <> 'CONSUMO' THEN
    RAISE EXCEPTION 'Este evento nao e um consumo de estoque.' USING ERRCODE = 'P0001';
  END IF;
  IF v_evento.status = 'CANCELADO' THEN
    RAISE EXCEPTION 'Este consumo ja foi cancelado.' USING ERRCODE = 'P0001';
  END IF;
  -- Dinheiro real amarrado: desfazer aqui deixaria uma transacao orfa.
  IF v_evento.status = 'CONVERTIDO'
     OR v_evento.transacaoid IS NOT NULL
     OR v_evento.lancamento_id IS NOT NULL THEN
    RAISE EXCEPTION 'Este consumo ja foi lancado no financeiro. Exclua a transacao vinculada antes de devolver o item ao estoque.'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT o.status::text INTO v_status_os
    FROM public.ordemservico o WHERE o.id = v_evento.ordemservicoid;
  -- Mesma frase que o lancamento de despesas ja usa, para o operador reconhecer
  -- o caminho: reabrir a OS destrava.
  IF v_status_os IN ('CONCLUIDO', 'SEM_COBRANCA', 'CANCELADO') THEN
    RAISE EXCEPTION 'A OS #% ja foi finalizada. Reabra a OS para desfazer este consumo.',
      v_evento.ordemservicoid USING ERRCODE = 'P0001';
  END IF;

  IF v_evento.consumo_saida_id IS NOT NULL THEN
    PERFORM set_config('app.consumo_os_estorno', 'permitido', true);
    PERFORM public.cancelar_saida_estoque(v_evento.consumo_saida_id, v_motivo, p_usuario);
    PERFORM set_config('app.consumo_os_estorno', '', true);
  ELSIF v_evento.consumo_usoconsumo_saida_id IS NOT NULL THEN
    PERFORM set_config('app.consumo_os_estorno', 'permitido', true);
    PERFORM public.cancelar_saida_usoconsumo(v_evento.consumo_usoconsumo_saida_id, v_motivo, p_usuario);
    PERFORM set_config('app.consumo_os_estorno', '', true);
  ELSE
    RAISE EXCEPTION 'Este consumo nao tem saida de estoque vinculada.' USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.eventos_financeiros
     SET status = 'CANCELADO',
         updated_at = now(),
         dados_snapshot = coalesce(dados_snapshot, '{}'::jsonb) || jsonb_build_object(
           'cancelado_em', now(),
           'cancelado_por', p_usuario,
           'motivo_cancelamento', v_motivo
         )
   WHERE id = p_evento_id;

  RETURN jsonb_build_object('evento_id', p_evento_id, 'status', 'CANCELADO');
END;
$function$

CREATE OR REPLACE FUNCTION public.cancelar_saida_estoque(p_saida_id bigint, p_motivo text, p_cancelada_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_os integer;
BEGIN
  SELECT ordemservicoid INTO v_os FROM public.estoque_saida WHERE id = p_saida_id;
  IF v_os IS NOT NULL
     AND coalesce(nullif(current_setting('app.consumo_os_estorno', true), ''), '') <> 'permitido' THEN
    RAISE EXCEPTION 'Esta saida foi gerada pelo consumo registrado na OS #%. Cancele a despesa na ordem de servico para devolver o item ao estoque.',
      v_os USING ERRCODE = 'P0001';
  END IF;

  PERFORM public.estoque_definir_contexto(
    'SAIDA_MANUAL', p_saida_id, 'Saida #' || p_saida_id || ' - cancelada', p_cancelada_by
  );
  RETURN public.cancelar_saida_estoque_interna(p_saida_id, p_motivo, p_cancelada_by);
END;
$function$

CREATE OR REPLACE FUNCTION public.cancelar_saida_usoconsumo(p_saida_id bigint, p_motivo text, p_cancelada_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_saida public.usoconsumo_saida%ROWTYPE; v_linha record;
  v_motivo text := nullif(btrim(p_motivo), '');
BEGIN
  IF v_motivo IS NULL THEN RAISE EXCEPTION 'Informe o motivo do cancelamento.' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_saida FROM public.usoconsumo_saida WHERE id=p_saida_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Saida nao encontrada.' USING ERRCODE='P0002'; END IF;
  IF v_saida.status='CANCELADA' THEN RAISE EXCEPTION 'Saida ja cancelada.' USING ERRCODE='22023'; END IF;
  IF v_saida.ordemservicoid IS NOT NULL
     AND coalesce(nullif(current_setting('app.consumo_os_estorno', true), ''), '') <> 'permitido' THEN
    RAISE EXCEPTION 'Esta saida foi gerada pelo consumo registrado na OS #%. Cancele a despesa na ordem de servico para devolver o item ao estoque.',
      v_saida.ordemservicoid USING ERRCODE='P0001';
  END IF;
  FOR v_linha IN SELECT * FROM public.usoconsumo_saida_item WHERE saida_id=p_saida_id ORDER BY id FOR UPDATE LOOP
    PERFORM 1 FROM public.usoconsumo_item WHERE id=v_linha.item_id FOR UPDATE;
    PERFORM set_config('app.usoconsumo_movimento','permitido',true);
    UPDATE public.usoconsumo_item SET estoque=estoque+v_linha.quantidade,updated_by=p_cancelada_by WHERE id=v_linha.item_id;
  END LOOP;
  UPDATE public.usoconsumo_saida
    SET status='CANCELADA',cancelada_at=now(),cancelada_by=p_cancelada_by,motivo_cancelamento=v_motivo
    WHERE id=p_saida_id;
  RETURN jsonb_build_object('saida_id',p_saida_id,'status','CANCELADA');
END $function$

CREATE OR REPLACE FUNCTION public.fn_registrar_evento_notificacao_os()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tipo text;
  v_status_anterior text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_tipo := 'CRIADA';
    v_status_anterior := NULL;
  ELSIF OLD.status IS DISTINCT FROM NEW.status THEN
    v_tipo := 'STATUS_ALTERADO';
    v_status_anterior := OLD.status::text;
  ELSE
    RETURN NEW;
  END IF;

  INSERT INTO public.os_notificacao_evento (
    ordemservico_id, tipo, status_anterior, status_novo,
    ator_usuario_id, snapshot, disponivel_em
  ) VALUES (
    NEW.id, v_tipo, v_status_anterior, NEW.status::text,
    public.auditoria_usuario_requisicao(),
    jsonb_build_object(
      'cliente_id', NEW.clienteid,
      'veiculo_id', NEW.veiculoid,
      'peca_id', NEW.pecaid,
      'alvo_tipo', NEW.alvo_tipo,
      'equipamento_nome', NEW.equipamento_nome,
      'setor_id', NEW.setorid,
      'usuario_criador_id', NEW.usuariocriadorid,
      'prioridade', NEW.prioridade
    ),
    now()
  );

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.registrar_entrada_comercial_apropriada(p_entrada jsonb, p_itens jsonb, p_transacoes jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result jsonb;
  v_item jsonb;
  v_documento_id bigint:=nullif(p_entrada->>'fiscal_dfe_documento_id','')::bigint;
  v_numero_item integer;
  v_user uuid:=nullif(p_entrada->>'created_by','')::uuid;
BEGIN
  SELECT public.registrar_entrada_confirmada(p_entrada,p_itens,p_transacoes) INTO v_result;
  IF v_documento_id IS NOT NULL THEN
    FOR v_item IN SELECT value FROM jsonb_array_elements(p_itens) LOOP
      v_numero_item:=nullif(v_item->>'numero_item_fiscal','')::integer;
      IF v_numero_item IS NULL THEN
        RAISE EXCEPTION 'Informe o numero fiscal de todos os itens apropriados.' USING ERRCODE='22023';
      END IF;
      INSERT INTO public.fiscal_dfe_item_apropriacao(
        documento_id,numero_item,destino,entrada_id,quantidade,created_by
      ) VALUES(
        v_documento_id,v_numero_item,'PRODUTO',(v_result->>'entrada_id')::bigint,
        (v_item->>'quantidade')::numeric,v_user
      );
    END LOOP;
  END IF;
  RETURN v_result;
END $function$

CREATE OR REPLACE FUNCTION public.tg_congelar_comissao_ao_encerrar_execucao()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF new.execucao_fim_em IS NOT NULL AND old.execucao_fim_em IS NULL THEN
    PERFORM public.recarimbar_comissao_osservico(new.id, NULL);
    PERFORM public.recalcular_comissao_osservico(new.id, s.servicoid)
      FROM public.osservico s WHERE s.ordemservicoid = new.id;
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.excluir_evento_financeiro_manual_os(p_ordemservico_id integer, p_evento_id bigint, p_motivo text DEFAULT NULL::text, p_usuario uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_evento public.eventos_financeiros%ROWTYPE;
  v_status_os text;
  v_os_excluida boolean;
  v_manual_de_origem boolean;
  v_consumo_com_estoque boolean;
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
BEGIN
  IF p_ordemservico_id IS NULL OR p_ordemservico_id <= 0
     OR p_evento_id IS NULL OR p_evento_id <= 0 THEN
    RAISE EXCEPTION 'Identificador invalido.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_evento
    FROM public.eventos_financeiros
   WHERE id = p_evento_id
     AND ordemservicoid = p_ordemservico_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Evento financeiro nao encontrado nesta OS.' USING ERRCODE = 'P0002';
  END IF;

  v_consumo_com_estoque :=
    v_evento.origem = 'CONSUMO'
    AND v_evento.natureza = 'DESPESA'
    AND (v_evento.consumo_saida_id IS NOT NULL OR v_evento.consumo_usoconsumo_saida_id IS NOT NULL);
  v_manual_de_origem :=
    coalesce(v_evento.is_manual, false)
    AND (
      coalesce(v_evento.chave_origem, '') LIKE 'MANUAL:%'
      OR v_consumo_com_estoque
    );

  -- Uma comissao corrigida recebe is_manual para congelar seu calculo, mas
  -- continua sendo automatica. Frete/receita pertence ao orcamento.
  IF NOT v_manual_de_origem
     OR v_evento.origem = 'COMISSAO'
     OR (v_evento.origem = 'FRETE' AND v_evento.natureza = 'RECEITA') THEN
    RAISE EXCEPTION 'Este evento foi gerado automaticamente e deve ser corrigido na origem que o criou.'
      USING ERRCODE = 'P0001';
  END IF;

  IF v_evento.status = 'CONVERTIDO'
     OR v_evento.transacaoid IS NOT NULL
     OR v_evento.lancamento_id IS NOT NULL THEN
    RAISE EXCEPTION 'Este evento ja foi lancado no Financeiro. Exclua primeiro a transacao ou o lancamento vinculado.'
      USING ERRCODE = 'P0001';
  END IF;
  IF v_evento.status <> 'ATIVO' THEN
    RAISE EXCEPTION 'Somente eventos financeiros ativos podem ser excluidos.' USING ERRCODE = 'P0001';
  END IF;

  SELECT o.status::text, coalesce(o.is_deleted, false)
    INTO v_status_os, v_os_excluida
    FROM public.ordemservico o
   WHERE o.id = p_ordemservico_id
   FOR UPDATE;
  IF NOT FOUND OR v_os_excluida THEN
    RAISE EXCEPTION 'OS nao encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF v_status_os = 'CANCELADO' THEN
    RAISE EXCEPTION 'Esta OS esta cancelada e seus eventos financeiros nao podem mais ser alterados.'
      USING ERRCODE = 'P0001';
  END IF;
  IF v_consumo_com_estoque AND v_status_os IN ('CONCLUIDO', 'SEM_COBRANCA') THEN
    RAISE EXCEPTION 'A OS #% ja foi finalizada. Reabra a OS para excluir este consumo e devolver o item ao estoque.',
      p_ordemservico_id USING ERRCODE = 'P0001';
  END IF;
  IF v_consumo_com_estoque AND v_motivo IS NULL THEN
    RAISE EXCEPTION 'Informe o motivo para devolver o item ao estoque.' USING ERRCODE = '22023';
  END IF;

  -- Faz o gatilho generico de auditoria atribuir UPDATE/DELETE ao operador que
  -- chamou a API, mesmo a RPC sendo executada pelo service_role.
  PERFORM set_config('app.audit_user_id', coalesce(p_usuario::text, ''), true);

  IF v_consumo_com_estoque THEN
    -- A funcao existente cancela a saida e devolve o saldo. Como esta chamada e
    -- interna a mesma RPC, qualquer falha no DELETE tambem desfaz o estorno.
    PERFORM public.cancelar_consumo_produto_os(p_evento_id, v_motivo, p_usuario);
  END IF;

  DELETE FROM public.eventos_financeiros
   WHERE id = p_evento_id
     AND ordemservicoid = p_ordemservico_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'O evento mudou durante a exclusao. Recarregue a OS e tente novamente.'
      USING ERRCODE = '40001';
  END IF;

  RETURN jsonb_build_object(
    'evento_id', p_evento_id,
    'excluido', true,
    'estoque_devolvido', v_consumo_com_estoque,
    'saida_id', coalesce(v_evento.consumo_saida_id, v_evento.consumo_usoconsumo_saida_id)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.cancelar_venda_marketplace_sem_repor_estoque(p_venda_id integer, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_venda public.venda%rowtype;
  v_transacoes_excluidas integer := 0;
begin
  if p_motivo is null or char_length(btrim(p_motivo)) < 3 then
    raise exception 'Informe um motivo com pelo menos 3 caracteres.' using errcode = '22023';
  end if;

  select * into v_venda from public.venda where id = p_venda_id for update;
  if not found then
    raise exception 'Venda não encontrada.' using errcode = 'P0002';
  end if;
  if v_venda.status::text in ('CANCELADA', 'CANCELADO') then
    return jsonb_build_object('vendaId', p_venda_id, 'status', 'CANCELADA', 'alreadyCancelled', true);
  end if;
  if exists (
    select 1 from public.nfe
     where vendaid = p_venda_id
       and status::text not in ('RASCUNHO', 'CANCELADA', 'REJEITADA')
  ) then
    raise exception 'Cancele a NF-e autorizada ou em processamento antes de encerrar a venda.' using errcode = '23514';
  end if;

  update public.transacao
     set pendente = false,
         is_deleted = true,
         deleted_at = now(),
         updated_at = now()
   where vendaid = p_venda_id
     and not is_deleted;
  get diagnostics v_transacoes_excluidas = row_count;

  update public.venda
     set status = 'CANCELADA',
         motivo_cancelamento = nullif(btrim(p_motivo), ''),
         cancelada_at = now(),
         updatedat = now(),
         status_entrega = null
   where id = p_venda_id;

  return jsonb_build_object(
    'vendaId', p_venda_id,
    'status', 'CANCELADA',
    'estoqueAguardandoConferencia', true,
    'transacoesExcluidas', v_transacoes_excluidas
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.registrar_pagamento_multiplo(p_payload jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tipo_documento text := upper(coalesce(p_payload->>'tipo_documento', ''));
  v_modo text := upper(coalesce(p_payload->>'modo', ''));
  v_valor_total numeric(14,2) := round(coalesce((p_payload->>'valor_total')::numeric, 0), 2);
  v_liquido_total numeric(14,2) := round(coalesce((p_payload->>'valor_liquido')::numeric, 0), 2);
  v_data timestamptz := coalesce(nullif(p_payload->>'data', '')::timestamptz, now());
  v_banco_id bigint := nullif(p_payload->>'banco_id', '')::bigint;
  v_metodo public.metodo_pagamento := nullif(p_payload->>'metodopagamento', '')::public.metodo_pagamento;
  v_created_by uuid := nullif(p_payload->>'created_by', '')::uuid;
  v_categoria text := coalesce(nullif(p_payload->>'categoria', ''), 'NÃO RELACIONADO');
  v_categoria_id integer := nullif(p_payload->>'categoria_id', '')::integer;
  v_plano_id integer := nullif(p_payload->>'plano_de_conta_id', '')::integer;
  v_centro_id integer := nullif(p_payload->>'centro_custo_id', '')::integer;
  v_pendente boolean := (v_modo = 'PARCELADO');
  v_grupo_id bigint;
  v_soma numeric(14,2);
  v_doc_id integer;
  v_documentos integer[] := ARRAY[]::integer[];
  v_cliente_id integer := nullif(p_payload->>'cliente_id', '')::integer;
  v_nome text := nullif(btrim(p_payload->>'nomepagador'), '');
  v_cpfcnpj text := nullif(btrim(p_payload->>'cpfcnpjpagador'), '');
  v_clientes integer[];
  v_descricao_grupo text;
  v_descricao text;
  v_parcela record;
  v_transacao_id bigint;
  v_total_parcelas integer;
  v_comprometido numeric(14,2);
  v_devido numeric(14,2);
  v_liquido numeric(14,2);
  v_liquido_acumulado numeric(14,2) := 0;
  v_indice integer := 0;
BEGIN
  IF v_tipo_documento NOT IN ('OS', 'VENDA') THEN
    RAISE EXCEPTION 'tipo_documento deve ser OS ou VENDA.' USING ERRCODE = 'P0001';
  END IF;
  IF v_modo NOT IN ('AVISTA', 'PARCELADO') THEN
    RAISE EXCEPTION 'modo deve ser AVISTA ou PARCELADO.' USING ERRCODE = 'P0001';
  END IF;
  IF v_valor_total <= 0 THEN
    RAISE EXCEPTION 'O valor do pagamento deve ser maior que zero.' USING ERRCODE = 'P0001';
  END IF;
  IF jsonb_typeof(p_payload->'linhas') <> 'array'
     OR jsonb_array_length(p_payload->'linhas') = 0 THEN
    RAISE EXCEPTION 'Informe as linhas do rateio.' USING ERRCODE = 'P0001';
  END IF;

  -- Sem líquido informado, líquido é o próprio valor: não houve taxa.
  IF v_liquido_total <= 0 THEN v_liquido_total := v_valor_total; END IF;

  SELECT round(coalesce(sum((item->>'valor')::numeric), 0), 2) INTO v_soma
    FROM jsonb_array_elements(p_payload->'linhas') AS item;

  IF v_soma <> v_valor_total THEN
    RAISE EXCEPTION 'A soma do rateio (%) difere do valor do pagamento (%).',
      v_soma, v_valor_total USING ERRCODE = 'P0001';
  END IF;

  SELECT array_agg(DISTINCT (item->>'documento_id')::integer)
    INTO v_documentos
    FROM jsonb_array_elements(p_payload->'linhas') AS item;

  FOREACH v_doc_id IN ARRAY v_documentos LOOP
    PERFORM pg_advisory_xact_lock(87001, v_doc_id);
  END LOOP;

  IF v_cliente_id IS NULL THEN
    IF v_tipo_documento = 'OS' THEN
      SELECT array_agg(DISTINCT o.clienteid) INTO v_clientes
        FROM public.ordemservico o WHERE o.id = ANY (v_documentos);
    ELSE
      SELECT array_agg(DISTINCT v.clienteid) INTO v_clientes
        FROM public.venda v WHERE v.id = ANY (v_documentos);
    END IF;

    IF array_length(v_clientes, 1) = 1 THEN
      v_cliente_id := v_clientes[1];
    END IF;
  END IF;

  IF v_cliente_id IS NOT NULL AND (v_nome IS NULL OR v_cpfcnpj IS NULL) THEN
    SELECT coalesce(v_nome, c.nomerazaosocial), coalesce(v_cpfcnpj, c.cpfcnpj)
      INTO v_nome, v_cpfcnpj
      FROM public.cliente c WHERE c.id = v_cliente_id;
  END IF;

  v_descricao_grupo := coalesce(
    nullif(btrim(p_payload->>'descricao'), ''),
    'Pagamento múltiplo de ' || array_length(v_documentos, 1) || ' documento(s)');

  INSERT INTO public.pagamento_multiplo (
    descricao, modo, tipo_documento, valor_total, data, banco_id, metodopagamento, created_by
  ) VALUES (
    v_descricao_grupo, v_modo, v_tipo_documento, v_valor_total, v_data,
    v_banco_id, v_metodo, v_created_by
  ) RETURNING id INTO v_grupo_id;

  SELECT max((item->>'total_parcelas')::integer) INTO v_total_parcelas
    FROM jsonb_array_elements(p_payload->'linhas') AS item;
  v_total_parcelas := greatest(coalesce(v_total_parcelas, 1), 1);

  FOR v_parcela IN
    SELECT (item->>'parcela')::integer AS numero,
           round(sum((item->>'valor')::numeric), 2) AS valor,
           min(nullif(item->>'vencimento_em', '')) AS vencimento
      FROM jsonb_array_elements(p_payload->'linhas') AS item
     GROUP BY (item->>'parcela')::integer
     ORDER BY 1
  LOOP
    v_indice := v_indice + 1;

    -- O líquido acompanha a proporção do valor. A última parcela leva a sobra
    -- para a soma dos líquidos fechar exatamente com o informado.
    IF v_indice = v_total_parcelas THEN
      v_liquido := round(v_liquido_total - v_liquido_acumulado, 2);
    ELSE
      v_liquido := round(v_parcela.valor * v_liquido_total / v_valor_total, 2);
      v_liquido_acumulado := v_liquido_acumulado + v_liquido;
    END IF;

    v_descricao := v_descricao_grupo;
    IF v_total_parcelas > 1 THEN
      v_descricao := v_descricao || ' - Parcela ' || v_parcela.numero || '/' || v_total_parcelas;
    END IF;

    INSERT INTO public.transacao (
      descricao, valor, "valorLiquido", data, metodopagamento, categoria, categoria_id,
      plano_de_conta_id, centro_custo_id, tipo, cliente_id, banco_id,
      nomepagador, cpfcnpjpagador, pendente, pago_em,
      ordemservicoid, vendaid, pagamento_multiplo_id, created_by
    ) VALUES (
      v_descricao,
      v_parcela.valor,
      greatest(v_liquido, 0),
      coalesce(v_parcela.vencimento::timestamptz, v_data),
      v_metodo, v_categoria, v_categoria_id, v_plano_id, v_centro_id,
      'RECEITA'::public.tipos_transacao, v_cliente_id,
      CASE WHEN v_pendente THEN NULL ELSE v_banco_id END,
      coalesce(v_nome, 'Diversos'),
      coalesce(v_cpfcnpj, 'NÃO INFORMADO'),
      v_pendente,
      CASE WHEN v_pendente THEN NULL ELSE v_data END,
      NULL, NULL,
      v_grupo_id, v_created_by
    ) RETURNING id INTO v_transacao_id;

    INSERT INTO public.pagamento_multiplo_rateio (
      pagamento_multiplo_id, transacao_id, tipo_documento, documento_id, valor
    )
    SELECT v_grupo_id, v_transacao_id, v_tipo_documento,
           (item->>'documento_id')::integer,
           round((item->>'valor')::numeric, 2)
      FROM jsonb_array_elements(p_payload->'linhas') AS item
     WHERE (item->>'parcela')::integer = v_parcela.numero
       AND round((item->>'valor')::numeric, 2) > 0;
  END LOOP;

  FOREACH v_doc_id IN ARRAY v_documentos LOOP
    IF v_tipo_documento = 'OS' THEN
      SELECT r.total_devido, r.valor_comprometido
        INTO v_devido, v_comprometido
        FROM public.resumo_financeiro_os(v_doc_id) r;
    ELSE
      SELECT round(
               greatest(coalesce(v.valortotal, 0), 0) +
               CASE
                 WHEN v.acrescimo_financeiro_tipo = 'PORCENTAGEM' THEN
                   greatest(coalesce(v.valortotal, 0), 0) *
                   least(greatest(coalesce(v.acrescimo_financeiro_valor, 0), 0), 100) / 100
                 WHEN v.acrescimo_financeiro_tipo = 'FIXO' THEN
                   greatest(coalesce(v.acrescimo_financeiro_valor, 0), 0)
                 ELSE 0
               END, 2)
        INTO v_devido
        FROM public.venda v WHERE v.id = v_doc_id;

      SELECT coalesce(round(sum(r.valor), 2), 0) INTO v_comprometido
        FROM public.recebimento_por_documento r
       WHERE r.tipo_documento = 'VENDA' AND r.documento_id = v_doc_id;
    END IF;

    IF coalesce(v_devido, 0) <= 0 THEN
      RAISE EXCEPTION 'O documento #% não possui valor financeiro disponível para pagamento.',
        v_doc_id USING ERRCODE = '23514';
    END IF;
    IF round(coalesce(v_comprometido, 0), 2) > v_devido THEN
      RAISE EXCEPTION 'O rateio ultrapassa o saldo do documento #%: comprometido % de %.',
        v_doc_id, v_comprometido, v_devido USING ERRCODE = '23514';
    END IF;
  END LOOP;

  RETURN v_grupo_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.processar_devolucao_mercadolivre_estoque(p_empresa_id integer, p_request_key uuid, p_ml_claim_id text, p_produto_id integer, p_disposition text, p_quantity integer, p_note text DEFAULT NULL::text, p_processed_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_claim public.mercadolivre_claim%rowtype;
  v_order public.mercadolivre_order%rowtype;
  v_existing public.mercadolivre_return_inventory%rowtype;
  v_sold_quantity integer;
  v_processed_quantity integer := 0;
  v_deducted_quantity integer := 0;
  v_restored_quantity integer := 0;
  v_stock_before integer;
  v_stock_after integer;
  v_disposition text := upper(btrim(coalesce(p_disposition, '')));
begin
  if p_empresa_id is null or p_request_key is null or p_ml_claim_id is null or btrim(p_ml_claim_id) = '' or p_produto_id is null then
    raise exception 'Empresa, operação, reclamação e produto são obrigatórios.' using errcode = '22023';
  end if;
  if v_disposition not in ('RESTOCK', 'DAMAGED', 'NOT_RETURNED') then
    raise exception 'Destinação da devolução inválida.' using errcode = '22023';
  end if;
  if v_disposition in ('DAMAGED', 'NOT_RETURNED') and nullif(btrim(coalesce(p_note, '')), '') is null then
    raise exception 'Informe uma observação para itens avariados ou não retornados.' using errcode = '22023';
  end if;
  if p_quantity is null or p_quantity <= 0 then
    raise exception 'A quantidade conferida deve ser maior que zero.' using errcode = '22023';
  end if;

  select * into v_claim
    from public.mercadolivre_claim
   where empresa_id = p_empresa_id
     and ml_claim_id = btrim(p_ml_claim_id)
   for update;
  if not found then
    raise exception 'Devolução do Mercado Livre não encontrada.' using errcode = 'P0002';
  end if;
  if v_claim.return_id is null then
    raise exception 'A reclamação ainda não possui uma devolução identificada pelo Mercado Livre.' using errcode = '22023';
  end if;

  select * into v_order
    from public.mercadolivre_order
   where id = v_claim.order_id
     and empresa_id = p_empresa_id;
  if not found or v_order.venda_id is null then
    raise exception 'A devolução não possui uma venda vinculada no ERP.' using errcode = 'P0002';
  end if;

  select * into v_existing
    from public.mercadolivre_return_inventory
   where request_key = p_request_key;
  if found then
    return jsonb_build_object(
      'id', v_existing.id,
      'alreadyProcessed', true,
      'disposition', v_existing.disposition,
      'quantity', v_existing.quantity,
      'restoredQuantity', v_existing.restored_quantity,
      'stockBefore', v_existing.stock_before,
      'stockAfter', v_existing.stock_after,
      'processedAt', v_existing.processed_at
    );
  end if;

  select coalesce(sum(quantidade), 0)::integer into v_sold_quantity
    from public.vendaproduto
   where venda_id = v_order.venda_id
     and produtoid = p_produto_id;
  if v_sold_quantity <= 0 then
    raise exception 'O produto informado não pertence à venda desta devolução.' using errcode = '22023';
  end if;
  if p_quantity > v_sold_quantity then
    raise exception 'A quantidade devolvida não pode superar a quantidade vendida (%).', v_sold_quantity using errcode = '22023';
  end if;

  select coalesce(sum(quantity), 0)::integer into v_processed_quantity
    from public.mercadolivre_return_inventory
   where claim_id = v_claim.id
     and produto_id = p_produto_id;
  if p_quantity > v_sold_quantity - v_processed_quantity then
    raise exception 'A quantidade informada supera o saldo pendente de conferência (%).', greatest(v_sold_quantity - v_processed_quantity, 0)
      using errcode = '22023';
  end if;

  select estoque into v_stock_before
    from public.produto
   where id = p_produto_id
   for update;
  if not found then
    raise exception 'Produto não encontrado no estoque.' using errcode = 'P0002';
  end if;

  select coalesce(quantidade, 0)::integer into v_deducted_quantity
    from public.vendaproduto_baixa
   where venda_id = v_order.venda_id
     and produtoid = p_produto_id;
  v_deducted_quantity := coalesce(v_deducted_quantity, 0);

  if v_disposition = 'RESTOCK' then
    v_restored_quantity := least(p_quantity, v_deducted_quantity);
    if v_restored_quantity > 0 then
      perform public.fn_sincronizar_baixa_estoque_marketplace(
        v_order.venda_id,
        p_produto_id,
        v_deducted_quantity - v_restored_quantity
      );
    end if;
  end if;

  select estoque into v_stock_after from public.produto where id = p_produto_id;

  insert into public.mercadolivre_return_inventory (
    empresa_id, request_key, claim_id, order_id, venda_id, produto_id, disposition,
    quantity, restored_quantity, stock_before, stock_after, note, processed_by
  ) values (
    p_empresa_id, p_request_key, v_claim.id, v_order.id, v_order.venda_id, p_produto_id, v_disposition,
    p_quantity, v_restored_quantity, v_stock_before, v_stock_after,
    nullif(btrim(coalesce(p_note, '')), ''), p_processed_by
  ) returning * into v_existing;

  return jsonb_build_object(
    'id', v_existing.id,
    'alreadyProcessed', false,
    'disposition', v_existing.disposition,
    'quantity', v_existing.quantity,
    'restoredQuantity', v_existing.restored_quantity,
    'stockBefore', v_existing.stock_before,
    'stockAfter', v_existing.stock_after,
    'processedAt', v_existing.processed_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.abonar_transacao_pendente(p_transacao_id bigint, p_abonado_por uuid DEFAULT NULL::uuid, p_motivo text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_atual public.transacao%ROWTYPE;
  v_transacao public.transacao%ROWTYPE;
BEGIN
  IF p_transacao_id IS NULL OR p_transacao_id <= 0 THEN
    RAISE EXCEPTION 'Transação inválida.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_atual FROM public.transacao
   WHERE id = p_transacao_id AND is_deleted = false FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Transação não encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF NOT coalesce(v_atual.pendente, false) THEN
    RAISE EXCEPTION 'A transação já foi baixada.' USING ERRCODE = '23505';
  END IF;

  IF upper(v_atual.tipo::text) <> 'RECEITA' THEN
    RAISE EXCEPTION 'Só é possível abonar uma cobrança a receber.' USING ERRCODE = '22023';
  END IF;
  IF v_atual.ordemservicoid IS NULL AND v_atual.vendaid IS NULL THEN
    RAISE EXCEPTION 'Este lançamento não está ligado a uma OS ou venda.' USING ERRCODE = '22023';
  END IF;
  IF v_atual.evento_financeiro_id IS NOT NULL THEN
    RAISE EXCEPTION 'Este lançamento é um evento financeiro da OS, não uma cobrança avulsa.' USING ERRCODE = '22023';
  END IF;
  IF v_atual.adiantamento_id IS NOT NULL THEN
    RAISE EXCEPTION
      'Este título está ligado à antecipação #%. Desfaça a antecipação primeiro.',
      v_atual.adiantamento_id USING ERRCODE = '22023';
  END IF;
  IF coalesce(v_atual.eh_adiantamento, false) THEN
    RAISE EXCEPTION 'Isto é uma antecipação, não uma cobrança avulsa.' USING ERRCODE = '22023';
  END IF;
  IF v_atual.pagamento_multiplo_id IS NOT NULL THEN
    RAISE EXCEPTION
      'Esta cobrança faz parte do pagamento múltiplo #%. Desfaça o grupo primeiro.',
      v_atual.pagamento_multiplo_id USING ERRCODE = '22023';
  END IF;

  UPDATE public.transacao
     SET pendente = false,
         banco_id = NULL,
         metodopagamento = NULL,
         baixado_por = NULL,
         pago_em = now(),
         abonado = true,
         abonado_por = p_abonado_por,
         abonado_em = now(),
         abono_motivo = nullif(btrim(coalesce(p_motivo, '')), ''),
         updated_at = now()
   WHERE id = p_transacao_id
     AND pendente = true
     AND is_deleted = false
  RETURNING * INTO v_transacao;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'A transação já foi baixada.' USING ERRCODE = '23505';
  END IF;

  INSERT INTO public.transacao_baixa_historico (
    transacao_id, vencimento_em, pago_em, baixado_por, banco_id, metodopagamento, operacao
  ) VALUES (
    v_transacao.id, coalesce(v_transacao.vencimento_em, v_transacao.data), v_transacao.pago_em,
    p_abonado_por, NULL, NULL, 'ABONO'
  );

  IF v_transacao.ordemservicoid IS NOT NULL THEN
    PERFORM public.recalcular_status_financeiro_os(v_transacao.ordemservicoid);
  END IF;
  IF v_transacao.vendaid IS NOT NULL THEN
    PERFORM public.recalcular_status_financeiro_venda(v_transacao.vendaid);
  END IF;

  RETURN jsonb_build_object(
    'id', v_transacao.id,
    'pendente', false,
    'abonado', true,
    'abonado_em', v_transacao.abonado_em
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_cliente_saldo_movimento()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.recalcular_saldo_credito_cliente(new.cliente_id);
  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.ajustar_saldo_credito_cliente(p_cliente_id integer, p_sentido text, p_valor numeric, p_motivo text DEFAULT NULL::text, p_usuario uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sentido text;
  v_valor numeric(14,2);
  v_saldo_anterior numeric(14,2);
  v_saldo_resultante numeric(14,2);
  v_movimento_id bigint;
BEGIN
  v_sentido := upper(btrim(coalesce(p_sentido, '')));
  IF v_sentido NOT IN ('CREDITO', 'DEBITO') THEN
    RAISE EXCEPTION 'Informe se o ajuste adiciona (CREDITO) ou remove (DEBITO) saldo.'
      USING ERRCODE = '22023';
  END IF;

  v_valor := round(coalesce(p_valor, 0), 2);
  IF v_valor <= 0 THEN
    RAISE EXCEPTION 'O valor do ajuste deve ser maior que zero.' USING ERRCODE = '22023';
  END IF;

  -- Trava a linha do cliente: dois ajustes simultâneos não podem ler o mesmo
  -- saldo e gravar cada um o seu.
  SELECT c.saldo_credito INTO v_saldo_anterior
    FROM public.cliente c
   WHERE c.id = p_cliente_id AND c.is_deleted = false
     FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cliente não encontrado.' USING ERRCODE = 'P0002';
  END IF;

  v_saldo_anterior := coalesce(v_saldo_anterior, 0);
  v_saldo_resultante := CASE
    WHEN v_sentido = 'CREDITO' THEN v_saldo_anterior + v_valor
    ELSE v_saldo_anterior - v_valor
  END;

  IF v_saldo_resultante < 0 THEN
    RAISE EXCEPTION
      'O cliente tem % de crédito: não dá para remover %.',
      to_char(v_saldo_anterior, 'FM999999990.00'), to_char(v_valor, 'FM999999990.00')
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.cliente_saldo_movimento (
    cliente_id, sentido, origem, acao, valor,
    saldo_anterior, saldo_resultante, motivo, created_by
  ) VALUES (
    p_cliente_id, v_sentido, 'MANUAL', 'REGISTRO', v_valor,
    v_saldo_anterior, round(v_saldo_resultante, 2),
    nullif(btrim(coalesce(p_motivo, '')), ''), p_usuario
  ) RETURNING id INTO v_movimento_id;

  RETURN jsonb_build_object(
    'movimento_id', v_movimento_id,
    'cliente_id', p_cliente_id,
    'sentido', v_sentido,
    'valor', v_valor,
    'saldo_anterior', v_saldo_anterior,
    'saldo', round(v_saldo_resultante, 2)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.baixar_com_credito_cliente(p_transacao_id bigint, p_pago_em timestamp with time zone, p_plano_de_conta_id integer DEFAULT NULL::integer, p_centro_custo_id integer DEFAULT NULL::integer, p_baixado_por uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_atual public.transacao%ROWTYPE;
  v_transacao public.transacao%ROWTYPE;
  v_tipo text;
  v_cliente_id integer;
  v_sentido text;
  v_valor numeric(14,2);
  v_saldo_anterior numeric(14,2);
  v_saldo_resultante numeric(14,2);
  v_movimento_id bigint;
BEGIN
  IF p_transacao_id IS NULL OR p_transacao_id <= 0 THEN
    RAISE EXCEPTION 'Transação inválida.' USING ERRCODE = '22023';
  END IF;
  IF p_pago_em IS NULL THEN
    RAISE EXCEPTION 'Data do pagamento obrigatória.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_atual FROM public.transacao
   WHERE id = p_transacao_id AND is_deleted = false FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Transação não encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF NOT coalesce(v_atual.pendente, false) THEN
    RAISE EXCEPTION 'A transação já foi baixada.' USING ERRCODE = '23505';
  END IF;

  v_tipo := upper(v_atual.tipo::text);
  IF v_tipo NOT IN ('RECEITA', 'DESPESA') THEN
    RAISE EXCEPTION
      'Crédito do cliente vale para título a receber ou a pagar, não para depósito ou saque.'
      USING ERRCODE = '22023';
  END IF;

  -- As mesmas recusas do abono: são conjuntos que se liquidam juntos, e mexer
  -- numa perna sozinha desmonta a conta do grupo.
  IF v_atual.baixa_de_transacao_id IS NOT NULL THEN
    RAISE EXCEPTION
      'Esta linha é o dinheiro de uma baixa parcial, não um título.' USING ERRCODE = '22023';
  END IF;
  IF v_atual.adiantamento_id IS NOT NULL THEN
    RAISE EXCEPTION
      'Este título está ligado à antecipação #%. Desfaça a antecipação primeiro.',
      v_atual.adiantamento_id USING ERRCODE = '22023';
  END IF;
  IF coalesce(v_atual.eh_adiantamento, false) THEN
    RAISE EXCEPTION 'Isto é uma antecipação, não uma cobrança avulsa.' USING ERRCODE = '22023';
  END IF;
  IF v_atual.pagamento_multiplo_id IS NOT NULL THEN
    RAISE EXCEPTION
      'Esta cobrança faz parte do pagamento múltiplo #%. Desfaça o grupo primeiro.',
      v_atual.pagamento_multiplo_id USING ERRCODE = '22023';
  END IF;
  IF v_atual.transferencia_id IS NOT NULL THEN
    RAISE EXCEPTION
      'Esta linha é uma perna de transferência entre contas.' USING ERRCODE = '22023';
  END IF;
  -- O crédito quita o título inteiro, então um título que já recebeu pagamento
  -- em partes não entra: o resto dele mora nas filhas, e fechá-lo por aqui
  -- deixaria o dinheiro contado duas vezes.
  IF coalesce(v_atual.valor_baixado, 0) > 0 THEN
    RAISE EXCEPTION
      'Este título já foi pago em partes. O crédito do cliente só quita título inteiro.'
      USING ERRCODE = '22023';
  END IF;

  -- ------------------------------------------------------------- de quem é
  IF v_tipo = 'RECEITA' THEN
    v_cliente_id := coalesce(
      v_atual.cliente_id,
      (SELECT os.clienteid FROM public.ordemservico os WHERE os.id = v_atual.ordemservicoid),
      (SELECT vd.clienteid FROM public.venda vd WHERE vd.id = v_atual.vendaid)
    );
  ELSE
    -- Numa despesa o vínculo com OS/venda é do fornecedor, não do cliente: o
    -- único dono possível é o que foi gravado na própria linha.
    v_cliente_id := v_atual.cliente_id;
  END IF;

  IF v_cliente_id IS NULL THEN
    RAISE EXCEPTION
      'Este lançamento não tem cliente vinculado. Informe o cliente nele antes de usar o crédito.'
      USING ERRCODE = '22023';
  END IF;

  v_valor := round(coalesce(nullif(v_atual."valorLiquido", 0), v_atual.valor, 0), 2);
  IF v_valor <= 0 THEN
    RAISE EXCEPTION 'O título não tem valor a baixar.' USING ERRCODE = '22023';
  END IF;

  -- A receber consome a carteira; a pagar abastece.
  v_sentido := CASE WHEN v_tipo = 'RECEITA' THEN 'DEBITO' ELSE 'CREDITO' END;

  SELECT c.saldo_credito INTO v_saldo_anterior
    FROM public.cliente c
   WHERE c.id = v_cliente_id AND c.is_deleted = false
     FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cliente não encontrado.' USING ERRCODE = 'P0002';
  END IF;

  v_saldo_anterior := coalesce(v_saldo_anterior, 0);
  v_saldo_resultante := CASE
    WHEN v_sentido = 'CREDITO' THEN v_saldo_anterior + v_valor
    ELSE v_saldo_anterior - v_valor
  END;

  IF v_saldo_resultante < 0 THEN
    RAISE EXCEPTION
      'O cliente tem R$ % de crédito e este título é de R$ %.',
      to_char(v_saldo_anterior, 'FM999999990.00'),
      to_char(v_valor, 'FM999999990.00')
      USING ERRCODE = '22023';
  END IF;

  -- ------------------------------------------------------------- a baixa
  UPDATE public.transacao
     SET vencimento_em = coalesce(vencimento_em, data),
         data = p_pago_em,
         pago_em = p_pago_em,
         pendente = false,
         -- Nunca passa por conta: é isto que mantém a linha fora do Fluxo e do
         -- saldo dos bancos, como já acontece no título quitado por antecipação
         -- e no abonado.
         banco_id = NULL,
         metodopagamento = 'CREDITO CLIENTE'::public.metodo_pagamento,
         baixado_por = p_baixado_por,
         plano_de_conta_id = coalesce(p_plano_de_conta_id, plano_de_conta_id),
         centro_custo_id = coalesce(p_centro_custo_id, centro_custo_id),
         updated_at = now()
   WHERE id = p_transacao_id
     AND pendente = true
     AND is_deleted = false
  RETURNING * INTO v_transacao;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'A transação já foi baixada.' USING ERRCODE = '23505';
  END IF;

  INSERT INTO public.cliente_saldo_movimento (
    cliente_id, sentido, origem, acao, valor,
    saldo_anterior, saldo_resultante, transacao_id, motivo, created_by
  ) VALUES (
    v_cliente_id, v_sentido, 'TRANSACAO', 'REGISTRO', v_valor,
    v_saldo_anterior, round(v_saldo_resultante, 2), v_transacao.id,
    CASE
      WHEN v_sentido = 'DEBITO' THEN 'Baixa do título #' || v_transacao.id
      ELSE 'Crédito gerado pelo título #' || v_transacao.id
    END,
    p_baixado_por
  ) RETURNING id INTO v_movimento_id;

  INSERT INTO public.transacao_baixa_historico (
    transacao_id, vencimento_em, pago_em, baixado_por, banco_id, metodopagamento, operacao
  ) VALUES (
    v_transacao.id, v_transacao.vencimento_em, v_transacao.pago_em,
    p_baixado_por, NULL, 'CREDITO CLIENTE', 'BAIXA'
  );

  IF v_tipo = 'RECEITA' AND v_transacao.evento_financeiro_id IS NULL THEN
    IF v_transacao.ordemservicoid IS NOT NULL THEN
      PERFORM public.recalcular_status_financeiro_os(v_transacao.ordemservicoid);
    END IF;
    IF v_transacao.vendaid IS NOT NULL THEN
      PERFORM public.recalcular_status_financeiro_venda(v_transacao.vendaid);
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'id', v_transacao.id,
    'pendente', false,
    'cliente_id', v_cliente_id,
    'sentido', v_sentido,
    'valor', v_valor,
    'movimento_id', v_movimento_id,
    'saldo', round(v_saldo_resultante, 2)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.estornar_baixa_transacao(p_transacao_id bigint, p_estornado_por uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_transacao public.transacao%ROWTYPE;
  v_acrescimos_removidos numeric(14,2) := 0;
  v_valor_reaberto numeric(14,2);
  v_baixa_do_titulo boolean := false;
  v_titulo bigint;
  v_movimento public.cliente_saldo_movimento%ROWTYPE;
  v_sentido_estorno text;
  v_saldo_anterior numeric(14,2);
  v_saldo_resultante numeric(14,2);
BEGIN
  SELECT * INTO v_transacao
    FROM public.transacao
   WHERE id = p_transacao_id AND is_deleted = false
     FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Transação não encontrada.' USING ERRCODE = 'P0002';
  END IF;

  IF v_transacao.baixa_de_transacao_id IS NOT NULL THEN
    v_titulo := v_transacao.baixa_de_transacao_id;

    INSERT INTO public.transacao_baixa_historico (
      transacao_id, vencimento_em, pago_em, baixado_por, banco_id, metodopagamento, operacao
    ) VALUES (
      v_titulo, coalesce(v_transacao.vencimento_em, v_transacao.data),
      coalesce(v_transacao.pago_em, v_transacao.data),
      p_estornado_por, v_transacao.banco_id, v_transacao.metodopagamento, 'ESTORNO'
    );

    DELETE FROM public.transacao WHERE id = p_transacao_id;

    SELECT * INTO v_transacao FROM public.transacao WHERE id = v_titulo;

    IF upper(v_transacao.tipo::text) = 'RECEITA' THEN
      IF v_transacao.ordemservicoid IS NOT NULL THEN
        PERFORM public.recalcular_status_financeiro_os(v_transacao.ordemservicoid);
      END IF;
      IF v_transacao.vendaid IS NOT NULL THEN
        PERFORM public.recalcular_status_financeiro_venda(v_transacao.vendaid);
      END IF;
    END IF;

    RETURN jsonb_build_object(
      'id', v_titulo,
      'baixa_estornada', p_transacao_id,
      'valor_baixado', v_transacao.valor_baixado,
      'pendente', v_transacao.pendente,
      'parcial', true
    );
  END IF;

  IF coalesce(v_transacao.pendente, false) THEN
    RAISE EXCEPTION 'Esta transação não está liquidada: não há baixa a estornar.'
      USING ERRCODE = '22023';
  END IF;

  IF coalesce(v_transacao.abonado, false) THEN
    UPDATE public.transacao
       SET pendente = true,
           data = coalesce(vencimento_em, data),
           pago_em = NULL,
           abonado = false,
           abonado_por = NULL,
           abonado_em = NULL,
           abono_motivo = NULL,
           updated_at = now()
     WHERE id = p_transacao_id;

    INSERT INTO public.transacao_baixa_historico (
      transacao_id, vencimento_em, pago_em, baixado_por, banco_id, metodopagamento, operacao
    ) VALUES (
      v_transacao.id, coalesce(v_transacao.vencimento_em, v_transacao.data),
      coalesce(v_transacao.pago_em, v_transacao.data),
      p_estornado_por, NULL, NULL, 'ESTORNO'
    );

    IF upper(v_transacao.tipo::text) = 'RECEITA' THEN
      IF v_transacao.ordemservicoid IS NOT NULL THEN
        PERFORM public.recalcular_status_financeiro_os(v_transacao.ordemservicoid);
      END IF;
      IF v_transacao.vendaid IS NOT NULL THEN
        PERFORM public.recalcular_status_financeiro_venda(v_transacao.vendaid);
      END IF;
    END IF;

    RETURN jsonb_build_object(
      'id', v_transacao.id,
      'pendente', true,
      'abono_desfeito', true
    );
  END IF;

  -- ------------------------------------------------- baixa por crédito
  --
  -- A última linha do razão daquela transação diz se ainda há o que desfazer:
  -- REGISTRO é baixa em pé, ESTORNO é ciclo já fechado.
  SELECT * INTO v_movimento
    FROM public.cliente_saldo_movimento m
   WHERE m.transacao_id = p_transacao_id
     AND m.origem = 'TRANSACAO'
   ORDER BY m.id DESC
   LIMIT 1;

  IF FOUND AND v_movimento.acao = 'REGISTRO' THEN
    v_sentido_estorno := CASE WHEN v_movimento.sentido = 'DEBITO' THEN 'CREDITO' ELSE 'DEBITO' END;

    SELECT c.saldo_credito INTO v_saldo_anterior
      FROM public.cliente c
     WHERE c.id = v_movimento.cliente_id
       FOR UPDATE;

    v_saldo_anterior := coalesce(v_saldo_anterior, 0);
    v_saldo_resultante := CASE
      WHEN v_sentido_estorno = 'CREDITO' THEN v_saldo_anterior + v_movimento.valor
      ELSE v_saldo_anterior - v_movimento.valor
    END;

    -- Só acontece no título a pagar: o crédito que ele gerou já foi gasto em
    -- outra cobrança, e tirá-lo agora deixaria a carteira negativa.
    IF v_saldo_resultante < 0 THEN
      RAISE EXCEPTION
        'O crédito gerado por esta baixa já foi usado: o cliente tem R$ % e o estorno retiraria R$ %.',
        to_char(v_saldo_anterior, 'FM999999990.00'),
        to_char(v_movimento.valor, 'FM999999990.00')
        USING ERRCODE = '22023';
    END IF;

    UPDATE public.transacao
       SET pendente = true,
           data = coalesce(vencimento_em, data),
           pago_em = NULL,
           baixado_por = NULL,
           updated_at = now()
     WHERE id = p_transacao_id;

    INSERT INTO public.cliente_saldo_movimento (
      cliente_id, sentido, origem, acao, valor,
      saldo_anterior, saldo_resultante, transacao_id, motivo, created_by
    ) VALUES (
      v_movimento.cliente_id, v_sentido_estorno, 'TRANSACAO', 'ESTORNO', v_movimento.valor,
      v_saldo_anterior, round(v_saldo_resultante, 2), p_transacao_id,
      'Estorno da baixa do título #' || p_transacao_id, p_estornado_por
    );

    INSERT INTO public.transacao_baixa_historico (
      transacao_id, vencimento_em, pago_em, baixado_por, banco_id, metodopagamento, operacao
    ) VALUES (
      v_transacao.id, coalesce(v_transacao.vencimento_em, v_transacao.data),
      coalesce(v_transacao.pago_em, v_transacao.data),
      p_estornado_por, NULL, v_transacao.metodopagamento, 'ESTORNO'
    );

    IF upper(v_transacao.tipo::text) = 'RECEITA' THEN
      IF v_transacao.ordemservicoid IS NOT NULL THEN
        PERFORM public.recalcular_status_financeiro_os(v_transacao.ordemservicoid);
      END IF;
      IF v_transacao.vendaid IS NOT NULL THEN
        PERFORM public.recalcular_status_financeiro_venda(v_transacao.vendaid);
      END IF;
    END IF;

    RETURN jsonb_build_object(
      'id', v_transacao.id,
      'pendente', true,
      'credito_devolvido', v_movimento.valor,
      'saldo', round(v_saldo_resultante, 2)
    );
  END IF;

  IF v_transacao.adiantamento_id IS NOT NULL THEN
    SELECT coalesce(a.adiantamento_manteve_pendentes, false) INTO v_baixa_do_titulo
      FROM public.transacao a WHERE a.id = v_transacao.adiantamento_id;

    IF NOT coalesce(v_baixa_do_titulo, false) THEN
      RAISE EXCEPTION
        'Este título foi liquidado pela antecipação #%. Desfaça a antecipação: ela devolve este título e os irmãos para em aberto de uma vez.',
        v_transacao.adiantamento_id USING ERRCODE = '22023';
    END IF;
  END IF;

  IF coalesce(v_transacao.eh_adiantamento, false) THEN
    RAISE EXCEPTION
      'Esta é uma antecipação, não a baixa de um título. Excluí-la é que devolve os títulos para em aberto.'
      USING ERRCODE = '22023';
  END IF;

  IF v_transacao.pagamento_multiplo_id IS NOT NULL THEN
    RAISE EXCEPTION
      'Esta baixa é uma perna do pagamento múltiplo #%. Desfaça o pagamento inteiro.',
      v_transacao.pagamento_multiplo_id USING ERRCODE = '22023';
  END IF;

  /*
   * Título comum pago em partes: cada pagamento tem data, banco e valor próprios
   * e sai do extrato sozinho, então o estorno é de cada um.
   *
   * O antecipado é o contrário: a baixa foi UMA — ela quitou o título e criou o
   * repasse no mesmo ato —, e desfazê-la desfaz as duas coisas.
   */
  IF v_transacao.adiantamento_id IS NULL AND EXISTS (
    SELECT 1 FROM public.transacao f
     WHERE f.baixa_de_transacao_id = p_transacao_id AND f.is_deleted = false
  ) THEN
    RAISE EXCEPTION
      'Este título foi pago em partes. Estorne os pagamentos dele, um a um.'
      USING ERRCODE = '22023';
  END IF;

  IF v_transacao.adiantamento_id IS NOT NULL THEN
    DELETE FROM public.transacao WHERE baixa_de_transacao_id = p_transacao_id;
  END IF;

  UPDATE public.transacao
     SET pendente = true,
         data = coalesce(vencimento_em, data),
         pago_em = NULL,
         baixado_por = NULL,
         banco_id = CASE WHEN v_transacao.adiantamento_id IS NOT NULL THEN NULL ELSE banco_id END,
         updated_at = now()
   WHERE id = p_transacao_id;

  WITH removidos AS (
    DELETE FROM public.transacao_ajuste
     WHERE transacao_id = p_transacao_id
       AND natureza = 'ACRESCIMO'
    RETURNING valor_calculado
  )
  SELECT coalesce(sum(valor_calculado), 0) INTO v_acrescimos_removidos FROM removidos;

  v_valor_reaberto := round(coalesce(v_transacao.valor_base, v_transacao.valor), 2);

  UPDATE public.transacao
     SET valor = v_valor_reaberto,
         valor_acrescimos = 0,
         "valorLiquido" = round(v_valor_reaberto - coalesce(valor_descontos, 0), 2),
         updated_at = now()
   WHERE id = p_transacao_id;

  INSERT INTO public.transacao_baixa_historico (
    transacao_id, vencimento_em, pago_em, baixado_por, banco_id, metodopagamento, operacao
  ) VALUES (
    v_transacao.id,
    coalesce(v_transacao.vencimento_em, v_transacao.data),
    coalesce(v_transacao.pago_em, v_transacao.data),
    p_estornado_por,
    v_transacao.banco_id,
    v_transacao.metodopagamento,
    'ESTORNO'
  );

  RETURN jsonb_build_object(
    'id', v_transacao.id,
    'pendente', true,
    'valor', v_valor_reaberto,
    'acrescimos_removidos', v_acrescimos_removidos,
    'vencimento_em', coalesce(v_transacao.vencimento_em, v_transacao.data)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.registrar_entrada_confirmada(p_entrada jsonb, p_itens jsonb, p_transacoes jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result jsonb;
  v_entrada_id bigint;
  v_item record;
  v_entrada_item_id bigint;
  v_numero_item integer;
  v_competencia timestamptz;
BEGIN
  SELECT public.registrar_entrada_confirmada_sem_numero_item(
    p_entrada,
    p_itens,
    p_transacoes
  ) INTO v_result;
  v_entrada_id := (v_result->>'entrada_id')::bigint;

  FOR v_item IN
    SELECT value, ordinality
      FROM jsonb_array_elements(p_itens) WITH ORDINALITY
  LOOP
    v_numero_item := nullif(v_item.value->>'numero_item_fiscal', '')::integer;
    IF v_numero_item IS NOT NULL AND (v_numero_item < 1 OR v_numero_item > 990) THEN
      RAISE EXCEPTION 'O número fiscal do item deve ficar entre 1 e 990.' USING ERRCODE = '22023';
    END IF;

    SELECT id
      INTO v_entrada_item_id
      FROM public.entradaitens
     WHERE entrada_id = v_entrada_id
     ORDER BY id
     OFFSET (v_item.ordinality - 1)
     LIMIT 1;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Não foi possível reconciliar os itens da entrada fiscal.' USING ERRCODE = '23514';
    END IF;

    UPDATE public.entradaitens
       SET numero_item_fiscal = v_numero_item
     WHERE id = v_entrada_item_id;
  END LOOP;

  IF p_entrada ? 'tributos' THEN
    SELECT coalesce(data_emissao, created_at) INTO v_competencia
      FROM public.entrada WHERE id = v_entrada_id;
    PERFORM public.registrar_eventos_dre_entrada(
      'ENTRADA', v_entrada_id, v_competencia, p_entrada->'tributos',
      nullif(p_entrada->>'created_by', '')::uuid
    );
  END IF;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.nfe_saida_item_vinculo_validar()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_modelo text;
  v_status text;
  v_excluida boolean;
  v_saida_id bigint;
  v_produto_id integer;
  v_quantidade numeric;
  v_entrada_produto_id integer;
BEGIN
  SELECT modelo::text, status::text, coalesce(is_deleted, false)
    INTO v_modelo, v_status, v_excluida
    FROM public.nfe
   WHERE id = NEW.nfe_id;

  IF NOT FOUND OR v_modelo <> 'NFE' THEN
    RAISE EXCEPTION 'O vínculo de saída exige uma NF-e existente.' USING ERRCODE = '23514';
  END IF;

  SELECT saida_id, produto_id, quantidade
    INTO v_saida_id, v_produto_id, v_quantidade
    FROM public.estoque_saida_item
   WHERE id = NEW.saida_item_id;

  IF NOT FOUND OR v_saida_id <> NEW.saida_id THEN
    RAISE EXCEPTION 'O item não pertence à saída informada.' USING ERRCODE = '23514';
  END IF;

  IF round(NEW.quantidade, 4) <> round(v_quantidade, 4) THEN
    RAISE EXCEPTION 'A quantidade fiscal deve corresponder à baixa da saída.' USING ERRCODE = '23514';
  END IF;

  IF NEW.entrada_item_origem_id IS NOT NULL THEN
    SELECT produto_id
      INTO v_entrada_produto_id
      FROM public.entradaitens
     WHERE id = NEW.entrada_item_origem_id;
    IF NOT FOUND OR v_entrada_produto_id <> v_produto_id THEN
      RAISE EXCEPTION 'A entrada fiscal vinculada pertence a outro produto.' USING ERRCODE = '23514';
    END IF;
  END IF;

  NEW.ativo := NOT v_excluida AND v_status IN (
    'RASCUNHO', 'ASSINADA', 'ENVIADA', 'AUTORIZADA', 'PENDENTE_ENVIO',
    'CONTINGENCIA', 'RESULTADO_INCERTO'
  );
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_ajustar_eventos_frete_os()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  PERFORM public.ajustar_eventos_frete_os(new.id);
  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.vincular_nfe_saidas(p_nfe_id bigint, p_itens jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item jsonb;
  v_nfe_saida_id bigint;
  v_nfe_modelo text;
  v_nfe_excluida boolean;
BEGIN
  IF p_nfe_id IS NULL OR jsonb_typeof(p_itens) <> 'array' OR jsonb_array_length(p_itens) = 0 THEN
    RAISE EXCEPTION 'Informe a NF-e e ao menos um item de saída.' USING ERRCODE = '22023';
  END IF;

  SELECT saidaid, modelo::text, coalesce(is_deleted, false)
    INTO v_nfe_saida_id, v_nfe_modelo, v_nfe_excluida
    FROM public.nfe
   WHERE id = p_nfe_id
   FOR UPDATE;

  IF NOT FOUND OR v_nfe_modelo <> 'NFE' OR v_nfe_excluida THEN
    RAISE EXCEPTION 'NF-e inválida para vínculo com saídas.' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM jsonb_array_elements(p_itens) item
     WHERE nullif(item->>'saida_id', '')::bigint = v_nfe_saida_id
  ) THEN
    RAISE EXCEPTION 'A saída principal da NF-e precisa estar entre os itens.' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(format('nfe:saida-item:%s', ids.saida_item_id), 0)
  )
  FROM (
    SELECT DISTINCT nullif(item->>'saida_item_id', '')::bigint AS saida_item_id
      FROM jsonb_array_elements(p_itens) item
     ORDER BY 1
  ) ids;

  DELETE FROM public.nfe_saida_item_vinculo WHERE nfe_id = p_nfe_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_itens) LOOP
    INSERT INTO public.nfe_saida_item_vinculo (
      nfe_id, saida_id, saida_item_id, entrada_item_origem_id, quantidade
    ) VALUES (
      p_nfe_id,
      nullif(v_item->>'saida_id', '')::bigint,
      nullif(v_item->>'saida_item_id', '')::bigint,
      nullif(v_item->>'entrada_item_origem_id', '')::bigint,
      nullif(v_item->>'quantidade', '')::numeric
    );
  END LOOP;

  RETURN jsonb_build_object(
    'nfe_id', p_nfe_id,
    'saidas', (SELECT count(DISTINCT saida_id) FROM public.nfe_saida_item_vinculo WHERE nfe_id = p_nfe_id),
    'itens', (SELECT count(*) FROM public.nfe_saida_item_vinculo WHERE nfe_id = p_nfe_id)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_recalc_comissao_criacao_por_item()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM public.recalcular_comissao_criacao_os(old.ordemservicoid);
    RETURN NULL;
  END IF;

  PERFORM public.recalcular_comissao_criacao_os(new.ordemservicoid);

  -- Item movido de OS: a de origem tambem encolheu.
  IF TG_OP = 'UPDATE' AND old.ordemservicoid IS DISTINCT FROM new.ordemservicoid THEN
    PERFORM public.recalcular_comissao_criacao_os(old.ordemservicoid);
  END IF;

  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_recalc_comissao_criacao_os_total()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  PERFORM public.recalcular_comissao_criacao_os(new.id);
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_congelar_comissao_criacao()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF new.execucao_fim_em IS NOT NULL AND old.execucao_fim_em IS NULL THEN
    PERFORM public.recarimbar_comissao_criacao_os(new.id);
    PERFORM public.recalcular_comissao_criacao_os(new.id);
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.recalcular_comissao_criacao_os(p_ordemservicoid integer, p_forcar boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_criador uuid;
  v_pct_servicos numeric := 0;
  v_pct_produtos numeric := 0;
  v_somente boolean := false;
  v_execucao_encerrada boolean := false;
  v_total_os_sem_frete numeric := 0;
  v_total_itens numeric := 0;
  v_fator numeric := 1;
  v_existe boolean;
BEGIN
  SELECT o.usuariocriadorid, o.execucao_fim_em IS NOT NULL
    INTO v_criador, v_execucao_encerrada
    FROM public.ordemservico o
   WHERE o.id = p_ordemservicoid;

  IF v_criador IS NULL THEN
    DELETE FROM public.os_comissao_criacao WHERE ordemservicoid = p_ordemservicoid;
    RETURN;
  END IF;

  SELECT EXISTS (SELECT 1 FROM public.os_comissao_criacao WHERE ordemservicoid = p_ordemservicoid)
    INTO v_existe;

  -- Execucao encerrada e nunca apurada: fica assim, a menos que alguem tenha
  -- pedido nomeando a OS. Ver 20260904140000.
  IF NOT v_existe AND v_execucao_encerrada AND NOT p_forcar THEN
    RETURN;
  END IF;

  IF p_forcar THEN
    v_execucao_encerrada := false;
  END IF;

  -- Execucao encerrada: os percentuais viraram historico e saem das proprias
  -- linhas. Ainda em execucao: releem o cadastro.
  IF v_existe AND v_execucao_encerrada THEN
    SELECT max(CASE WHEN c.tipo = 'SERVICO' THEN c.pct END),
           max(CASE WHEN c.tipo <> 'SERVICO' THEN c.pct END)
      INTO v_pct_servicos, v_pct_produtos
      FROM public.os_comissao_criacao c
     WHERE c.ordemservicoid = p_ordemservicoid;
    -- A flag nao viaja nas linhas: o que ela decidiu ja esta expresso em quais
    -- servicos existem como linha. Reler o cadastro aqui reabriria a base.
    SELECT coalesce(u.comissao_criacao_somente_comissionaveis, false) INTO v_somente
      FROM public.usuario u WHERE u.id = v_criador;
  ELSE
    SELECT coalesce(u.comissao_criacao_servico_percent, 0),
           coalesce(u.comissao_criacao_produto_percent, 0),
           coalesce(u.comissao_criacao_somente_comissionaveis, false)
      INTO v_pct_servicos, v_pct_produtos, v_somente
      FROM public.usuario u
     WHERE u.id = v_criador;
  END IF;

  v_pct_servicos := coalesce(v_pct_servicos, 0);
  v_pct_produtos := coalesce(v_pct_produtos, 0);

  IF v_pct_servicos = 0 AND v_pct_produtos = 0 THEN
    DELETE FROM public.os_comissao_criacao WHERE ordemservicoid = p_ordemservicoid;
    RETURN;
  END IF;

  -- Expressao identica a de `recalcular_comissao_osservico`. Mudar uma sem a
  -- outra faz as duas comissoes da mesma OS discordarem sobre o desconto.
  SELECT greatest(coalesce(o.orcamentototal, 0) - coalesce(o.valor_frete, 0), 0),
         coalesce((SELECT sum(coalesce(op.subtotal, 0)) FROM public.osproduto op WHERE op.ordemservicoid = o.id), 0)
           + coalesce((SELECT sum(coalesce(opa.subtotal, 0)) FROM public.osproduto_avulso opa WHERE opa.ordemservicoid = o.id), 0)
           + coalesce((SELECT sum(coalesce(os.subtotal, 0)) FROM public.osservico os WHERE os.ordemservicoid = o.id), 0)
    INTO v_total_os_sem_frete, v_total_itens
    FROM public.ordemservico o WHERE o.id = p_ordemservicoid;

  IF v_total_itens > 0 THEN v_fator := v_total_os_sem_frete / v_total_itens; END IF;

  -- Uma linha por item. O DELETE do que sobrou remove item retirado da OS.
  WITH desejadas AS (
    SELECT 'SERVICO'::text AS tipo, os.servicoid AS item_id,
           round(coalesce(os.subtotal, 0) * v_fator, 2) AS base, v_pct_servicos AS pct
      FROM public.osservico os
      JOIN public.servico s ON s.id = os.servicoid
     WHERE os.ordemservicoid = p_ordemservicoid
       AND v_pct_servicos > 0
       AND (NOT v_somente OR coalesce(s.gera_comissao, true))
    UNION ALL
    SELECT 'PRODUTO', op.produtoid,
           round(coalesce(op.subtotal, 0) * v_fator, 2), v_pct_produtos
      FROM public.osproduto op
     WHERE op.ordemservicoid = p_ordemservicoid AND v_pct_produtos > 0
    UNION ALL
    SELECT 'PRODUTO_AVULSO', opa.id,
           round(coalesce(opa.subtotal, 0) * v_fator, 2), v_pct_produtos
      FROM public.osproduto_avulso opa
     WHERE opa.ordemservicoid = p_ordemservicoid AND v_pct_produtos > 0
  ),
  gravadas AS (
    INSERT INTO public.os_comissao_criacao AS c
      (ordemservicoid, tipo, item_id, usuarioid, base, pct, valor_comissao, updated_at)
    SELECT p_ordemservicoid, d.tipo, d.item_id, v_criador, d.base, d.pct,
           round(d.base * d.pct / 100.0, 2), now()
      FROM desejadas d
    ON CONFLICT (ordemservicoid, tipo, item_id) DO UPDATE SET
      -- `usuarioid` de proposito NAO entra: o criador e carimbado na primeira
      -- apuracao e nao acompanha troca de titularidade.
      base = excluded.base,
      pct = excluded.pct,
      valor_comissao = excluded.valor_comissao,
      updated_at = now()
    RETURNING c.tipo, c.item_id
  )
  DELETE FROM public.os_comissao_criacao c
   WHERE c.ordemservicoid = p_ordemservicoid
     AND NOT EXISTS (
       SELECT 1 FROM gravadas g WHERE g.tipo = c.tipo AND g.item_id = c.item_id
     );
END;
$function$

