CREATE OR REPLACE FUNCTION public.fn_disparar_processamento_notificacao_os()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_endpoint_url text;
  v_bearer_token text;
BEGIN
  SELECT endpoint_url, bearer_token
    INTO v_endpoint_url, v_bearer_token
    FROM public.telegram_dispatch_configuracao
   WHERE id = 1 AND ativo = true;

  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  BEGIN
    PERFORM net.http_post(
      url := v_endpoint_url,
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || v_bearer_token
      ),
      body := jsonb_build_object('evento_id', NEW.id),
      timeout_milliseconds := 5000
    );
  EXCEPTION WHEN OTHERS THEN
    -- A OS e o evento permanecem salvos; o processador recorrente pode recuperar a fila.
    RAISE WARNING 'Falha ao agendar processamento Telegram para evento %: %', NEW.id, SQLERRM;
  END;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.cancelar_entrada_confirmada_interna(p_entrada_id bigint, p_motivo text, p_cancelada_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_entrada public.entrada%ROWTYPE;
  v_item record;
  v_estoque integer;
  v_ultimo_custo numeric;
  v_transacao public.transacao%ROWTYPE;
  v_tipo_estorno public.tipos_transacao;
  v_motivo text := nullif(btrim(p_motivo), '');
BEGIN
  IF v_motivo IS NULL THEN
    RAISE EXCEPTION 'Informe o motivo do cancelamento.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_entrada FROM public.entrada WHERE id = p_entrada_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Entrada não encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF v_entrada.status = 'CANCELADA'::public.enum_status_entrada THEN
    RAISE EXCEPTION 'Esta entrada já está cancelada.' USING ERRCODE = '22023';
  END IF;

  -- Pagamento compartilhado com uma entrada de uso e consumo ainda ativa: a NF-e
  -- mista so pode ser cancelada como um todo, via cancelar_entrada_fiscal_mista.
  IF coalesce(current_setting('app.entrada_mista_cancelamento', true), '') <> 'permitido'
     AND EXISTS(
       SELECT 1 FROM public.transacao t
       JOIN public.usoconsumo_entrada ue ON ue.id = t.usoconsumo_entrada_id
       WHERE t.entrada_id = p_entrada_id
         AND NOT t.is_deleted
         AND t.estorno_transacao_id IS NULL
         AND ue.cancelada_at IS NULL
     ) THEN
    RAISE EXCEPTION 'Esta entrada divide o pagamento da NF-e com uma entrada de uso e consumo ainda ativa. Cancele a nota inteira.'
      USING ERRCODE = '23514';
  END IF;

  FOR v_item IN
    SELECT * FROM public.entradaitens WHERE entrada_id = p_entrada_id ORDER BY id FOR UPDATE
  LOOP
    SELECT estoque INTO v_estoque FROM public.produto WHERE id = v_item.produto_id FOR UPDATE;
    IF coalesce(v_estoque, 0) < v_item.quantidade THEN
      RAISE EXCEPTION 'Não há saldo suficiente do produto % para cancelar a entrada.', v_item.produto_id
        USING ERRCODE = '22023';
    END IF;

    UPDATE public.produto
    SET estoque = estoque - v_item.quantidade::integer, updatedat = now()
    WHERE id = v_item.produto_id;

    INSERT INTO public.estoque_movimento_entrada (
      entrada_id, entrada_item_id, produto_id, tipo, quantidade,
      saldo_anterior, saldo_resultante, valor_unitario_compra
    ) VALUES (
      p_entrada_id, v_item.id, v_item.produto_id, 'CANCELAMENTO', v_item.quantidade::integer,
      v_estoque, v_estoque - v_item.quantidade::integer, v_item.valor_unitario_compra
    );

    SELECT ei.valor_unitario_compra INTO v_ultimo_custo
    FROM public.entradaitens ei
    JOIN public.entrada e ON e.id = ei.entrada_id
    WHERE ei.produto_id = v_item.produto_id
      AND e.id <> p_entrada_id
      AND e.status = 'CONFIRMADA'::public.enum_status_entrada
    ORDER BY e.created_at DESC, e.id DESC, ei.id DESC LIMIT 1;

    UPDATE public.produto
    SET ultimovalordecompra = v_ultimo_custo
    WHERE id = v_item.produto_id;
  END LOOP;

  FOR v_transacao IN
    SELECT * FROM public.transacao
    WHERE entrada_id = p_entrada_id AND NOT is_deleted AND estorno_transacao_id IS NULL
    FOR UPDATE
  LOOP
    IF v_transacao.pendente THEN
      UPDATE public.transacao
      SET pendente = false, is_deleted = true, deleted_at = now(), updated_at = now()
      WHERE id = v_transacao.id;
    ELSE
      v_tipo_estorno := CASE v_transacao.tipo
        WHEN 'DESPESA'::public.tipos_transacao THEN 'RECEITA'::public.tipos_transacao
        WHEN 'RECEITA'::public.tipos_transacao THEN 'DESPESA'::public.tipos_transacao
        WHEN 'DEPOSITO'::public.tipos_transacao THEN 'SAQUE'::public.tipos_transacao
        ELSE 'DEPOSITO'::public.tipos_transacao
      END;
      INSERT INTO public.transacao (
        descricao, valor, "valorLiquido", data, metodopagamento, categoria, categoria_id,
        tipo, cliente_id, banco_id, nomepagador, cpfcnpjpagador, pendente,
        plano_de_conta_id, plano_de_conta, centro_custo_id, centro_custo,
        entrada_id, estorno_transacao_id
      ) VALUES (
        'Estorno: ' || v_transacao.descricao, v_transacao.valor, v_transacao."valorLiquido", now(),
        v_transacao.metodopagamento, v_transacao.categoria, v_transacao.categoria_id,
        v_tipo_estorno, v_transacao.cliente_id, v_transacao.banco_id,
        v_transacao.nomepagador, v_transacao.cpfcnpjpagador, false,
        v_transacao.plano_de_conta_id, v_transacao.plano_de_conta,
        v_transacao.centro_custo_id, v_transacao.centro_custo,
        p_entrada_id, v_transacao.id
      );
    END IF;
  END LOOP;

  UPDATE public.entrada
  SET status = 'CANCELADA'::public.enum_status_entrada,
      cancelada_at = now(),
      cancelada_by = p_cancelada_by,
      motivo_cancelamento = v_motivo
  WHERE id = p_entrada_id;

  RETURN jsonb_build_object('entrada_id', p_entrada_id, 'status', 'CANCELADA');
END;
$function$

CREATE OR REPLACE FUNCTION public.reconciliar_comissao_venda(p_vendaid bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_venda public.venda%ROWTYPE;
  v_snapshot public.venda_comissao%ROWTYPE;
  v_usuario uuid;
  v_pct numeric;
  v_base numeric;
  v_valor numeric;
  v_frete_itens numeric;
  v_reconhecida boolean;
  v_nome text;
BEGIN
  SELECT * INTO v_venda FROM public.venda WHERE id=p_vendaid FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  SELECT * INTO v_snapshot FROM public.venda_comissao WHERE vendaid=p_vendaid;
  IF FOUND AND NOT v_snapshot.integrada THEN RETURN; END IF;

  v_reconhecida := public.venda_reconhece_receita(v_venda.status::text);
  v_usuario := coalesce(v_venda.vendedor,v_venda.created_by);
  IF v_reconhecida AND v_snapshot.congelada_em IS NOT NULL THEN
    IF v_usuario IS DISTINCT FROM v_snapshot.usuarioid THEN
      RAISE EXCEPTION 'Reabra a venda antes de trocar o vendedor de uma comissão já apurada.' USING ERRCODE='P0001';
    END IF;
    v_pct := v_snapshot.percentual;
  ELSE
    SELECT coalesce(comissao_venda_percent,0) INTO v_pct FROM public.usuario WHERE id=v_usuario;
  END IF;
  v_pct := coalesce(v_pct,0);
  SELECT coalesce(sum(valor_frete),0) INTO v_frete_itens FROM public.vendaproduto WHERE venda_id=p_vendaid;
  v_base := round(greatest(coalesce(v_venda.valortotal,0)-coalesce(v_venda.valor_frete,0)-v_frete_itens,0),2);
  v_valor := round(v_base*v_pct/100,2);

  -- Uma comissão comprometida não pode ser cancelada, transferida ou alterada
  -- silenciosamente. A operação inteira (inclusive itens/estoque) é desfeita.
  PERFORM 1 FROM public.eventos_financeiros
   WHERE source_type='VENDA' AND source_id=p_vendaid AND origem='COMISSAO' FOR UPDATE;
  IF EXISTS (
    SELECT 1 FROM public.eventos_financeiros e
     WHERE e.source_type='VENDA' AND e.source_id=p_vendaid AND e.origem='COMISSAO'
       AND (e.status='CONVERTIDO' OR e.transacaoid IS NOT NULL OR e.lancamento_id IS NOT NULL)
       AND (NOT v_reconhecida OR e.valor IS DISTINCT FROM v_valor
            OR e.usuarioid IS DISTINCT FROM v_usuario)
  ) THEN
    RAISE EXCEPTION 'Desfaça o lançamento financeiro da comissão antes de alterar ou cancelar esta venda.' USING ERRCODE='P0001';
  END IF;

  INSERT INTO public.venda_comissao(vendaid,usuarioid,base,percentual,valor_comissao,congelada_em)
  VALUES(p_vendaid,v_usuario,v_base,v_pct,v_valor,
    CASE WHEN v_reconhecida THEN coalesce(v_snapshot.congelada_em,v_venda.pagamento_em,now()) END)
  ON CONFLICT(vendaid) DO UPDATE SET
    usuarioid=excluded.usuarioid,base=excluded.base,percentual=excluded.percentual,
    valor_comissao=excluded.valor_comissao,congelada_em=excluded.congelada_em,updated_at=now();

  IF NOT v_reconhecida THEN
    UPDATE public.eventos_financeiros SET status='CANCELADO',updated_at=now()
     WHERE source_type='VENDA' AND source_id=p_vendaid AND origem='COMISSAO' AND status='ATIVO' AND NOT is_manual;
    RETURN;
  END IF;
  SELECT coalesce(nullif(nome,''),'Vendedor') INTO v_nome FROM public.usuario WHERE id=v_usuario;
  INSERT INTO public.eventos_financeiros
    (source_type,source_id,origem,natureza,natureza_dre,chave_origem,descricao,detalhe,
     valor,usuarioid,valor_base_snapshot,percentual_snapshot,competencia_em,dados_snapshot,pode_gerar_transacao)
  VALUES ('VENDA',p_vendaid,'COMISSAO','DESPESA',public.natureza_dre_de_evento('COMISSAO','DESPESA'),
    'COMISSAO_VENDA','Comissão da venda #'||p_vendaid||' - '||coalesce(v_nome,'Sem vendedor'),
    'Base líquida sem frete: R$ '||v_base||' × '||v_pct||'%',v_valor,v_usuario,v_base,v_pct,
    coalesce(v_venda.datavenda,v_venda.createdat,now()),
    jsonb_build_object('vendaid',p_vendaid,'usuarioid',v_usuario,'base',v_base,'percentual',v_pct,'valor_comissao',v_valor),
    v_valor>0 AND v_usuario IS NOT NULL)
  ON CONFLICT(source_type,source_id,origem,chave_origem,natureza) WHERE ordemservicoid IS NULL
  DO UPDATE SET valor=excluded.valor,usuarioid=excluded.usuarioid,descricao=excluded.descricao,
    detalhe=excluded.detalhe,valor_base_snapshot=excluded.valor_base_snapshot,
    percentual_snapshot=excluded.percentual_snapshot,competencia_em=excluded.competencia_em,
    dados_snapshot=excluded.dados_snapshot,pode_gerar_transacao=excluded.pode_gerar_transacao,
    status='ATIVO',updated_at=now()
  WHERE eventos_financeiros.status<>'CONVERTIDO' AND NOT eventos_financeiros.is_manual;
END;
$function$

