CREATE OR REPLACE FUNCTION public.vincular_produto_avulso_os_interna(p_ordem_id integer, p_avulso_id bigint, p_produto_id integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item public.osproduto_avulso%ROWTYPE;
  v_estoque numeric;
  v_modo text := 'ORCAMENTO';
BEGIN
  SELECT * INTO v_item
  FROM public.osproduto_avulso
  WHERE id = p_avulso_id AND ordemservicoid = p_ordem_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Produto avulso não encontrado.' USING ERRCODE = 'P0002';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.osproduto
    WHERE ordemservicoid = p_ordem_id AND produtoid = p_produto_id
  ) THEN
    RAISE EXCEPTION 'O produto selecionado já está neste orçamento.' USING ERRCODE = '23505';
  END IF;

  SELECT estoque INTO v_estoque
  FROM public.produto
  WHERE id = p_produto_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Produto não encontrado.' USING ERRCODE = 'P0002';
  END IF;

  SELECT COALESCE(modo_baixa_estoque_os::text, 'ORCAMENTO') INTO v_modo
  FROM public.config_geral ORDER BY id DESC LIMIT 1;

  IF v_modo = 'ORCAMENTO' AND v_estoque < v_item.quantidade THEN
    RAISE EXCEPTION 'Estoque insuficiente. Disponível: %, solicitado: %.', v_estoque, v_item.quantidade
      USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO public.osproduto (
    ordemservicoid, produtoid, quantidade, precounitario, subtotal,
    desconto_tipo, desconto
  ) VALUES (
    p_ordem_id, p_produto_id, v_item.quantidade, v_item.precounitario,
    v_item.subtotal, v_item.desconto_tipo, v_item.desconto
  );

  IF v_modo = 'ORCAMENTO' THEN
    UPDATE public.produto
    SET estoque = estoque - v_item.quantidade
    WHERE id = p_produto_id;

    INSERT INTO public.osproduto_baixa (ordemservicoid, produtoid, quantidade)
    VALUES (p_ordem_id, p_produto_id, v_item.quantidade)
    ON CONFLICT (ordemservicoid, produtoid)
    DO UPDATE SET quantidade = EXCLUDED.quantidade;
  END IF;

  DELETE FROM public.osproduto_avulso WHERE id = v_item.id;
END;
$function$

CREATE OR REPLACE FUNCTION public.avancar_venda_aprovada_pagamento(p_venda_id integer, p_usuario_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_venda public.venda%ROWTYPE;
BEGIN
  SELECT * INTO v_venda
    FROM public.venda
   WHERE id = p_venda_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Venda não encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF v_venda.status::text IN ('PAGAMENTO', 'PAGO', 'FINALIZADA') THEN
    RETURN jsonb_build_object(
      'vendaId', p_venda_id,
      'status', v_venda.status::text,
      'statusaprovacao', v_venda.statusaprovacao::text
    );
  END IF;
  IF v_venda.status::text <> 'ORCAMENTO_APROVADO' THEN
    RAISE EXCEPTION 'Apenas um orçamento aprovado pode avançar para pagamento.'
      USING ERRCODE = '22023';
  END IF;

  PERFORM public.fn_baixar_estoque_venda(p_venda_id);

  UPDATE public.venda
     SET status = 'PAGAMENTO',
         statusaprovacao = 'APROVADA',
         updated_by = coalesce(p_usuario_id, updated_by),
         updatedat = now()
   WHERE id = p_venda_id;

  RETURN jsonb_build_object(
    'vendaId', p_venda_id,
    'status', 'PAGAMENTO',
    'statusaprovacao', 'APROVADA'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_criar_venda_marketplace_com_itens(p_venda jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_cliente_id integer := COALESCE((p_venda->>'clienteId')::integer, (p_venda->>'clienteid')::integer);
  v_status public.enum_status_venda := COALESCE(NULLIF(p_venda->>'status', '')::public.enum_status_venda, 'ABERTA'::public.enum_status_venda);
  v_canal public.enum_canal_venda := COALESCE(NULLIF(p_venda->>'canal', '')::public.enum_canal_venda, 'MERCADO_LIVRE'::public.enum_canal_venda);
  v_status_entrega public.enum_status_entrega := NULLIF(p_venda->>'statusEntrega', '')::public.enum_status_entrega;
  v_desconto_tipo public.enum_tipo_desconto_venda := NULLIF(COALESCE(p_venda->>'descontoTipo', p_venda->>'desconto_tipo'), '')::public.enum_tipo_desconto_venda;
  v_desconto_valor numeric := NULLIF(COALESCE(p_venda->>'descontoValor', p_venda->>'desconto_valor'), '')::numeric;
  v_sub_total numeric := COALESCE(NULLIF(COALESCE(p_venda->>'subTotal', p_venda->>'sub_total'), '')::numeric, 0);
  v_valor_total numeric := COALESCE(NULLIF(COALESCE(p_venda->>'valorTotal', p_venda->>'valortotal'), '')::numeric, 0);
  v_data_venda timestamptz := COALESCE(NULLIF(p_venda->>'dataVenda', '')::timestamptz, now());
  v_forma_pagamento text := NULLIF(COALESCE(p_venda->>'formaPagamento', p_venda->>'forma_pagamento'), '');
  v_observacoes text := NULLIF(p_venda->>'observacoes', '');
  v_itens jsonb := p_venda->'itens';
  v_item jsonb;
  v_produto_id integer;
  v_quantidade integer;
  v_sub_total_item numeric;
  v_valor_total_item numeric;
  v_baixar_estoque boolean;
  v_venda_id integer;
BEGIN
  IF v_cliente_id IS NULL OR v_sub_total <= 0 OR v_valor_total <= 0 THEN
    RAISE EXCEPTION 'Campos obrigatórios ausentes em p_venda (clienteId, subTotal, valorTotal).';
  END IF;

  IF v_itens IS NULL OR jsonb_typeof(v_itens) <> 'array' OR jsonb_array_length(v_itens) = 0 THEN
    RAISE EXCEPTION 'p_venda.itens deve ser um array não vazio.';
  END IF;

  INSERT INTO public.venda (
    clienteid,
    status,
    canal,
    status_entrega,
    valortotal,
    sub_total,
    desconto_tipo,
    desconto_valor,
    forma_pagamento,
    datavenda,
    createdat,
    updatedat,
    observacoes
  )
  VALUES (
    v_cliente_id,
    v_status,
    v_canal,
    v_status_entrega,
    v_valor_total,
    v_sub_total,
    v_desconto_tipo,
    v_desconto_valor,
    v_forma_pagamento,
    v_data_venda,
    now(),
    now(),
    v_observacoes
  )
  RETURNING id INTO v_venda_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(v_itens)
  LOOP
    v_produto_id := COALESCE((v_item->>'produtoId')::integer, (v_item->>'produtoid')::integer);
    v_quantidade := COALESCE((v_item->>'quantidade')::integer, 1);
    v_sub_total_item := COALESCE(NULLIF(COALESCE(v_item->>'subTotal', v_item->>'sub_total'), '')::numeric, 0);
    v_valor_total_item := COALESCE(NULLIF(COALESCE(v_item->>'valorTotal', v_item->>'valor_total'), '')::numeric, v_sub_total_item);
    v_baixar_estoque := COALESCE((v_item->>'baixarEstoque')::boolean, true);

    IF v_produto_id IS NULL OR v_quantidade <= 0 THEN
      RAISE EXCEPTION 'Cada item deve possuir produtoId e quantidade > 0.';
    END IF;

    IF v_baixar_estoque THEN
      PERFORM public.fn_baixa_estoque_produto(v_produto_id, v_quantidade);

      INSERT INTO public.vendaproduto_baixa (venda_id, produtoid, quantidade, created_at, updated_at)
      VALUES (v_venda_id, v_produto_id, v_quantidade, now(), now())
      ON CONFLICT (venda_id, produtoid) DO UPDATE
      SET quantidade = EXCLUDED.quantidade,
          updated_at = now();
    END IF;

    INSERT INTO public.vendaproduto (
      venda_id,
      produtoid,
      quantidade,
      sub_total,
      valor_total,
      valor_desconto,
      tipo_desconto
    )
    VALUES (
      v_venda_id,
      v_produto_id,
      v_quantidade,
      v_sub_total_item,
      v_valor_total_item,
      NULL,
      NULL
    );
  END LOOP;

  RETURN v_venda_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_sincronizar_baixa_estoque_marketplace_interna(p_venda_id integer, p_produto_id integer, p_quantidade_alvo integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_estoque integer;
  v_quantidade_atual integer := 0;
  v_delta integer;
BEGIN
  IF p_venda_id IS NULL OR p_venda_id <= 0 OR p_produto_id IS NULL OR p_produto_id <= 0 THEN
    RAISE EXCEPTION 'Venda e produto são obrigatórios.';
  END IF;
  IF p_quantidade_alvo IS NULL OR p_quantidade_alvo < 0 THEN
    RAISE EXCEPTION 'Quantidade alvo inválida.';
  END IF;

  SELECT estoque
    INTO v_estoque
    FROM public.produto
   WHERE id = p_produto_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Produto % não encontrado.', p_produto_id;
  END IF;

  SELECT quantidade
    INTO v_quantidade_atual
    FROM public.vendaproduto_baixa
   WHERE venda_id = p_venda_id
     AND produtoid = p_produto_id
   FOR UPDATE;

  v_quantidade_atual := COALESCE(v_quantidade_atual, 0);
  v_delta := p_quantidade_alvo - v_quantidade_atual;

  IF v_delta > 0 THEN
    IF v_estoque < v_delta THEN
      RAISE EXCEPTION 'Estoque insuficiente para produto %, em estoque: %, necessário: %',
        p_produto_id, v_estoque, v_delta;
    END IF;

    UPDATE public.produto
       SET estoque = estoque - v_delta,
           updatedat = now()
     WHERE id = p_produto_id;
  ELSIF v_delta < 0 THEN
    UPDATE public.produto
       SET estoque = estoque + abs(v_delta),
           updatedat = now()
     WHERE id = p_produto_id;
  END IF;

  IF p_quantidade_alvo = 0 THEN
    DELETE FROM public.vendaproduto_baixa
     WHERE venda_id = p_venda_id
       AND produtoid = p_produto_id;
  ELSE
    INSERT INTO public.vendaproduto_baixa (venda_id, produtoid, quantidade, created_at, updated_at)
    VALUES (p_venda_id, p_produto_id, p_quantidade_alvo, now(), now())
    ON CONFLICT (venda_id, produtoid) DO UPDATE
      SET quantidade = EXCLUDED.quantidade,
          updated_at = now();
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.separar_conclusao_financeira_da_saida_os()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.status::text = 'CONCLUIDO'
     and old.status::text is distinct from 'CONCLUIDO' then
    new.pagamento_concluido_em := coalesce(new.pagamento_concluido_em, new.datasaida, now());
  end if;
  if old.status::text = 'CONCLUIDO' and new.status::text = 'PAGAMENTO' then
    new.pagamento_concluido_em := null;
  end if;

  if new.datasaida is distinct from old.datasaida
     and not exists (
       select 1 from public.os_saida s where s.ordemservico_id = old.id
     ) then
    new.datasaida := old.datasaida;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.propagar_nome_categoria_transacao()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.nome IS DISTINCT FROM OLD.nome THEN
    UPDATE public.transacao
    SET categoria = NEW.nome
    WHERE categoria_id = NEW.id;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_gerar_eventos_financeiros_os()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status = 'ORCAMENTO_APROVADO' and old.status is distinct from new.status then
    perform public.sincronizar_eventos_financeiros_os(new.id, false);
  elsif new.status = 'EM_ANDAMENTO' and old.status is distinct from new.status then
    if exists (
      select 1 from public.osservico s
      where s.ordemservicoid = new.id
        and not exists (select 1 from public.osservico_realizador r
                        where r.ordemservicoid = s.ordemservicoid and r.servicoid = s.servicoid)
    ) then
      raise exception 'Defina os realizadores de todos os servicos antes de iniciar a OS.';
    end if;
    perform public.sincronizar_eventos_financeiros_os(new.id, true);
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.proteger_tipo_entrada_sistema()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.sistema THEN
      RAISE EXCEPTION 'O tipo de entrada "%" e do sistema e nao pode ser removido.', OLD.nome
        USING ERRCODE = '22023';
    END IF;
    RETURN OLD;
  END IF;

  IF NOT OLD.sistema THEN
    RETURN NEW;
  END IF;

  -- Nome e descricao continuam editaveis: sao rotulo, nao regra.
  IF NEW.codigo IS DISTINCT FROM OLD.codigo
     OR NEW.escopo IS DISTINCT FROM OLD.escopo
     OR NEW.exige_valor IS DISTINCT FROM OLD.exige_valor
     OR NEW.ativo IS DISTINCT FROM OLD.ativo
     OR NEW.sistema IS DISTINCT FROM OLD.sistema THEN
    RAISE EXCEPTION 'O tipo de entrada "%" e do sistema: as regras dele nao podem ser alteradas.', OLD.nome
      USING ERRCODE = '22023';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.proteger_categoria_transacao_sistema()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.codigo_sistema IS NOT NULL THEN
    IF TG_OP = 'DELETE' THEN
      RAISE EXCEPTION 'Categorias de sistema não podem ser excluídas.';
    END IF;

    IF NEW.codigo_sistema IS DISTINCT FROM OLD.codigo_sistema THEN
      RAISE EXCEPTION 'O código de uma categoria de sistema não pode ser alterado.';
    END IF;

    IF NEW.ativo IS NOT TRUE THEN
      RAISE EXCEPTION 'Categorias de sistema não podem ser desativadas.';
    END IF;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.converter_evento_financeiro_em_transacao(p_eventoid bigint, p_usuarioid uuid DEFAULT NULL::uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_evento public.eventos_financeiros%rowtype;
  v_transacaoid bigint;
BEGIN
  SELECT * INTO v_evento FROM public.eventos_financeiros WHERE id = p_eventoid FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Evento financeiro nao encontrado.'; END IF;
  IF NOT v_evento.pode_gerar_transacao THEN
    RAISE EXCEPTION 'Este evento nao pode gerar uma transacao.';
  END IF;
  IF v_evento.status <> 'ATIVO' OR v_evento.transacaoid IS NOT NULL THEN
    RAISE EXCEPTION 'Este evento ja foi convertido ou cancelado.';
  END IF;

  INSERT INTO public.transacao
    (descricao, valor, "valorLiquido", data, tipo, ordemservicoid, pendente,
     categoria, nomepagador, cpfcnpjpagador, created_by, evento_financeiro_id)
  VALUES
    (v_evento.descricao, v_evento.valor, v_evento.valor, now(),
     v_evento.natureza::public.tipos_transacao, v_evento.ordemservicoid, true,
     'NAO RELACIONADO', 'Evento financeiro OS #' || v_evento.ordemservicoid, '',
     p_usuarioid, v_evento.id)
  RETURNING id INTO v_transacaoid;

  UPDATE public.eventos_financeiros
     SET status = 'CONVERTIDO', transacaoid = v_transacaoid, updated_at = now()
   WHERE id = v_evento.id;
  RETURN v_transacaoid;
END;
$function$

