CREATE OR REPLACE FUNCTION public.atualizar_permissoes_perfil_auditado(p_perfilid integer, p_permissoes_ids integer[], p_usuario_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_usuario_id is not null and not exists (select 1 from public.usuario where id = p_usuario_id) then
    raise exception 'Usuario responsavel invalido';
  end if;

  if p_usuario_id is not null then
    perform set_config('app.audit_user_id', p_usuario_id::text, true);
  end if;

  delete from public.perfilpermissao pp
  where pp.perfilid = p_perfilid
    and not (pp.permissaoid = any(coalesce(p_permissoes_ids, '{}'::integer[])));

  insert into public.perfilpermissao (perfilid, permissaoid, created_by, updated_by)
  select p_perfilid, permissaoid, p_usuario_id, p_usuario_id
  from unnest(coalesce(p_permissoes_ids, '{}'::integer[])) as permissaoid
  on conflict (perfilid, permissaoid) do nothing;
end;
$function$

CREATE OR REPLACE FUNCTION public.auditoria_usuario_requisicao()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  claims_raw text := nullif(current_setting('request.jwt.claims', true), '');
  headers_raw text := nullif(current_setting('request.headers', true), '');
  role_requisicao text;
begin
  if claims_raw is null or headers_raw is null then
    return null;
  end if;

  role_requisicao := claims_raw::jsonb ->> 'role';
  if role_requisicao <> 'service_role' then
    return null;
  end if;

  return public.auditoria_try_uuid(headers_raw::jsonb ->> 'x-audit-user-id');
exception when others then
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.tg_set_comissao_percent_aplicada()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.comissao_percent_aplicada is null then
    if exists (
      select 1 from public.servico s
      where s.id = new.servicoid and s.gera_comissao is false
    ) then
      new.comissao_percent_aplicada := 0;
    else
      select coalesce(u.comissao_percent, 0)
        into new.comissao_percent_aplicada
      from public.usuario u
      where u.id = new.usuarioid;
    end if;
  end if;

  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_baixar_estoque_venda_interna(p_venda_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
  q_baixada int;
  delta int;
begin
  -- trava a venda para evitar concorrência
  perform 1 from public.venda where id = p_venda_id for update;

  for r in
    select vp.produtoid, vp.quantidade
      from public.vendaproduto vp
     where vp.venda_id = p_venda_id
  loop
    select b.quantidade into q_baixada
      from public.vendaproduto_baixa b
     where b.venda_id = p_venda_id
       and b.produtoid = r.produtoid;

    if q_baixada is null then
      delta := r.quantidade;
    else
      delta := r.quantidade - q_baixada;
    end if;

    if delta > 0 then
      update public.produto
         set estoque = estoque - delta,
             updatedat = now()
       where id = r.produtoid
         and estoque >= delta;

      if not found then
        raise exception 'Estoque insuficiente para o produto % (necessário: %, venda %)',
          r.produtoid, delta, p_venda_id
          using errcode = 'P0001';
      end if;

    elsif delta < 0 then
      update public.produto
         set estoque = estoque + (-delta),
             updatedat = now()
       where id = r.produtoid;
    end if;

    insert into public.vendaproduto_baixa (venda_id, produtoid, quantidade, updated_at)
    values (p_venda_id, r.produtoid, r.quantidade, now())
    on conflict (venda_id, produtoid) do update
      set quantidade = excluded.quantidade,
          updated_at = now();
  end loop;

  return jsonb_build_object('ok', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.tg_recalc_comissao_os_total()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF new.orcamentototal IS DISTINCT FROM old.orcamentototal
     OR new.valor_frete IS DISTINCT FROM old.valor_frete THEN
