END;
$function$

CREATE OR REPLACE FUNCTION public.registrar_entrada_usoconsumo_sem_dre(p_entrada jsonb, p_itens jsonb, p_transacoes jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_entrada_id bigint; v_item_json jsonb; v_item public.usoconsumo_item%ROWTYPE;
  v_entrada_item_id bigint; v_item_id integer; v_qtd integer; v_custo numeric(14,4);
  v_desc numeric(14,2); v_frete numeric(14,2); v_outras numeric(14,2); v_total_item numeric(14,2);
  v_total numeric(14,2):=0; v_total_fin numeric(14,2); v_tx jsonb; v_fiscal boolean;
  v_chave text; v_documento_id bigint; v_numero_item integer; v_user uuid;
  v_total_documento numeric(14,2) := nullif(p_entrada->>'valor_total_documento','')::numeric;
  v_total_devido numeric(14,2);
  v_escopo text := upper(btrim(coalesce(p_entrada->>'escopo','USOCONSUMO')));
  v_rotulo text;
BEGIN
  IF jsonb_typeof(p_itens)<>'array' OR jsonb_array_length(p_itens)=0 THEN
    RAISE EXCEPTION 'Informe ao menos um item.' USING ERRCODE='22023';
  END IF;
  IF v_escopo NOT IN ('USOCONSUMO','GERAL','MISTO') THEN
    RAISE EXCEPTION 'Escopo de estoque invalido: %.', v_escopo USING ERRCODE='22023';
  END IF;
  v_rotulo := CASE v_escopo
                WHEN 'GERAL' THEN 'Compra de material do estoque geral'
                WHEN 'MISTO' THEN 'Compra de material de uso e consumo e do estoque geral'
                ELSE 'Compra de material de uso e consumo' END;
  IF v_total_documento IS NOT NULL AND v_total_documento < 0 THEN
    RAISE EXCEPTION 'O total do documento fiscal nao pode ser negativo.' USING ERRCODE='22023';
  END IF;
  v_fiscal:=coalesce((p_entrada->>'fiscal')::boolean,false);
  v_chave:=nullif(regexp_replace(coalesce(p_entrada->>'chave_nfe',''),'\D','','g'),'');
  v_documento_id:=nullif(p_entrada->>'documento_fiscal_recebido_id','')::bigint;
  v_user:=nullif(p_entrada->>'created_by','')::uuid;
  IF v_fiscal AND (v_chave IS NULL OR length(v_chave)<>44 OR nullif(p_entrada->>'fornecedor_id','') IS NULL) THEN
    RAISE EXCEPTION 'A entrada fiscal exige chave valida e fornecedor.' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.usoconsumo_entrada(
    escopo,fornecedor_id,fiscal,chave_nfe,numero_nota,serie_nota,data_emissao,tipo,origem,documento_fiscal_recebido_id,created_by,observacao
  ) VALUES(
    v_escopo,
    nullif(p_entrada->>'fornecedor_id','')::integer,v_fiscal,v_chave,nullif(p_entrada->>'numero_nota',''),
    nullif(p_entrada->>'serie_nota',''),nullif(p_entrada->>'data_emissao','')::timestamptz,
    coalesce(nullif(p_entrada->>'tipo',''),'COMPRA_FORNECEDOR'),coalesce(nullif(p_entrada->>'origem',''),'MANUAL'),
    v_documento_id,v_user,nullif(btrim(coalesce(p_entrada->>'observacao','')),'')
  ) RETURNING id INTO v_entrada_id;

  FOR v_item_json IN SELECT value FROM jsonb_array_elements(p_itens) LOOP
    v_item_id:=nullif(v_item_json->>'item_id','')::integer;
    v_qtd:=nullif(v_item_json->>'quantidade','')::integer;
    v_custo:=nullif(v_item_json->>'valor_unitario_compra','')::numeric;
    v_desc:=coalesce(nullif(v_item_json->>'valor_desconto','')::numeric,0);
    v_frete:=coalesce(nullif(v_item_json->>'valor_frete','')::numeric,0);
    v_outras:=coalesce(nullif(v_item_json->>'outras_despesas','')::numeric,0);
    v_numero_item:=nullif(v_item_json->>'numero_item_fiscal','')::integer;
    IF v_item_id IS NULL OR v_qtd IS NULL OR v_qtd<=0 OR v_custo IS NULL OR v_custo<0
       OR v_desc<0 OR v_frete<0 OR v_outras<0 THEN
      RAISE EXCEPTION 'Item, quantidade ou valores invalidos.' USING ERRCODE='22023';
    END IF;
    IF v_fiscal AND v_documento_id IS NOT NULL AND v_numero_item IS NULL THEN
      RAISE EXCEPTION 'Informe o numero do item fiscal.' USING ERRCODE='22023';
    END IF;
    -- MISTO aceita item de qualquer estoque simples; escopo unico exige o proprio.
    SELECT * INTO v_item FROM public.usoconsumo_item
    WHERE id=v_item_id AND ativo
      AND (v_escopo='MISTO' OR escopo=v_escopo)
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Item % nao encontrado neste estoque.',v_item_id USING ERRCODE='P0002';
    END IF;
    v_total_item:=round(v_qtd*v_custo-v_desc+v_frete+v_outras,2);
    IF v_total_item<0 THEN RAISE EXCEPTION 'Total do item invalido.' USING ERRCODE='22023'; END IF;
    INSERT INTO public.usoconsumo_entrada_item(
      entrada_id,item_id,numero_item_fiscal,codigo_fornecedor,quantidade,unidade,valor_unitario_compra,
      valor_desconto,valor_frete,outras_despesas,valor_total,saldo_anterior,saldo_resultante,ncm,cest,csosn,
      referencia,titulo,cst,aliquotaicms,cfop,cst_pis,aliquota_pis,cst_cofins,aliquota_cofins,cst_ibscbs,
      cclass_trib,aliquota_ibs_uf,aliquota_ibs_municipio,aliquota_cbs
    ) VALUES(
      v_entrada_id,v_item_id,v_numero_item,nullif(v_item_json->>'codigo_fornecedor',''),v_qtd,
      coalesce(nullif(v_item_json->>'unidade','')::public.unidade_medida,v_item.unidade),v_custo,v_desc,v_frete,v_outras,
      v_total_item,v_item.estoque,v_item.estoque+v_qtd,coalesce(nullif(v_item_json->>'ncm',''),v_item.ncm),
      coalesce(nullif(v_item_json->>'cest',''),v_item.cest),coalesce(nullif(v_item_json->>'csosn',''),v_item.csosn),
      coalesce(nullif(v_item_json->>'referencia',''),v_item.referencia),coalesce(nullif(v_item_json->>'titulo',''),v_item.titulo),
      coalesce(nullif(v_item_json->>'cst',''),v_item.cst),coalesce(nullif(v_item_json->>'aliquotaicms','')::numeric,v_item.aliquotaicms),
      coalesce(nullif(v_item_json->>'cfop',''),v_item.cfop_entrada),coalesce(nullif(v_item_json->>'cst_pis',''),v_item.cst_pis),
      coalesce(nullif(v_item_json->>'aliquota_pis','')::numeric,v_item.aliquota_pis),
      coalesce(nullif(v_item_json->>'cst_cofins',''),v_item.cst_cofins),coalesce(nullif(v_item_json->>'aliquota_cofins','')::numeric,v_item.aliquota_cofins),
      coalesce(nullif(v_item_json->>'cst_ibscbs',''),v_item.cst_ibscbs),coalesce(nullif(v_item_json->>'cclass_trib',''),v_item.cclass_trib),
      coalesce(nullif(v_item_json->>'aliquota_ibs_uf','')::numeric,v_item.aliquota_ibs_uf),
      coalesce(nullif(v_item_json->>'aliquota_ibs_municipio','')::numeric,v_item.aliquota_ibs_municipio),
      coalesce(nullif(v_item_json->>'aliquota_cbs','')::numeric,v_item.aliquota_cbs)
    ) RETURNING id INTO v_entrada_item_id;
    PERFORM set_config('app.usoconsumo_movimento','permitido',true);
    UPDATE public.usoconsumo_item SET estoque=estoque+v_qtd,ultimovalordecompra=v_custo,updated_by=v_user WHERE id=v_item_id;
    INSERT INTO public.usoconsumo_movimento_entrada(
      entrada_id,entrada_item_id,item_id,tipo,quantidade,saldo_anterior,saldo_resultante,valor_unitario_compra,created_by
    ) VALUES(v_entrada_id,v_entrada_item_id,v_item_id,'ENTRADA',v_qtd,v_item.estoque,v_item.estoque+v_qtd,v_custo,v_user);
    IF nullif(p_entrada->>'fornecedor_id','') IS NOT NULL THEN
      INSERT INTO public.usoconsumo_fornecedor_item(fornecedor_id,item_id,codigo_fornecedor,ultimo_valor_compra)
      VALUES((p_entrada->>'fornecedor_id')::integer,v_item_id,nullif(v_item_json->>'codigo_fornecedor',''),v_custo)
      ON CONFLICT(fornecedor_id,item_id) DO UPDATE SET
        codigo_fornecedor=coalesce(EXCLUDED.codigo_fornecedor,usoconsumo_fornecedor_item.codigo_fornecedor),
        ultimo_valor_compra=EXCLUDED.ultimo_valor_compra,updated_at=now();
    END IF;
    IF v_fiscal AND v_documento_id IS NOT NULL THEN
      INSERT INTO public.fiscal_dfe_item_apropriacao(
        documento_id,numero_item,destino,usoconsumo_entrada_id,quantidade,created_by
      ) VALUES(v_documento_id,v_numero_item,'USOCONSUMO',v_entrada_id,v_qtd,v_user);
    END IF;
    v_total:=v_total+v_total_item;
  END LOOP;

  v_total_devido := round(coalesce(v_total_documento, v_total),2);
  UPDATE public.usoconsumo_entrada SET valor_total=v_total_devido WHERE id=v_entrada_id;

  IF jsonb_typeof(p_transacoes)='array' AND jsonb_array_length(p_transacoes)>0 THEN
    SELECT round(coalesce(sum((value->>'valor')::numeric),0),2) INTO v_total_fin FROM jsonb_array_elements(p_transacoes);
    IF v_total_fin<>v_total_devido THEN
      RAISE EXCEPTION 'A soma dos lancamentos financeiros (%) difere do total da entrada (%).',
        v_total_fin, v_total_devido USING ERRCODE='22023';
    END IF;
    FOR v_tx IN SELECT value FROM jsonb_array_elements(p_transacoes) LOOP
      IF coalesce(nullif(v_tx->>'valor','')::numeric,0)<=0 THEN
        RAISE EXCEPTION 'Valor financeiro invalido.' USING ERRCODE='22023';
      END IF;
      INSERT INTO public.transacao(
        descricao,valor,"valorLiquido",data,vencimento_em,metodopagamento,categoria,categoria_id,tipo,cliente_id,
        banco_id,nomepagador,cpfcnpjpagador,pendente,plano_de_conta_id,plano_de_conta,centro_custo_id,
        centro_custo,usoconsumo_entrada_id,origem,created_by
      ) VALUES(
        coalesce(nullif(v_tx->>'descricao',''),v_rotulo),(v_tx->>'valor')::numeric,
        (v_tx->>'valor')::numeric,coalesce(nullif(v_tx->>'data','')::timestamptz,now()),
        nullif(v_tx->>'vencimento_em','')::timestamptz,nullif(v_tx->>'metodopagamento','')::public.metodo_pagamento,
        coalesce(nullif(v_tx->>'categoria',''),v_rotulo),
        nullif(v_tx->>'categoria_id','')::integer,'DESPESA',NULL,nullif(v_tx->>'banco_id','')::bigint,
        coalesce(nullif(v_tx->>'nomepagador',''),'Fornecedor'),
        coalesce(nullif(regexp_replace(v_tx->>'cpfcnpjpagador','\D','','g'),''),'NAO INFORMADO'),
        coalesce((v_tx->>'pendente')::boolean,false),nullif(v_tx->>'plano_de_conta_id','')::integer,
        nullif(v_tx->>'plano_de_conta',''),nullif(v_tx->>'centro_custo_id','')::integer,
        nullif(v_tx->>'centro_custo',''),v_entrada_id,'USOCONSUMO_ENTRADA',v_user
      );
    END LOOP;
  END IF;
  RETURN jsonb_build_object('entrada_id',v_entrada_id,'valor_total',v_total_devido,'escopo',v_escopo);
END $function$

CREATE OR REPLACE FUNCTION public.responder_aprovacao_venda(p_token uuid, p_documento text, p_acao text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_token public.vendaaprovacao%ROWTYPE;
  v_venda public.venda%ROWTYPE;
  v_documento_cliente text;
  v_documento text := regexp_replace(coalesce(p_documento, ''), '\D', '', 'g');
  v_acao text := upper(btrim(coalesce(p_acao, '')));
  v_resultado public.enum_status_aprovacao;
  v_novo_status public.enum_status_venda;
BEGIN
  IF v_acao NOT IN ('APROVAR', 'REPROVAR') THEN
    RAISE EXCEPTION 'Ação de aprovação inválida.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_token
    FROM public.vendaaprovacao
   WHERE token = p_token
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Link de aprovação inválido.' USING ERRCODE = 'P0002';
  END IF;
  IF v_token.usado_em IS NOT NULL OR v_token.invalidado_em IS NOT NULL OR v_token.expira_em <= now() THEN
    RAISE EXCEPTION 'Este link não está mais disponível para resposta.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_venda
    FROM public.venda
   WHERE id = v_token.vendaid
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Venda não encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF v_venda.status::text <> 'APROVACAO_ORCAMENTO'
     OR v_venda.statusaprovacao::text IS DISTINCT FROM 'PENDENTE' THEN
    RAISE EXCEPTION 'Este orçamento não está aguardando aprovação.' USING ERRCODE = '22023';
  END IF;

  SELECT regexp_replace(coalesce(c.cpfcnpj, ''), '\D', '', 'g')
    INTO v_documento_cliente
    FROM public.cliente c
   WHERE c.id = v_venda.clienteid;
  IF v_documento = '' OR v_documento IS DISTINCT FROM v_documento_cliente THEN
    RAISE EXCEPTION 'Documento não confere para este orçamento.' USING ERRCODE = '22023';
  END IF;

  v_resultado := CASE WHEN v_acao = 'APROVAR' THEN 'APROVADA' ELSE 'REPROVADA' END;
  v_novo_status := CASE
    WHEN v_acao = 'APROVAR' THEN 'ORCAMENTO_APROVADO'::public.enum_status_venda
    ELSE 'ORCAMENTO_RECUSADO'::public.enum_status_venda
  END;

  UPDATE public.vendaaprovacao
     SET usado_em = now(),
         origem = 'LINK',
         resultado = v_resultado,
         aprovador_doc = v_documento
   WHERE id = v_token.id
     AND usado_em IS NULL
     AND invalidado_em IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Este link já foi respondido.' USING ERRCODE = '22023';
  END IF;

  UPDATE public.venda
     SET status = v_novo_status,
         statusaprovacao = v_resultado,
         updatedat = now()
   WHERE id = v_venda.id;

  RETURN jsonb_build_object(
    'vendaId', v_venda.id,
    'status', v_novo_status::text,
    'statusaprovacao', v_resultado
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.registrar_entrada_fiscal_mista(p_entrada_produto jsonb, p_itens_produto jsonb, p_entrada_usoconsumo jsonb, p_itens_usoconsumo jsonb, p_transacoes jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_res_produto jsonb;
  v_res_uso jsonb;
  v_entrada_id bigint;
  v_uso_entrada_id bigint;
  v_entrada_produto jsonb;
  v_entrada_uso jsonb;
  v_documento_id bigint := nullif(p_entrada_produto->>'fiscal_dfe_documento_id','')::bigint;
  v_total numeric(14,2);
  v_total_itens numeric(14,2);
  v_total_documento numeric(14,2) := nullif(p_entrada_produto->>'valor_total_documento','')::numeric;
  v_total_fin numeric(14,2);
  v_tx jsonb;
  v_user uuid := nullif(p_entrada_produto->>'created_by','')::uuid;
BEGIN
  IF jsonb_typeof(p_itens_produto) <> 'array' OR jsonb_array_length(p_itens_produto) = 0
     OR jsonb_typeof(p_itens_usoconsumo) <> 'array' OR jsonb_array_length(p_itens_usoconsumo) = 0 THEN
    RAISE EXCEPTION 'A entrada mista exige ao menos um item de estoque e um item de uso e consumo.'
      USING ERRCODE = '22023';
  END IF;

  IF v_total_documento IS NOT NULL AND v_total_documento < 0 THEN
    RAISE EXCEPTION 'O total do documento fiscal não pode ser negativo.' USING ERRCODE = '22023';
  END IF;

  -- Sem valor_total_documento a entrada de estoque fecha pelo total dos seus proprios
  -- itens, e nao pelo total da NF-e (que inclui a parte de uso e consumo). O mesmo
  -- vale agora para a metade de uso e consumo, que ganhou a mesma válvula.
  v_entrada_produto := p_entrada_produto - 'valor_total_documento';
  v_entrada_uso := p_entrada_usoconsumo - 'valor_total_documento';

  -- As duas entradas sao gravadas sem transacoes: o pagamento e unico e vem depois.
  IF v_documento_id IS NOT NULL THEN
    SELECT public.registrar_entrada_comercial_apropriada(v_entrada_produto, p_itens_produto, '[]'::jsonb)
      INTO v_res_produto;
  ELSE
    SELECT public.registrar_entrada_confirmada(v_entrada_produto, p_itens_produto, '[]'::jsonb)
      INTO v_res_produto;
  END IF;
  v_entrada_id := (v_res_produto->>'entrada_id')::bigint;

  SELECT public.registrar_entrada_usoconsumo(v_entrada_uso, p_itens_usoconsumo, '[]'::jsonb)
    INTO v_res_uso;
  v_uso_entrada_id := (v_res_uso->>'entrada_id')::bigint;

  v_total_itens := round(
    coalesce((v_res_produto->>'valor_total')::numeric, 0)
    + coalesce((v_res_uso->>'valor_total')::numeric, 0), 2);

  -- O documento manda quando informado: é ele que o fornecedor cobra, e é contra
  -- ele que as duplicatas fecham. Sem ele, vale a soma das duas entradas.
  v_total := round(coalesce(v_total_documento, v_total_itens), 2);

  IF jsonb_typeof(p_transacoes) = 'array' AND jsonb_array_length(p_transacoes) > 0 THEN
    SELECT round(coalesce(sum((value->>'valor')::numeric), 0), 2)
      INTO v_total_fin
      FROM jsonb_array_elements(p_transacoes);
    IF v_total_fin <> v_total THEN
      RAISE EXCEPTION 'A soma dos lancamentos financeiros (%) difere do total da nota (%).',
        v_total_fin, v_total USING ERRCODE = '22023';
    END IF;

    FOR v_tx IN SELECT value FROM jsonb_array_elements(p_transacoes) LOOP
      IF coalesce(nullif(v_tx->>'valor','')::numeric, 0) <= 0 THEN
        RAISE EXCEPTION 'O valor do lancamento financeiro deve ser positivo.' USING ERRCODE = '22023';
      END IF;
      INSERT INTO public.transacao(
        descricao, valor, "valorLiquido", data, vencimento_em, metodopagamento, categoria, categoria_id,
        tipo, cliente_id, banco_id, nomepagador, cpfcnpjpagador, pendente, plano_de_conta_id,
        plano_de_conta, centro_custo_id, centro_custo, entrada_id, usoconsumo_entrada_id, origem, created_by
      ) VALUES (
        coalesce(nullif(v_tx->>'descricao',''), 'Compra de mercadorias'),
        (v_tx->>'valor')::numeric,
        (v_tx->>'valor')::numeric,
        coalesce(nullif(v_tx->>'data','')::timestamptz, now()),
        nullif(v_tx->>'vencimento_em','')::timestamptz,
        nullif(v_tx->>'metodopagamento','')::public.metodo_pagamento,
        coalesce(nullif(v_tx->>'categoria',''), 'NAO RELACIONADO'),
        nullif(v_tx->>'categoria_id','')::integer,
        'DESPESA'::public.tipos_transacao,
        NULL,
        nullif(v_tx->>'banco_id','')::bigint,
        coalesce(nullif(v_tx->>'nomepagador',''), 'Fornecedor'),
        coalesce(nullif(regexp_replace(v_tx->>'cpfcnpjpagador','\D','','g'),''), 'NAO INFORMADO'),
        coalesce((v_tx->>'pendente')::boolean, false),
        nullif(v_tx->>'plano_de_conta_id','')::integer,
        nullif(v_tx->>'plano_de_conta',''),
        nullif(v_tx->>'centro_custo_id','')::integer,
        nullif(v_tx->>'centro_custo',''),
        v_entrada_id,
        v_uso_entrada_id,
        'ENTRADA_FISCAL_MISTA',
        v_user
      );
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'entrada_id', v_entrada_id,
    'usoconsumo_entrada_id', v_uso_entrada_id,
    'valor_total', v_total
  );
END $function$

CREATE OR REPLACE FUNCTION public.tg_transacao_baixa_parcial()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF old.baixa_de_transacao_id IS NOT NULL THEN
      PERFORM public.recalcular_baixas_transacao(old.baixa_de_transacao_id);
    END IF;
    RETURN old;
  END IF;

  IF new.baixa_de_transacao_id IS NOT NULL THEN
    PERFORM public.recalcular_baixas_transacao(new.baixa_de_transacao_id);
  END IF;

  -- Mover ou apagar logicamente uma filha tem que acertar as duas pontas.
  IF TG_OP = 'UPDATE'
     AND old.baixa_de_transacao_id IS NOT NULL
     AND old.baixa_de_transacao_id IS DISTINCT FROM new.baixa_de_transacao_id THEN
    PERFORM public.recalcular_baixas_transacao(old.baixa_de_transacao_id);
  END IF;

  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_criar_venda_mercadolivre_reservada(p_ml_order_id bigint, p_empresa_id integer, p_venda jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_venda_id integer;
  v_import_status text;
BEGIN
  SELECT venda_id, import_status
    INTO v_venda_id, v_import_status
    FROM public.mercadolivre_order
   WHERE ml_order_id = p_ml_order_id
     AND empresa_id = p_empresa_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Pedido Mercado Livre % não encontrado.', p_ml_order_id;
  END IF;

  IF v_venda_id IS NOT NULL THEN
    RETURN v_venda_id;
  END IF;

  IF v_import_status <> 'PROCESSANDO' THEN
    RAISE EXCEPTION 'Pedido Mercado Livre % não está reservado para importação.', p_ml_order_id;
  END IF;

  v_venda_id := public.fn_criar_venda_marketplace_com_itens(p_venda);

  UPDATE public.mercadolivre_order
     SET venda_id = v_venda_id,
         import_status = 'IMPORTADA',
         import_locked_at = NULL,
         import_error = NULL,
         updated_at = now()
   WHERE ml_order_id = p_ml_order_id
     AND empresa_id = p_empresa_id;

  RETURN v_venda_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.habilitar_auditoria_tabela(nome_tabela regclass)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  schema_nome text;
  tabela_nome text;
begin
  select n.nspname, c.relname
    into schema_nome, tabela_nome
  from pg_class c
  join pg_namespace n on n.oid = c.relnamespace
  where c.oid = nome_tabela;

  if schema_nome <> 'public' or tabela_nome = 'auditoria_evento' then
    raise exception 'A auditoria so pode ser habilitada em tabelas de negocio do schema public';
  end if;

  execute format('drop trigger if exists auditoria_linha on %I.%I', schema_nome, tabela_nome);
  execute format(
    'create trigger auditoria_linha after insert or update or delete on %I.%I for each row execute function public.registrar_auditoria()',
    schema_nome,
    tabela_nome
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.auditoria_contexto_externo_requisicao()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  claims_raw text := nullif(current_setting('request.jwt.claims', true), '');
  headers_raw text := nullif(current_setting('request.headers', true), '');
  headers_json jsonb;
  tipo text;
  nome text;
begin
  if claims_raw is null or headers_raw is null then
    return null;
  end if;
  if claims_raw::jsonb ->> 'role' <> 'service_role' then
    return null;
  end if;

  headers_json := headers_raw::jsonb;
  tipo := lower(coalesce(headers_json ->> 'x-audit-actor-type', ''));
  if tipo <> 'cliente' then
    return null;
  end if;

  nome := left(nullif(btrim(headers_json ->> 'x-audit-actor-name'), ''), 120);
  return jsonb_build_object(
    'origem', tipo,
    'nome', coalesce(nome, 'Cliente via link de aprovacao')
  );
exception when others then
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.tg_transacao_valor_apos_baixa()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF round(coalesce(new.valor, 0), 2) = round(coalesce(old.valor, 0), 2) THEN
    RETURN new;
  END IF;

  IF coalesce(old.pendente, false) = false THEN
    RAISE EXCEPTION
      'O valor de uma transação já baixada não pode ser alterado. Tire-a do fluxo de caixa primeiro: o título volta a ficar em aberto e o valor volta a ser editável.'
      USING ERRCODE = '22023';
  END IF;

  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_transacao_ajuste_coerente()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_natureza text;
  v_ativo boolean;
  v_pendente boolean;
BEGIN
  SELECT natureza, ativo INTO v_natureza, v_ativo
    FROM public.tipos_ajuste_transacao WHERE id = new.tipo_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tipo de ajuste nao encontrado.' USING ERRCODE = 'P0002';
  END IF;
  IF v_ativo IS NOT TRUE THEN
    RAISE EXCEPTION 'Tipo de ajuste inativo.' USING ERRCODE = '22023';
  END IF;
  IF new.natureza <> v_natureza THEN
    RAISE EXCEPTION 'A natureza informada nao confere com a do tipo escolhido.'
      USING ERRCODE = '22023';
  END IF;

  -- Acrescimo altera o bruto, e bruto de transacao baixada e imutavel (ver
  -- 20260806120000_travar_valor_apos_baixa). Recusar aqui da mensagem util em
  -- vez de deixar estourar a trava do `valor`, que falaria de outra coisa.
  -- Desconto mexe so no liquido e segue liberado: a taxa da maquineta costuma
  -- ser conhecida depois do pagamento.
  IF new.natureza = 'ACRESCIMO' THEN
    SELECT pendente INTO v_pendente FROM public.transacao WHERE id = new.transacao_id;
    IF coalesce(v_pendente, false) = false THEN
      RAISE EXCEPTION
        'Nao da para lancar acrescimo em transacao ja baixada, porque ele altera o valor bruto.'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_transacao_ajuste_recalcular()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF tg_op = 'DELETE' THEN
    PERFORM public.recalcular_valores_transacao(old.transacao_id);
    RETURN old;
  END IF;

  PERFORM public.recalcular_valores_transacao(new.transacao_id);
  -- Mover a linha de uma transacao para outra tem que acertar as duas pontas.
  IF tg_op = 'UPDATE' AND old.transacao_id <> new.transacao_id THEN
    PERFORM public.recalcular_valores_transacao(old.transacao_id);
  END IF;

  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_transacao_valor_coerente()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF new.valor IS DISTINCT FROM old.valor THEN
    new.valor_base := round(coalesce(new.valor, 0) - coalesce(new.valor_acrescimos, 0), 2);
  END IF;

  -- Havendo desconto lancado, o liquido e resultado, nao entrada: qualquer valor
  -- que o chamador tenha mandado seria uma segunda verdade sobre o mesmo numero.
  IF coalesce(new.valor_descontos, 0) > 0 THEN
    new."valorLiquido" := round(coalesce(new.valor, 0) - new.valor_descontos, 2);

  -- Sem desconto lancado o liquido segue livre — e assim que os registros
  -- antigos guardam a taxa da maquineta. Livre ate o bruto, nao alem dele:
  -- receber liquido mais do que o valor da transacao nao existe.
  ELSIF coalesce(new."valorLiquido", 0) > coalesce(new.valor, 0) THEN
    new."valorLiquido" := new.valor;
  END IF;

  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_recalcular_status_financeiro_os()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old_os integer;
  v_new_os integer;
BEGIN
  IF TG_OP <> 'INSERT'
     AND OLD.ordemservicoid IS NOT NULL
     AND upper(OLD.tipo::text) = 'RECEITA'
     AND OLD.evento_financeiro_id IS NULL THEN
    v_old_os := OLD.ordemservicoid;
  END IF;

  IF TG_OP <> 'DELETE'
     AND NEW.ordemservicoid IS NOT NULL
     AND upper(NEW.tipo::text) = 'RECEITA'
     AND NEW.evento_financeiro_id IS NULL THEN
    v_new_os := NEW.ordemservicoid;
  END IF;

  IF v_old_os IS NOT NULL THEN
    PERFORM public.recalcular_status_financeiro_os(v_old_os);
  END IF;
  IF v_new_os IS NOT NULL AND v_new_os IS DISTINCT FROM v_old_os THEN
    PERFORM public.recalcular_status_financeiro_os(v_new_os);
  END IF;

  -- Transação de pagamento múltiplo não aponta para documento nenhum: quem sabe
  -- quais ela tocou é o rateio.
  IF TG_OP = 'DELETE' THEN
    IF OLD.pagamento_multiplo_id IS NOT NULL THEN
      PERFORM public.recalcular_documentos_da_transacao(OLD.id);
    END IF;
    RETURN OLD;
  END IF;

  IF NEW.pagamento_multiplo_id IS NOT NULL THEN
    PERFORM public.recalcular_documentos_da_transacao(NEW.id);
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_editar_venda_com_itens(p_venda_id integer, p_itens jsonb, p_sub_total numeric, p_valor_total numeric, p_desconto_tipo text DEFAULT NULL::text, p_desconto_valor numeric DEFAULT 0, p_valor_frete numeric DEFAULT 0, p_updated_by uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_status text;
  v_tinha_baixa boolean;
  v_item jsonb;
  v_produto_id integer;
  v_quantidade integer;
  v_sub_total numeric(14,2);
  v_valor_total numeric(14,2);
  v_valor_desconto numeric(14,2);
  v_tipo_desconto public.enum_tipo_desconto_venda;
  v_desconto_aplicado numeric(14,2);
  v_valor_frete_item numeric(14,2);
  v_ids_solicitados integer;
  v_ids_encontrados integer;
  v_soma_itens numeric(14,2);
BEGIN
  SELECT status::text
    INTO v_status
    FROM public.venda
   WHERE id = p_venda_id
   FOR UPDATE;

  IF v_status IS NULL THEN
    RAISE EXCEPTION 'Venda não encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF v_status IN ('PAGO', 'FINALIZADA', 'CANCELADA', 'CANCELADO') THEN
    RAISE EXCEPTION 'Os itens não podem ser alterados em uma venda paga, finalizada ou cancelada.'
      USING ERRCODE = 'P0001';
  END IF;
  IF EXISTS (SELECT 1 FROM public.nfe WHERE vendaid = p_venda_id) THEN
    RAISE EXCEPTION 'Exclua a NF-e em rascunho antes de alterar os itens da venda.'
      USING ERRCODE = 'P0001';
  END IF;
  IF jsonb_typeof(p_itens) <> 'array' OR jsonb_array_length(p_itens) = 0 THEN
    RAISE EXCEPTION 'A venda deve possuir ao menos um item.' USING ERRCODE = 'P0001';
  END IF;

  SELECT count(DISTINCT (value->>'produtoId')::integer)
    INTO v_ids_solicitados
    FROM jsonb_array_elements(p_itens);
  SELECT count(*)
    INTO v_ids_encontrados
    FROM public.produto
   WHERE id IN (
     SELECT DISTINCT (value->>'produtoId')::integer FROM jsonb_array_elements(p_itens)
   );
  IF v_ids_solicitados <> v_ids_encontrados THEN
    RAISE EXCEPTION 'Um ou mais produtos não existem.' USING ERRCODE = 'P0001';
  END IF;

  PERFORM 1
    FROM public.produto
   WHERE id IN (
     SELECT DISTINCT (value->>'produtoId')::integer FROM jsonb_array_elements(p_itens)
   )
   ORDER BY id
   FOR UPDATE;

  SELECT round(coalesce(sum((value->>'subTotal')::numeric), 0), 2)
    INTO v_soma_itens
    FROM jsonb_array_elements(p_itens);
  IF v_soma_itens <> round(coalesce(p_sub_total, 0), 2) THEN
    RAISE EXCEPTION 'O subtotal da venda não corresponde à soma dos itens.' USING ERRCODE = 'P0001';
  END IF;
  IF coalesce(p_sub_total, 0) < 0 OR coalesce(p_valor_total, 0) < 0
     OR coalesce(p_desconto_valor, 0) < 0 OR coalesce(p_valor_frete, 0) < 0 THEN
    RAISE EXCEPTION 'Os valores financeiros da venda não podem ser negativos.' USING ERRCODE = 'P0001';
  END IF;

  v_tinha_baixa := EXISTS (
    SELECT 1 FROM public.vendaproduto_baixa WHERE venda_id = p_venda_id
  );
  IF v_tinha_baixa THEN
    PERFORM public.fn_estornar_estoque_venda(p_venda_id);
  END IF;

  DELETE FROM public.vendaproduto WHERE venda_id = p_venda_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_itens) LOOP
    v_produto_id := (v_item->>'produtoId')::integer;
    v_quantidade := (v_item->>'quantidade')::integer;
    v_sub_total := round((v_item->>'subTotal')::numeric, 2);
    v_valor_total := round((v_item->>'valorTotal')::numeric, 2);
    v_valor_desconto := round(coalesce(nullif(v_item->>'valorDesconto', '')::numeric, 0), 2);
    v_tipo_desconto := nullif(v_item->>'tipoDesconto', '')::public.enum_tipo_desconto_venda;
    v_valor_frete_item := round(coalesce(nullif(v_item->>'valorFrete', '')::numeric, 0), 2);
    v_desconto_aplicado := CASE
      WHEN v_tipo_desconto::text = 'PORCENTAGEM'
        THEN round(v_sub_total * least(v_valor_desconto, 100) / 100, 2)
      WHEN v_tipo_desconto::text = 'FIXO'
        THEN least(v_sub_total, v_valor_desconto)
      ELSE 0
    END;

    IF v_produto_id IS NULL OR v_quantidade IS NULL OR v_quantidade <= 0
       OR v_sub_total < 0 OR v_valor_total < 0 OR v_valor_desconto < 0
       OR v_valor_frete_item < 0
       OR (v_tipo_desconto::text = 'PORCENTAGEM' AND v_valor_desconto > 100)
       OR v_valor_total <> round(v_sub_total - v_desconto_aplicado + v_valor_frete_item, 2) THEN
      RAISE EXCEPTION 'Dados inválidos em um dos itens da venda.' USING ERRCODE = 'P0001';
    END IF;

    INSERT INTO public.vendaproduto (
      venda_id, produtoid, quantidade, sub_total, valor_total,
      valor_desconto, tipo_desconto, valor_frete
    ) VALUES (
      p_venda_id, v_produto_id, v_quantidade, v_sub_total, v_valor_total,
      v_valor_desconto, v_tipo_desconto, v_valor_frete_item
    );
  END LOOP;

  UPDATE public.venda
     SET sub_total = round(p_sub_total, 2),
         valortotal = round(p_valor_total, 2),
         desconto_tipo = nullif(p_desconto_tipo, '')::public.enum_tipo_desconto_venda,
         desconto_valor = round(coalesce(p_desconto_valor, 0), 2),
         valor_frete = round(coalesce(p_valor_frete, 0), 2),
         updated_by = coalesce(p_updated_by, updated_by),
         updatedat = now()
   WHERE id = p_venda_id;

  IF v_tinha_baixa THEN
    PERFORM public.fn_baixar_estoque_venda(p_venda_id);
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.auditoria_json_seguro(valor jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  resultado jsonb;
begin
  if valor is null then
    return null;
  end if;

  if jsonb_typeof(valor) = 'object' then
    select coalesce(
      jsonb_object_agg(
        chave,
        case
          when lower(chave) ~ '(senha|password|secret|token|certificado|private.?key|access.?key|refresh.?key|authorization)'
            then '"[PROTEGIDO]"'::jsonb
          else public.auditoria_json_seguro(item)
        end
      ),
      '{}'::jsonb
    )
    into resultado
    from jsonb_each(valor) as entrada(chave, item);
    return resultado;
  end if;

  if jsonb_typeof(valor) = 'array' then
    select coalesce(jsonb_agg(public.auditoria_json_seguro(item)), '[]'::jsonb)
      into resultado
    from jsonb_array_elements(valor) as entrada(item);
    return resultado;
  end if;

  return valor;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_baixa_estoque_produto(p_produto_id integer, p_quantidade integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_estoque integer;
begin
  -- quantidade inválida: não faz nada
  if p_quantidade is null or p_quantidade <= 0 then
    return;
  end if;

  -- trava a linha para evitar corrida de concorrência
  select estoque
    into v_estoque
  from produto
  where id = p_produto_id
  for update;

  if v_estoque is null then
    raise exception 'Produto % não encontrado para baixa de estoque.', p_produto_id
      using errcode = 'P0001';
  end if;

  if v_estoque < p_quantidade then
    raise exception 'Estoque insuficiente para produto %, em estoque: %, necessário: %',
      p_produto_id, v_estoque, p_quantidade
      using errcode = 'P0001';
  end if;

  update produto
    set estoque = estoque - p_quantidade,
        updatedat = now()
  where id = p_produto_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.nfe_alocar_numero(p_config_id bigint)
 RETURNS TABLE(numero integer, serie integer, empresaid bigint, modelo enum_modelo_nfe, ambiente enum_ambiente_nfe)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_config public.nfe_config%ROWTYPE;
  v_reaproveitado integer;
BEGIN
  SELECT *
    INTO v_config
    FROM public.nfe_config
   WHERE id = p_config_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Configuração de NF-e % não encontrada.', p_config_id;
  END IF;

  -- O lock na config acima serializa as alocações concorrentes.
  DELETE FROM public.nfe_numero_liberado l
   WHERE l.id = (
     SELECT candidato.id
       FROM public.nfe_numero_liberado candidato
      WHERE candidato.config_id = p_config_id
        AND candidato.serie = v_config.serie
      ORDER BY candidato.numero
      LIMIT 1
   )
  RETURNING l.numero INTO v_reaproveitado;

  IF v_reaproveitado IS NOT NULL THEN
    numero := v_reaproveitado;
    serie := v_config.serie;
    empresaid := v_config.empresaid;
    modelo := v_config.modelo;
    ambiente := v_config.ambiente;
    RETURN NEXT;
    RETURN;
  END IF;

  UPDATE public.nfe_config
     SET ultimo_numero = COALESCE(ultimo_numero, 0) + 1,
         updatedat = now()
   WHERE id = p_config_id
   RETURNING ultimo_numero, nfe_config.serie, nfe_config.empresaid, nfe_config.modelo, nfe_config.ambiente
    INTO numero, serie, empresaid, modelo, ambiente;

  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_criar_venda_shopee_reservada(p_order_sn text, p_empresa_id integer, p_venda jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_venda_id integer;
  v_import_status text;
begin
  select venda_id, import_status
    into v_venda_id, v_import_status
    from public.shopee_order
   where order_sn = p_order_sn and empresa_id = p_empresa_id
   for update;

  if not found then raise exception 'Pedido Shopee % não encontrado.', p_order_sn; end if;
  if v_venda_id is not null then return v_venda_id; end if;
  if v_import_status <> 'PROCESSANDO' then raise exception 'Pedido Shopee % não está reservado para importação.', p_order_sn; end if;

  v_venda_id := public.fn_criar_venda_marketplace_com_itens(p_venda);
  update public.shopee_order
     set venda_id = v_venda_id,
         import_status = 'IMPORTADA',
         import_locked_at = null,
         import_error = null,
         updated_at = now()
   where order_sn = p_order_sn and empresa_id = p_empresa_id;
  return v_venda_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.cancelar_venda(p_venda_id bigint, p_motivo text, p_cancelada_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_venda public.venda%ROWTYPE;
  v_motivo text := nullif(btrim(p_motivo), '');
  v_transacoes_excluidas integer := 0;
  v_produtos_devolvidos integer := 0;
BEGIN
  IF v_motivo IS NULL OR char_length(v_motivo) < 3 THEN
    RAISE EXCEPTION 'Informe um motivo com pelo menos 3 caracteres.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_venda FROM public.venda WHERE id = p_venda_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Venda não encontrada.' USING ERRCODE = 'P0002'; END IF;
  IF v_venda.status::text IN ('CANCELADA', 'CANCELADO') THEN
    RAISE EXCEPTION 'Esta venda já está cancelada.' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.nfe
    WHERE vendaid = p_venda_id AND status::text NOT IN ('RASCUNHO', 'CANCELADA', 'REJEITADA')
  ) THEN
    RAISE EXCEPTION 'Cancele a NF-e autorizada ou em processamento antes de cancelar a venda.' USING ERRCODE = '23514';
  END IF;

  SELECT count(*)::integer INTO v_produtos_devolvidos
  FROM public.vendaproduto_baixa WHERE venda_id = p_venda_id;
  PERFORM public.fn_estornar_estoque_venda(p_venda_id::integer);

  -- Decisão temporária: remove todas as transações por exclusão lógica e não
  -- cria lançamentos inversos. Os registros continuam no banco para auditoria.
  UPDATE public.transacao
  SET pendente = false, is_deleted = true, deleted_at = now(), deleted_by = p_cancelada_by,
      updated_at = now(), updated_by = p_cancelada_by
  WHERE vendaid = p_venda_id AND NOT is_deleted;
  GET DIAGNOSTICS v_transacoes_excluidas = ROW_COUNT;

  UPDATE public.venda
  SET status = 'CANCELADA', motivo_cancelamento = v_motivo, cancelada_at = now(),
      cancelada_by = p_cancelada_by, updated_by = p_cancelada_by, updatedat = now(), status_entrega = NULL
  WHERE id = p_venda_id;

  RETURN jsonb_build_object(
    'vendaId', p_venda_id, 'status', 'CANCELADA',
    'produtosDevolvidos', v_produtos_devolvidos,
    'transacoesExcluidas', v_transacoes_excluidas,
    'estornosCriados', 0
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_criar_venda_com_itens(p_venda jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cliente_id integer := (p_venda->>'clienteId')::integer;
  v_created_by uuid := (p_venda->>'created_by')::uuid;
  v_status public.enum_status_venda := (p_venda->>'status')::public.enum_status_venda;
  v_baixar_estoque boolean := coalesce((p_venda->>'baixarEstoque')::boolean, true);
  v_valor_frete numeric(14,2) := round(coalesce(nullif(p_venda->>'valorFrete', '')::numeric, 0), 2);
  v_venda_id integer;
  v_item jsonb;
  v_produto_id integer;
  v_quantidade integer;
  v_item_sub_total numeric(14,2);
  v_item_valor_total numeric(14,2);
  v_item_valor_desconto numeric(14,2);
  v_item_tipo_desconto public.enum_tipo_desconto_venda;
  v_item_desconto_aplicado numeric(14,2);
  v_item_valor_frete numeric(14,2);
  v_comissao numeric;
BEGIN
  IF v_cliente_id IS NULL OR v_created_by IS NULL OR v_status IS NULL
     OR p_venda->>'subTotal' IS NULL OR p_venda->>'valorTotal' IS NULL THEN
    RAISE EXCEPTION 'Campos obrigatórios ausentes em p_venda.' USING ERRCODE = 'P0001';
  END IF;
  IF v_valor_frete < 0 THEN
    RAISE EXCEPTION 'O valor do frete não pode ser negativo.' USING ERRCODE = 'P0001';
  END IF;
  IF jsonb_typeof(p_venda->'itens') <> 'array' OR jsonb_array_length(p_venda->'itens') = 0 THEN
    RAISE EXCEPTION 'p_venda.itens deve possuir ao menos um item.' USING ERRCODE = 'P0001';
  END IF;

  SELECT coalesce(comissao_venda_percent, 0)
    INTO v_comissao
    FROM public.usuario
   WHERE id = v_created_by;

  INSERT INTO public.venda (
    clienteid, created_by, vendedor, status, statusaprovacao,
    forma_pagamento, pagamentos_previstos, parcelas_pagamento,
    descricao, observacoes, descricao_financeiro, observacoes_fiscais, garantia,
    sub_total, valortotal, desconto_tipo, desconto_valor, valor_frete, datavenda,
    comissao_venda_percent_aplicada, categoriavendaid
  ) VALUES (
    v_cliente_id,
    v_created_by,
    coalesce(nullif(p_venda->>'vendedor', '')::uuid, v_created_by),
    v_status,
    NULL,
    nullif(p_venda->>'formaPagamento', ''),
    nullif(p_venda->'pagamentosPrevistos', 'null'::jsonb),
    nullif(p_venda->>'parcelasPagamento', '')::integer,
    nullif(btrim(p_venda->>'descricao'), ''),
    nullif(btrim(p_venda->>'observacoes'), ''),
    nullif(btrim(p_venda->>'descricaoFinanceiro'), ''),
    nullif(btrim(p_venda->>'observacoesFiscais'), ''),
    nullif(btrim(p_venda->>'garantia'), ''),
    (p_venda->>'subTotal')::numeric,
    (p_venda->>'valorTotal')::numeric,
    nullif(p_venda->>'descontoTipo', '')::public.enum_tipo_desconto_venda,
    nullif(p_venda->>'descontoValor', '')::numeric,
    v_valor_frete,
    coalesce(nullif(p_venda->>'dataVenda', '')::timestamp, now()),
    v_comissao,
    nullif(p_venda->>'categoriaVendaId', '')::integer
  ) RETURNING id INTO v_venda_id;

  IF v_baixar_estoque THEN
    PERFORM public.estoque_definir_contexto(
      'VENDA', v_venda_id::bigint, 'Venda #' || v_venda_id, v_created_by
    );
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_venda->'itens') LOOP
    v_produto_id := (v_item->>'produtoId')::integer;
    v_quantidade := (v_item->>'quantidade')::integer;
    v_item_sub_total := round((v_item->>'subTotal')::numeric, 2);
    v_item_valor_total := round((v_item->>'valorTotal')::numeric, 2);
    v_item_valor_desconto := round(coalesce(nullif(v_item->>'valorDesconto', '')::numeric, 0), 2);
    v_item_tipo_desconto := nullif(v_item->>'tipoDesconto', '')::public.enum_tipo_desconto_venda;
    v_item_valor_frete := round(coalesce(nullif(v_item->>'valorFrete', '')::numeric, 0), 2);
    v_item_desconto_aplicado := CASE
      WHEN v_item_tipo_desconto::text = 'PORCENTAGEM'
        THEN round(v_item_sub_total * least(v_item_valor_desconto, 100) / 100, 2)
      WHEN v_item_tipo_desconto::text = 'FIXO'
        THEN least(v_item_sub_total, v_item_valor_desconto)
      ELSE 0
    END;

    IF v_produto_id IS NULL OR v_quantidade IS NULL OR v_quantidade <= 0
       OR v_item_sub_total < 0 OR v_item_valor_total < 0
       OR v_item_valor_desconto < 0 OR v_item_valor_frete < 0
       OR (v_item_tipo_desconto::text = 'PORCENTAGEM' AND v_item_valor_desconto > 100)
       OR v_item_valor_total <> round(v_item_sub_total - v_item_desconto_aplicado + v_item_valor_frete, 2) THEN
      RAISE EXCEPTION 'Dados inválidos em um dos itens da venda.' USING ERRCODE = 'P0001';
    END IF;

    IF v_baixar_estoque THEN
      PERFORM public.fn_baixa_estoque_produto(v_produto_id, v_quantidade);
    END IF;

    INSERT INTO public.vendaproduto (
      venda_id, produtoid, quantidade, sub_total, valor_total,
      valor_desconto, tipo_desconto, valor_frete
    ) VALUES (
      v_venda_id, v_produto_id, v_quantidade, v_item_sub_total, v_item_valor_total,
      v_item_valor_desconto, v_item_tipo_desconto, v_item_valor_frete
    );

    IF v_baixar_estoque THEN
      INSERT INTO public.vendaproduto_baixa (venda_id, produtoid, quantidade, updated_at)
      VALUES (v_venda_id, v_produto_id, v_quantidade, now())
      ON CONFLICT (venda_id, produtoid) DO UPDATE
        SET quantidade = excluded.quantidade, updated_at = now();
    END IF;
  END LOOP;

  RETURN v_venda_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.excluir_pagamento_multiplo(p_id bigint, p_deleted_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_grupo public.pagamento_multiplo%ROWTYPE;
  v_baixadas integer;
  v_documentos jsonb;
  v_doc record;
  v_removidas integer;
BEGIN
  SELECT * INTO v_grupo FROM public.pagamento_multiplo WHERE id = p_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Pagamento múltiplo #% não encontrado.', p_id USING ERRCODE = 'P0002';
  END IF;

  IF v_grupo.modo = 'PARCELADO' THEN
    SELECT count(*) INTO v_baixadas
      FROM public.transacao t
     WHERE t.pagamento_multiplo_id = p_id
       AND t.is_deleted = false
       AND t.pendente = false;

    IF v_baixadas > 0 THEN
      RAISE EXCEPTION
        'Este pagamento tem % parcela(s) já baixada(s). Estorne essas baixas antes de excluir o pagamento.',
        v_baixadas USING ERRCODE = 'P0001';
    END IF;
  END IF;

  -- Os documentos agora vivem no rateio, e não no `ordemservicoid` das linhas.
  SELECT coalesce(jsonb_agg(DISTINCT jsonb_build_object('tipo', tipo_documento, 'id', documento_id)), '[]'::jsonb)
    INTO v_documentos
    FROM public.pagamento_multiplo_rateio
   WHERE pagamento_multiplo_id = p_id;

  UPDATE public.transacao
     SET is_deleted = true,
         deleted_at = now(),
         deleted_by = p_deleted_by,
         updated_at = now()
   WHERE pagamento_multiplo_id = p_id
     AND is_deleted = false;

  GET DIAGNOSTICS v_removidas = ROW_COUNT;

  FOR v_doc IN
    SELECT DISTINCT tipo_documento, documento_id
      FROM public.pagamento_multiplo_rateio
     WHERE pagamento_multiplo_id = p_id
  LOOP
    IF v_doc.tipo_documento = 'OS' THEN
      PERFORM public.recalcular_status_financeiro_os(v_doc.documento_id);
    ELSE
      PERFORM public.recalcular_status_financeiro_venda(v_doc.documento_id);
    END IF;
  END LOOP;

  -- O grupo NÃO é apagado. A versão anterior tentava, e não podia: as transações
  -- são excluídas por `is_deleted` e continuam referenciando o grupo, cuja FK é
  -- ON DELETE RESTRICT — ou seja, excluir um pagamento múltiplo sempre falhou com
  -- erro de chave estrangeira. Manter a linha também preserva o histórico de que
  -- aquele recebimento existiu e foi desfeito; o rateio segue junto, e some das
  -- contas porque `recebimento_por_documento` só olha transação não excluída.

  RETURN jsonb_build_object(
    'id', p_id,
    'transacoes_removidas', v_removidas,
    'documentos', v_documentos
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_transacao_valor_base_padrao()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF new.valor_base IS NULL OR new.valor_base = 0 THEN
    new.valor_base := coalesce(new.valor, 0);
  END IF;
  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.recalcular_valores_transacao(p_transacao_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_acrescimos numeric(14,2);
  v_descontos numeric(14,2);
  v_base numeric(14,2);
  v_valor numeric(14,2);
BEGIN
  SELECT coalesce(valor_base, valor, 0) INTO v_base
    FROM public.transacao WHERE id = p_transacao_id;
  IF NOT FOUND THEN RETURN; END IF;

  SELECT
    coalesce(sum(valor_calculado) FILTER (WHERE natureza = 'ACRESCIMO'), 0),
    coalesce(sum(valor_calculado) FILTER (WHERE natureza = 'DESCONTO'), 0)
    INTO v_acrescimos, v_descontos
    FROM public.transacao_ajuste
   WHERE transacao_id = p_transacao_id;

  v_valor := round(v_base + v_acrescimos, 2);

  IF v_descontos > v_valor THEN
    RAISE EXCEPTION
      'A soma dos descontos (%) nao pode passar do valor bruto (%).', v_descontos, v_valor
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.transacao
     SET valor_acrescimos = v_acrescimos,
         valor_descontos = v_descontos,
         valor = v_valor,
         "valorLiquido" = round(v_valor - v_descontos, 2),
         updated_at = now()
   WHERE id = p_transacao_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.nfe_impedir_origem_transmitida_duplicada()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_status_ocupa boolean;
  v_status_anterior_ocupava boolean := false;
BEGIN
  v_status_ocupa := NOT coalesce(NEW.is_deleted, false)
    AND NEW.status IN (
      'ASSINADA', 'ENVIADA', 'AUTORIZADA', 'PENDENTE_ENVIO',
      'CONTINGENCIA', 'RESULTADO_INCERTO'
    );

  IF NOT v_status_ocupa THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    v_status_anterior_ocupava := NOT coalesce(OLD.is_deleted, false)
      AND OLD.status IN (
        'ASSINADA', 'ENVIADA', 'AUTORIZADA', 'PENDENTE_ENVIO',
        'CONTINGENCIA', 'RESULTADO_INCERTO'
      );

    IF v_status_anterior_ocupava
       AND NEW.vendaid IS NOT DISTINCT FROM OLD.vendaid
       AND NEW.ordemservicoid IS NOT DISTINCT FROM OLD.ordemservicoid
       AND NEW.modelo IS NOT DISTINCT FROM OLD.modelo THEN
      RETURN NEW;
    END IF;
  END IF;

  IF NEW.vendaid IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(
      hashtextextended(format('nfe:venda:%s:modelo:%s', NEW.vendaid, NEW.modelo), 0)
    );

    IF EXISTS (
      SELECT 1
        FROM public.nfe existente
       WHERE existente.id <> coalesce(NEW.id, -1)
         AND existente.vendaid = NEW.vendaid
         AND existente.modelo = NEW.modelo
         AND existente.is_deleted = false
         AND existente.status IN (
           'ASSINADA', 'ENVIADA', 'AUTORIZADA', 'PENDENTE_ENVIO',
           'CONTINGENCIA', 'RESULTADO_INCERTO'
         )
    ) THEN
      RAISE EXCEPTION USING
        ERRCODE = '23505',
        MESSAGE = format(
          'A venda %s já possui uma nota transmitida do modelo %s.',
          NEW.vendaid,
          NEW.modelo
        ),
        CONSTRAINT = 'nfe_origem_venda_modelo_transmitida_idx';
    END IF;
  END IF;

  IF NEW.ordemservicoid IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(
      hashtextextended(format('nfe:os:%s:modelo:%s', NEW.ordemservicoid, NEW.modelo), 0)
    );

    IF EXISTS (
      SELECT 1
        FROM public.nfe existente
       WHERE existente.id <> coalesce(NEW.id, -1)
         AND existente.ordemservicoid = NEW.ordemservicoid
         AND existente.modelo = NEW.modelo
         AND existente.is_deleted = false
         AND existente.status IN (
           'ASSINADA', 'ENVIADA', 'AUTORIZADA', 'PENDENTE_ENVIO',
           'CONTINGENCIA', 'RESULTADO_INCERTO'
         )
    ) THEN
      RAISE EXCEPTION USING
        ERRCODE = '23505',
        MESSAGE = format(
          'A OS %s já possui uma nota transmitida do modelo %s.',
          NEW.ordemservicoid,
          NEW.modelo
        ),
        CONSTRAINT = 'nfe_origem_os_modelo_transmitida_idx';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_vincular_transacao_evento_financeiro()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_evento public.eventos_financeiros%rowtype;
BEGIN
  IF new.evento_financeiro_id IS NULL THEN RETURN new; END IF;
  SELECT * INTO v_evento FROM public.eventos_financeiros WHERE id = new.evento_financeiro_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Evento financeiro nao encontrado.'; END IF;
  IF v_evento.status <> 'ATIVO' OR v_evento.transacaoid IS NOT NULL THEN
    RAISE EXCEPTION 'Este evento ja foi convertido ou cancelado.';
  END IF;
  -- `pode_gerar_transacao` e o sinalizador: comissao e lancamento manual o tem,
  -- evento automatico de item nao. A origem nao decide mais nada aqui.
  IF NOT v_evento.pode_gerar_transacao THEN
    RAISE EXCEPTION 'Este evento nao pode gerar uma transacao.';
  END IF;
  IF v_evento.ordemservicoid <> new.ordemservicoid OR v_evento.natureza <> new.tipo::text THEN
    RAISE EXCEPTION 'A transacao nao corresponde a OS ou a natureza do evento financeiro.';
  END IF;
  IF round(v_evento.valor, 2) <> round(new.valor, 2) THEN
    RAISE EXCEPTION 'O valor da transacao deve ser igual ao valor do evento financeiro.';
  END IF;
  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.baixar_por_adiantamento(p_ids bigint[], p_adiantamento jsonb, p_baixado_por uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tipo text;
  v_qtd int;
  v_tipos_distintos int;
  v_soma_liquida numeric(14,2) := 0;
  v_adiantamento_id bigint;
  v_pago_em timestamptz := coalesce(nullif(p_adiantamento->>'pago_em', '')::timestamptz, now());
  v_metodo public.metodo_pagamento;
  v_taxa numeric(14,2);
  v_tipo_taxa integer;
  -- Manter os títulos em aberto, só marcados como antecipados.
  v_manter_pendentes boolean :=
    coalesce((p_adiantamento->>'manter_titulos_pendentes')::boolean, false);
BEGIN
  IF p_ids IS NULL OR array_length(p_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'Selecione ao menos uma transacao.' USING ERRCODE = '22023';
  END IF;

  PERFORM 1 FROM public.transacao
   WHERE id = ANY(p_ids) AND is_deleted = false
   FOR UPDATE;

  SELECT count(*), count(DISTINCT upper(tipo::text)),
         coalesce(sum(coalesce(nullif("valorLiquido", 0), valor)), 0)
    INTO v_qtd, v_tipos_distintos, v_soma_liquida
    FROM public.transacao
   WHERE id = ANY(p_ids) AND is_deleted = false;

  IF v_qtd <> array_length(p_ids, 1) THEN
    RAISE EXCEPTION 'Alguma transacao selecionada nao existe mais.' USING ERRCODE = 'P0002';
  END IF;

  IF v_tipos_distintos > 1 THEN
    RAISE EXCEPTION 'Um adiantamento nao pode misturar receita e despesa.' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.transacao
     WHERE id = ANY(p_ids) AND (pendente = false OR is_deleted = true)
  ) THEN
    RAISE EXCEPTION 'Ha transacao ja baixada ou excluida na selecao.' USING ERRCODE = '23505';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.transacao WHERE id = ANY(p_ids) AND adiantamento_id IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'Ha transacao ja vinculada a outro adiantamento.' USING ERRCODE = '23505';
  END IF;

  SELECT upper(tipo::text) INTO v_tipo
    FROM public.transacao WHERE id = p_ids[1];

  BEGIN
    v_metodo := nullif(btrim(p_adiantamento->>'metodopagamento'), '')::public.metodo_pagamento;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'Metodo de pagamento invalido: %.', p_adiantamento->>'metodopagamento'
      USING ERRCODE = '22023';
  END;

  IF v_metodo IS NULL THEN
    RAISE EXCEPTION 'Metodo de pagamento obrigatorio.' USING ERRCODE = '22023';
  END IF;
  IF nullif(p_adiantamento->>'banco_id', '') IS NULL THEN
    RAISE EXCEPTION 'Banco obrigatorio no adiantamento.' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.transacao (
    descricao, valor, "valorLiquido", valor_base,
    data, competencia_em, vencimento_em, pago_em,
    tipo, pendente, eh_adiantamento, adiantamento_manteve_pendentes,
    banco_id, metodopagamento, categoria_id,
    plano_de_conta_id, centro_custo_id,
    cliente_id, fornecedor_id,
    nomepagador, cpfcnpjpagador,
    descricao_pagamento, created_by, baixado_por
  ) VALUES (
    coalesce(nullif(btrim(p_adiantamento->>'descricao'), ''),
             'Adiantamento de ' || v_qtd || ' titulo(s)'),
    v_soma_liquida, v_soma_liquida, v_soma_liquida,
    v_pago_em, v_pago_em, v_pago_em, v_pago_em,
    v_tipo::public.tipos_transacao, false, true, v_manter_pendentes,
    (p_adiantamento->>'banco_id')::bigint,
    v_metodo,
    nullif(p_adiantamento->>'categoria_id', '')::integer,
    nullif(p_adiantamento->>'plano_de_conta_id', '')::integer,
    nullif(p_adiantamento->>'centro_custo_id', '')::integer,
    nullif(p_adiantamento->>'cliente_id', '')::integer,
    nullif(p_adiantamento->>'fornecedor_id', '')::integer,
    coalesce(nullif(btrim(p_adiantamento->>'nomepagador'), ''), 'Adiantamento'),
    coalesce(nullif(btrim(p_adiantamento->>'cpfcnpjpagador'), ''), 'NÃO INFORMADO'),
    nullif(btrim(p_adiantamento->>'descricao_pagamento'), ''),
    p_baixado_por, p_baixado_por
  ) RETURNING id INTO v_adiantamento_id;

  IF v_manter_pendentes THEN
    -- Só o vínculo. O título continua em aberto para a cobrança acompanhar, e o
    -- banco fica nulo desde já: quando ele for baixado, o dinheiro não é novo —
    -- a menos que o banco tenha debitado de volta, e aí a baixa diz isso.
    UPDATE public.transacao
       SET adiantamento_id = v_adiantamento_id,
           banco_id = NULL,
           updated_at = now()
     WHERE id = ANY(p_ids);
  ELSE
    UPDATE public.transacao
       SET pendente = false,
           pago_em = v_pago_em,
           baixado_por = p_baixado_por,
           vencimento_em = coalesce(vencimento_em, data),
           banco_id = NULL,
           adiantamento_id = v_adiantamento_id,
           updated_at = now()
     WHERE id = ANY(p_ids);

    INSERT INTO public.transacao_baixa_historico (
      transacao_id, vencimento_em, pago_em, baixado_por, banco_id, metodopagamento
    )
    SELECT id, vencimento_em, pago_em, baixado_por, NULL, metodopagamento
      FROM public.transacao WHERE id = ANY(p_ids);
  END IF;

  v_taxa := round(coalesce(nullif(p_adiantamento->>'taxa', '')::numeric, 0), 2);

  IF v_taxa < 0 THEN
    RAISE EXCEPTION 'A taxa de antecipacao nao pode ser negativa.' USING ERRCODE = '22023';
  END IF;
  IF v_taxa >= v_soma_liquida THEN
    RAISE EXCEPTION
      'A taxa de antecipacao (%) nao pode alcancar o valor antecipado (%).', v_taxa, v_soma_liquida
      USING ERRCODE = '22023';
  END IF;

  IF v_taxa > 0 THEN
    SELECT id INTO v_tipo_taxa
      FROM public.tipos_ajuste_transacao WHERE codigo_sistema = 'TAXA_ANTECIPACAO';

    INSERT INTO public.transacao_ajuste (
      transacao_id, tipo_id, natureza, modo, valor_informado, valor_calculado, created_by
    ) VALUES (
      v_adiantamento_id, v_tipo_taxa, 'DESCONTO', 'FIXO', v_taxa, v_taxa, p_baixado_por
    );
  END IF;

  RETURN jsonb_build_object(
    'adiantamento_id', v_adiantamento_id,
    'quantidade', v_qtd,
    'valor_bruto', v_soma_liquida,
    'taxa', v_taxa,
    'valor_liquido', v_soma_liquida - v_taxa,
    'tipo', v_tipo,
    'titulos_mantidos_pendentes', v_manter_pendentes
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.recalcular_baixas_transacao(p_transacao_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_baixado numeric(14,2);
  v_quantas int;
  v_liquido numeric(14,2);
  v_ultimo_pago timestamptz;
  v_antecipado boolean;
  v_fechou boolean;
BEGIN
  SELECT coalesce(sum(coalesce(nullif(f."valorLiquido", 0), f.valor)), 0),
         count(*), max(f.pago_em)
    INTO v_baixado, v_quantas, v_ultimo_pago
    FROM public.transacao f
   WHERE f.baixa_de_transacao_id = p_transacao_id
     AND f.is_deleted = false;

  SELECT coalesce(nullif(t."valorLiquido", 0), t.valor), t.adiantamento_id IS NOT NULL
    INTO v_liquido, v_antecipado
    FROM public.transacao t WHERE t.id = p_transacao_id;
  IF NOT FOUND THEN RETURN; END IF;

  IF round(v_baixado, 2) > round(coalesce(v_liquido, 0), 2) THEN
    RAISE EXCEPTION
      'As baixas do título #% somam % e passam do valor dele (%).',
      p_transacao_id, v_baixado, v_liquido USING ERRCODE = '22023';
  END IF;

  IF v_quantas = 0 THEN
    UPDATE public.transacao SET valor_baixado = 0, updated_at = now()
     WHERE id = p_transacao_id AND valor_baixado <> 0;
    RETURN;
  END IF;

  /*
   * Em título antecipado a filha é REPASSE DE CAIXA, não quitação.
   *
   * A antecipação já respondeu pelo principal; o que entra agora é só a parte
   * que o banco não reteve. Quem fecha o título é a baixa, que sabe que o boleto
   * foi pago por inteiro — e ela já gravou a data informada.
   */
  IF coalesce(v_antecipado, false) THEN
    UPDATE public.transacao
       SET valor_baixado = round(v_baixado, 2), updated_at = now()
     WHERE id = p_transacao_id;
    RETURN;
  END IF;

  v_fechou := round(v_baixado, 2) >= round(coalesce(v_liquido, 0), 2);

  UPDATE public.transacao
     SET valor_baixado = round(v_baixado, 2),
         pendente = NOT v_fechou,
         pago_em = CASE WHEN v_fechou THEN v_ultimo_pago ELSE NULL END,
         -- `data` é a data de liquidação, e é por ela que as listas recortam o
         -- período. Fechado, o título vale pelo dia do último pagamento; reaberto
         -- por estorno, volta a valer pelo vencimento — a mesma ida e volta que a
         -- baixa comum e o estorno dela já fazem.
         data = CASE
           WHEN v_fechou THEN coalesce(v_ultimo_pago, data)
           ELSE coalesce(vencimento_em, data)
         END,
         updated_at = now()
   WHERE id = p_transacao_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.validar_limite_pagamento_os()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_status text;
  v_total_devido numeric(14,2);
  v_ja_comprometido numeric(14,2);
  v_novo_valor_face numeric(14,2);
BEGIN
  IF NEW.ordemservicoid IS NULL
     OR upper(NEW.tipo::text) <> 'RECEITA'
     OR NEW.evento_financeiro_id IS NOT NULL
     OR NEW.is_deleted THEN
    RETURN NEW;
  END IF;

  -- O lock vive até o fim da transação que efetivamente insere/edita a linha.
  PERFORM pg_advisory_xact_lock(87001, NEW.ordemservicoid);

  SELECT o.status::text,
         round(
           greatest(coalesce(o.orcamentototal, 0), 0) +
           CASE
             WHEN o.acrescimo_financeiro_tipo = 'PORCENTAGEM' THEN
               greatest(coalesce(o.orcamentototal, 0), 0) *
               least(greatest(coalesce(o.acrescimo_financeiro_valor, 0), 0), 100) / 100
             WHEN o.acrescimo_financeiro_tipo = 'FIXO' THEN
               greatest(coalesce(o.acrescimo_financeiro_valor, 0), 0)
             ELSE 0
           END,
           2
         )
    INTO v_status, v_total_devido
  FROM public.ordemservico o
  WHERE o.id = NEW.ordemservicoid
    AND coalesce(o.is_deleted, false) = false;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ordem de serviço não encontrada.' USING ERRCODE = 'P0002';
  END IF;

  IF v_status NOT IN ('ORCAMENTO_APROVADO', 'EM_ANDAMENTO', 'PAGAMENTO')
     AND (
       TG_OP = 'INSERT' OR
       OLD.ordemservicoid IS DISTINCT FROM NEW.ordemservicoid OR
       upper(OLD.tipo::text) IS DISTINCT FROM upper(NEW.tipo::text) OR
       OLD.evento_financeiro_id IS DISTINCT FROM NEW.evento_financeiro_id
     ) THEN
    RAISE EXCEPTION 'Pagamentos da OS só podem ser registrados após a aprovação do orçamento e antes da conclusão.'
      USING ERRCODE = 'P0001';
  END IF;

  IF v_total_devido <= 0 THEN
    RAISE EXCEPTION 'A OS não possui valor financeiro disponível para pagamento.'
      USING ERRCODE = '23514';
  END IF;

  SELECT coalesce(round(sum(
           greatest(coalesce(t.valor, 0) - greatest(coalesce(t.valor_acrescimos, 0), 0), 0)
         ), 2), 0)
    INTO v_ja_comprometido
  FROM public.transacao t
  WHERE t.ordemservicoid = NEW.ordemservicoid
    AND upper(t.tipo::text) = 'RECEITA'
    AND t.evento_financeiro_id IS NULL
    AND t.is_deleted = false
    AND (TG_OP = 'INSERT' OR t.id <> NEW.id);

  v_novo_valor_face := round(
    greatest(coalesce(NEW.valor, 0) - greatest(coalesce(NEW.valor_acrescimos, 0), 0), 0),
    2
  );

  IF round(v_ja_comprometido + v_novo_valor_face, 2) > v_total_devido THEN
    RAISE EXCEPTION 'A soma de pagamentos e títulos ultrapassa o total financeiro da OS. Saldo disponível: R$ %.',
      to_char(greatest(v_total_devido - v_ja_comprometido, 0), 'FM999G999G990D00')
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.recalcular_status_financeiro_os(p_ordemservicoid integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_status text;
  v_pagamento_concluido_em timestamptz;
  v_total_devido numeric(14,2);
  v_valor_comprometido numeric(14,2);
  v_quitada boolean;
  v_novo_status text;
  v_novo_pagamento_concluido_em timestamptz;
BEGIN
  SELECT o.status::text, o.pagamento_concluido_em
    INTO v_status, v_pagamento_concluido_em
  FROM public.ordemservico o
  WHERE o.id = p_ordemservicoid
    AND coalesce(o.is_deleted, false) = false;

  IF NOT FOUND THEN RETURN; END IF;

  SELECT r.total_devido, r.valor_comprometido, r.quitada
    INTO v_total_devido, v_valor_comprometido, v_quitada
  FROM public.resumo_financeiro_os(p_ordemservicoid) r;

  v_novo_status := v_status;
  IF v_status = 'PAGAMENTO' AND v_quitada THEN
    v_novo_status := 'CONCLUIDO';
  ELSIF v_status = 'CONCLUIDO'
        AND v_total_devido > 0
        AND v_valor_comprometido < v_total_devido THEN
    v_novo_status := 'PAGAMENTO';
  END IF;

  v_novo_pagamento_concluido_em := CASE
    WHEN v_quitada THEN coalesce(v_pagamento_concluido_em, now())
    ELSE NULL
  END;

  UPDATE public.ordemservico
  SET status = v_novo_status::public.enum_status_os,
      pagamento_concluido_em = v_novo_pagamento_concluido_em,
      updatedat = now()
  WHERE id = p_ordemservicoid
    AND (
      status::text IS DISTINCT FROM v_novo_status OR
      pagamento_concluido_em IS DISTINCT FROM v_novo_pagamento_concluido_em
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.nfe_liberar_numero(p_nfe_id bigint, p_motivo text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_nfe public.nfe%ROWTYPE;
  v_config public.nfe_config%ROWTYPE;
BEGIN
  SELECT * INTO v_nfe FROM public.nfe WHERE id = p_nfe_id FOR UPDATE;
  IF NOT FOUND OR NOT v_nfe.numero_definitivo OR v_nfe.numero IS NULL THEN
    RETURN false;
  END IF;

  IF v_nfe.status IN (
    'AUTORIZADA', 'DENEGADA', 'CANCELADA', 'ENVIADA', 'ASSINADA',
    'PENDENTE_ENVIO', 'CONTINGENCIA', 'RESULTADO_INCERTO'
  ) THEN
    RETURN false;
  END IF;

  SELECT * INTO v_config
    FROM public.nfe_config
   WHERE empresaid = v_nfe.empresaid
     AND modelo = v_nfe.modelo
   ORDER BY id
   LIMIT 1
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  UPDATE public.nfe
     SET numero_definitivo = false,
         updatedat = now()
   WHERE id = p_nfe_id;

  INSERT INTO public.nfe_numero_liberado (config_id, serie, numero, motivo)
  VALUES (v_config.id, v_nfe.serie, v_nfe.numero, p_motivo)
  ON CONFLICT ON CONSTRAINT nfe_numero_liberado_unico DO NOTHING;

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_estoque_movimento_registrar()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_delta integer;
  v_sentido text;
  v_origem text;
  v_acao text;
  v_documento bigint;
  v_label text;
  v_usuario uuid;
BEGIN
  v_delta := COALESCE(new.estoque, 0) - COALESCE(old.estoque, 0);
  IF v_delta = 0 THEN
    RETURN new;
  END IF;

  v_sentido := CASE WHEN v_delta > 0 THEN 'ENTRADA' ELSE 'SAIDA' END;

  v_origem := COALESCE(nullif(current_setting('app.estoque_origem', true), ''), 'NAO_IDENTIFICADA');
  IF v_origem NOT IN ('ENTRADA', 'SAIDA_MANUAL', 'VENDA', 'ORDEM_SERVICO') THEN
    v_origem := 'NAO_IDENTIFICADA';
  END IF;

  -- Entrada de mercadoria soma; os demais processos subtraem. Movimento no
  -- sentido contrario ao natural da origem so pode ser desfazimento.
  v_acao := CASE
    WHEN v_origem = 'NAO_IDENTIFICADA' THEN 'REGISTRO'
    WHEN v_origem = 'ENTRADA' AND v_sentido = 'SAIDA' THEN 'ESTORNO'
    WHEN v_origem <> 'ENTRADA' AND v_sentido = 'ENTRADA' THEN 'ESTORNO'
    ELSE 'REGISTRO'
  END;

  v_documento := nullif(current_setting('app.estoque_documento_id', true), '')::bigint;
  v_label := nullif(current_setting('app.estoque_documento_label', true), '');
  v_usuario := nullif(current_setting('app.estoque_usuario', true), '')::uuid;

  INSERT INTO public.estoque_movimento (
    produto_id, sentido, origem, acao, quantidade,
    saldo_anterior, saldo_resultante,
    entrada_id, saida_id, venda_id, ordemservicoid,
    documento_label, created_by
  ) VALUES (
    new.id,
    v_sentido,
    v_origem,
    v_acao,
    abs(v_delta),
    COALESCE(old.estoque, 0),
    COALESCE(new.estoque, 0),
    CASE WHEN v_origem = 'ENTRADA' THEN v_documento END,
    CASE WHEN v_origem = 'SAIDA_MANUAL' THEN v_documento END,
    CASE WHEN v_origem = 'VENDA' THEN v_documento::integer END,
    CASE WHEN v_origem = 'ORDEM_SERVICO' THEN v_documento::integer END,
    v_label,
    v_usuario
  );

  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.estoque_definir_contexto(p_origem text, p_documento_id bigint DEFAULT NULL::bigint, p_documento_label text DEFAULT NULL::text, p_usuario uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM set_config('app.estoque_origem', COALESCE(p_origem, ''), true);
  PERFORM set_config('app.estoque_documento_id', COALESCE(p_documento_id::text, ''), true);
  PERFORM set_config('app.estoque_documento_label', COALESCE(p_documento_label, ''), true);
  PERFORM set_config('app.estoque_usuario', COALESCE(p_usuario::text, ''), true);
END;
$function$

