CREATE OR REPLACE FUNCTION public.estoque_saida_item_fiscal_validar_origem()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_saida_produto integer;
  v_saida_quantidade numeric;
  v_entrada_produto integer;
  v_entrada_quantidade numeric;
  v_ja_vinculada numeric;
  v_exige_referencia boolean;
BEGIN
  SELECT produto_id, quantidade
    INTO v_saida_produto, v_saida_quantidade
    FROM public.estoque_saida_item
   WHERE id = NEW.saida_item_id
     AND saida_id = NEW.saida_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'O item fiscal não pertence à saída informada.' USING ERRCODE = '23514';
  END IF;

  SELECT documento_referenciado_obrigatorio OR finalidade = 'DEVOLUCAO'
    INTO v_exige_referencia
    FROM public.estoque_saida_fiscal
   WHERE saida_id = NEW.saida_id;

  IF v_exige_referencia AND (
    NEW.entrada_item_origem_id IS NULL OR NEW.numero_item_referenciado IS NULL
  ) THEN
    RAISE EXCEPTION 'A operação fiscal exige a entrada e o número do item de origem.'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.entrada_item_origem_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT produto_id, quantidade
    INTO v_entrada_produto, v_entrada_quantidade
    FROM public.entradaitens
   WHERE id = NEW.entrada_item_origem_id
   FOR UPDATE;

  IF NOT FOUND OR v_entrada_produto <> v_saida_produto THEN
    RAISE EXCEPTION 'O item da entrada de origem pertence a outro produto.' USING ERRCODE = '23514';
  END IF;

  SELECT coalesce(sum(saida_item.quantidade), 0)
    INTO v_ja_vinculada
    FROM public.estoque_saida_item_fiscal vinculo
    JOIN public.estoque_saida_item saida_item ON saida_item.id = vinculo.saida_item_id
   WHERE vinculo.entrada_item_origem_id = NEW.entrada_item_origem_id
     AND vinculo.id <> coalesce(NEW.id, -1);

  IF v_ja_vinculada + v_saida_quantidade > v_entrada_quantidade THEN
    RAISE EXCEPTION 'A quantidade total vinculada supera a quantidade recebida no item de origem.'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.registrar_saida_estoque(p_produto_id integer, p_quantidade integer, p_motivo text, p_observacao text DEFAULT NULL::text, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_produto public.produto%ROWTYPE;
  v_saida_id bigint;
  v_motivo text := upper(btrim(coalesce(p_motivo, '')));
  v_observacao text := nullif(btrim(p_observacao), '');
  v_saldo_anterior integer;
  v_saldo_resultante integer;
  v_custo numeric(14,4);
BEGIN
  IF p_produto_id IS NULL OR p_produto_id <= 0 THEN
    RAISE EXCEPTION 'Produto invalido.' USING ERRCODE = '22023';
  END IF;
  IF p_quantidade IS NULL OR p_quantidade <= 0 THEN
    RAISE EXCEPTION 'A quantidade deve ser maior que zero.' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.tipos_motivo_saida
    WHERE codigo = v_motivo AND ativo AND escopo IN ('PRODUTO', 'AMBOS')
  ) THEN
    RAISE EXCEPTION 'Motivo de saida invalido.' USING ERRCODE = '22023';
  END IF;
  IF v_motivo = 'OUTRO' AND v_observacao IS NULL THEN
    RAISE EXCEPTION 'Informe a observacao para o motivo Outro.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_produto
  FROM public.produto
  WHERE id = p_produto_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Produto nao encontrado.' USING ERRCODE = 'P0002';
  END IF;

  v_saldo_anterior := coalesce(v_produto.estoque, 0)::integer;
  IF v_saldo_anterior < p_quantidade THEN
    RAISE EXCEPTION 'Estoque insuficiente. Disponivel: %, solicitado: %.', v_saldo_anterior, p_quantidade
      USING ERRCODE = '23514';
  END IF;
  v_saldo_resultante := v_saldo_anterior - p_quantidade;
  v_custo := greatest(coalesce(v_produto.ultimovalordecompra, v_produto.precocompra, 0), 0);

  INSERT INTO public.estoque_saida (motivo, observacao, created_by)
  VALUES (v_motivo, v_observacao, p_created_by)
  RETURNING id INTO v_saida_id;

  INSERT INTO public.estoque_saida_item (
    saida_id, produto_id, quantidade, saldo_anterior, saldo_resultante, valor_custo_aplicado
  ) VALUES (
    v_saida_id, p_produto_id, p_quantidade, v_saldo_anterior, v_saldo_resultante, v_custo
  );

  PERFORM public.estoque_definir_contexto(
    'SAIDA_MANUAL', v_saida_id, 'Saida #' || v_saida_id || ' - ' || replace(v_motivo, '_', ' '), p_created_by
  );

  UPDATE public.produto
  SET estoque = v_saldo_resultante,
      updatedat = now()
  WHERE id = p_produto_id;

  RETURN jsonb_build_object(
    'saida_id', v_saida_id,
    'saldo_anterior', v_saldo_anterior,
    'saldo_resultante', v_saldo_resultante
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.sincronizar_baixa_estoque_os_produto(p_os_id integer, p_produto_id integer, p_quantidade_alvo integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_estoque integer;
  v_baixado integer := 0;
  v_delta integer;
BEGIN
  IF p_os_id IS NULL OR p_os_id <= 0 OR p_produto_id IS NULL OR p_produto_id <= 0 THEN
    RAISE EXCEPTION 'OS e produto sao obrigatorios.' USING ERRCODE = '22023';
  END IF;
  IF p_quantidade_alvo IS NULL OR p_quantidade_alvo < 0 THEN
    RAISE EXCEPTION 'Quantidade alvo invalida.' USING ERRCODE = '22023';
  END IF;

  SELECT estoque INTO v_estoque FROM public.produto WHERE id = p_produto_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Produto % nao encontrado.', p_produto_id USING ERRCODE = 'P0002';
  END IF;

  SELECT quantidade INTO v_baixado
  FROM public.osproduto_baixa
  WHERE ordemservicoid = p_os_id AND produtoid = p_produto_id
  FOR UPDATE;

  v_baixado := coalesce(v_baixado, 0);
  v_delta := p_quantidade_alvo - v_baixado;

  IF v_delta <> 0 THEN
    IF v_delta > 0 AND coalesce(v_estoque, 0) < v_delta THEN
      RAISE EXCEPTION 'Estoque insuficiente. Disponivel: %, necessario: %.', coalesce(v_estoque, 0), v_delta
        USING ERRCODE = '23514';
    END IF;

    PERFORM public.estoque_definir_contexto('ORDEM_SERVICO', p_os_id::bigint, 'OS #' || p_os_id);

    UPDATE public.produto
    SET estoque = coalesce(estoque, 0) - v_delta,
        updatedat = now()
    WHERE id = p_produto_id;
  END IF;

  IF p_quantidade_alvo = 0 THEN
    DELETE FROM public.osproduto_baixa
    WHERE ordemservicoid = p_os_id AND produtoid = p_produto_id;
  ELSE
    INSERT INTO public.osproduto_baixa (ordemservicoid, produtoid, quantidade)
    VALUES (p_os_id, p_produto_id, p_quantidade_alvo)
    ON CONFLICT (ordemservicoid, produtoid) DO UPDATE
      SET quantidade = excluded.quantidade;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.cancelar_entrada_fiscal_mista_interna(p_entrada_id bigint, p_usoconsumo_entrada_id bigint, p_motivo text, p_cancelada_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_doc_produto bigint;
  v_doc_uso bigint;
BEGIN
  SELECT fiscal_dfe_documento_id INTO v_doc_produto FROM public.entrada WHERE id = p_entrada_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Entrada de estoque nao encontrada.' USING ERRCODE = 'P0002'; END IF;
  SELECT documento_fiscal_recebido_id INTO v_doc_uso FROM public.usoconsumo_entrada WHERE id = p_usoconsumo_entrada_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Entrada de uso e consumo nao encontrada.' USING ERRCODE = 'P0002'; END IF;

  IF v_doc_produto IS NULL OR v_doc_uso IS NULL OR v_doc_produto <> v_doc_uso THEN
    RAISE EXCEPTION 'As entradas informadas nao pertencem a mesma NF-e.' USING ERRCODE = '22023';
  END IF;

  -- Libera os guards de cancelamento parcial apenas dentro desta transacao.
  PERFORM set_config('app.entrada_mista_cancelamento', 'permitido', true);

  -- Uso e consumo primeiro: e o lado que remove o pagamento pendente compartilhado,
  -- de modo que o cancelamento do estoque nao tente trata-lo uma segunda vez.
  PERFORM public.cancelar_entrada_usoconsumo(p_usoconsumo_entrada_id, p_motivo, p_cancelada_by);
  PERFORM public.cancelar_entrada_confirmada(p_entrada_id, p_motivo, p_cancelada_by);

  RETURN jsonb_build_object(
    'entrada_id', p_entrada_id,
    'usoconsumo_entrada_id', p_usoconsumo_entrada_id,
    'status', 'CANCELADA'
  );
END $function$

