CREATE OR REPLACE FUNCTION public.validar_etiqueta_inventario_global()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_etiqueta text;
BEGIN
  v_etiqueta := nullif(upper(btrim(NEW.etiqueta)), '');
  NEW.etiqueta := v_etiqueta;
  IF v_etiqueta IS NULL THEN
    RETURN NEW;
  END IF;

  -- Serializa tentativas concorrentes para a mesma etiqueta, inclusive entre tabelas.
  PERFORM pg_advisory_xact_lock(hashtextextended('inventario-etiqueta:' || v_etiqueta, 0));

  IF TG_TABLE_NAME = 'produto' THEN
    PERFORM 1 FROM public.usoconsumo_item
    WHERE upper(btrim(etiqueta)) = v_etiqueta
    LIMIT 1;
    IF FOUND THEN
      RAISE EXCEPTION 'Já existe um item de uso e consumo com esta etiqueta.' USING ERRCODE = '23505';
    END IF;

    PERFORM 1 FROM public.produto
    WHERE upper(btrim(etiqueta)) = v_etiqueta
      AND id <> coalesce(NEW.id, 0)
    LIMIT 1;
    IF FOUND THEN
      RAISE EXCEPTION 'Já existe um produto com esta etiqueta.' USING ERRCODE = '23505';
    END IF;
  ELSE
    PERFORM 1 FROM public.produto
    WHERE upper(btrim(etiqueta)) = v_etiqueta
    LIMIT 1;
    IF FOUND THEN
      RAISE EXCEPTION 'Já existe um produto com esta etiqueta.' USING ERRCODE = '23505';
    END IF;

    PERFORM 1 FROM public.usoconsumo_item
    WHERE upper(btrim(etiqueta)) = v_etiqueta
      AND id <> coalesce(NEW.id, 0)
    LIMIT 1;
    IF FOUND THEN
      RAISE EXCEPTION 'Já existe outro item de uso e consumo com esta etiqueta.' USING ERRCODE = '23505';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.registrar_auditoria()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  anterior jsonb := CASE WHEN tg_op IN ('UPDATE', 'DELETE') THEN to_jsonb(old) ELSE NULL END;
  novo jsonb := CASE WHEN tg_op IN ('INSERT', 'UPDATE') THEN to_jsonb(new) ELSE NULL END;
  anterior_alterado jsonb;
  novo_alterado jsonb;
  campos text[] := '{}'::text[];
  linha_referencia jsonb;
  ator uuid;
  contexto_externo jsonb;
  id_registro text;
BEGIN
  IF tg_op = 'UPDATE' AND anterior = novo THEN
    RETURN new;
  END IF;

  linha_referencia := coalesce(novo, anterior);

  IF tg_op = 'UPDATE' THEN
    SELECT
      coalesce(jsonb_object_agg(chave, anterior -> chave), '{}'::jsonb),
      coalesce(jsonb_object_agg(chave, novo -> chave), '{}'::jsonb),
      coalesce(array_agg(chave ORDER BY chave), '{}'::text[])
    INTO anterior_alterado, novo_alterado, campos
    FROM (
      SELECT chave
      FROM jsonb_object_keys(anterior || novo) AS chaves(chave)
      WHERE (anterior -> chave) IS DISTINCT FROM (novo -> chave)
    ) alteracoes;
  ELSIF tg_op = 'INSERT' THEN
    novo_alterado := novo;
    SELECT coalesce(array_agg(chave ORDER BY chave), '{}'::text[])
      INTO campos
    FROM jsonb_object_keys(novo) AS chaves(chave);
  ELSE
    anterior_alterado := anterior;
    SELECT coalesce(array_agg(chave ORDER BY chave), '{}'::text[])
      INTO campos
    FROM jsonb_object_keys(anterior) AS chaves(chave);
  END IF;

  ator := coalesce(
    public.auditoria_try_uuid(current_setting('app.audit_user_id', true)),
    auth.uid(),
    public.auditoria_usuario_requisicao()
  );
  contexto_externo := CASE
    WHEN ator IS NULL THEN public.auditoria_contexto_externo_requisicao()
    ELSE NULL
  END;

  IF ator IS NULL AND tg_op = 'INSERT' THEN
    ator := coalesce(
      public.auditoria_try_uuid(novo ->> 'created_by'),
      public.auditoria_try_uuid(novo ->> 'createdby'),
      public.auditoria_try_uuid(novo ->> 'usuariocriadorid')
    );
  ELSIF ator IS NULL AND tg_op = 'UPDATE' THEN
    ator := coalesce(
      public.auditoria_try_uuid(novo ->> 'updated_by'),
      public.auditoria_try_uuid(novo ->> 'updatedby'),
      public.auditoria_try_uuid(novo ->> 'usuarioalteracaoid')
    );
  ELSIF ator IS NULL AND tg_op = 'DELETE' THEN
    ator := coalesce(
      public.auditoria_try_uuid(anterior ->> 'deleted_by'),
      public.auditoria_try_uuid(anterior ->> 'updated_by'),
      public.auditoria_try_uuid(anterior ->> 'updatedby'),
      public.auditoria_try_uuid(anterior ->> 'usuarioalteracaoid')
    );
  END IF;

  IF ator IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.usuario WHERE id = ator) THEN
    ator := NULL;
  END IF;

  id_registro := coalesce(
    linha_referencia ->> 'id',
    linha_referencia ->> 'uuid',
    linha_referencia ->> 'ordemservicoid',
    linha_referencia ->> 'vendaid',
    linha_referencia ->> 'produtoid',
    linha_referencia ->> 'clienteid',
    nullif(concat_ws(':', linha_referencia ->> 'perfilid', linha_referencia ->> 'permissaoid'), '')
  );

  INSERT INTO public.auditoria_evento (
    operacao,
    modulo,
    tabela,
    registro_id,
    usuario_id,
    ator_nome,
    dados_anteriores,
    dados_novos,
    campos_alterados,
    origem
  ) VALUES (
    tg_op,
    public.auditoria_modulo_tabela(tg_table_name),
    tg_table_name,
    id_registro,
    ator,
    contexto_externo ->> 'nome',
    public.auditoria_json_seguro(anterior_alterado),
    public.auditoria_json_seguro(novo_alterado),
    campos,
    CASE
      WHEN ator IS NOT NULL THEN 'usuario'
      WHEN contexto_externo ->> 'origem' = 'cliente' THEN 'cliente'
      ELSE 'sistema'
    END
  );

  IF tg_op = 'DELETE' THEN
    RETURN old;
  END IF;
  RETURN new;
EXCEPTION WHEN others THEN
  RAISE WARNING 'Falha ao auditar %.%: %', tg_table_schema, tg_table_name, sqlerrm;
  IF tg_op = 'DELETE' THEN
    RETURN old;
  END IF;
  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.cancelar_saida_estoque_interna(p_saida_id bigint, p_motivo text, p_cancelada_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_saida public.estoque_saida%ROWTYPE;
  v_linha record;
  v_estoque integer;
  v_motivo text := nullif(btrim(p_motivo), '');
BEGIN
  IF v_motivo IS NULL THEN
    RAISE EXCEPTION 'Informe o motivo do cancelamento.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_saida FROM public.estoque_saida WHERE id = p_saida_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Saída não encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF v_saida.status = 'CANCELADA' THEN
    RAISE EXCEPTION 'Esta saída já está cancelada.' USING ERRCODE = '22023';
  END IF;

  -- Cancelar uma saida devolve a quantidade ao estoque.
  FOR v_linha IN
    SELECT * FROM public.estoque_saida_item WHERE saida_id = p_saida_id ORDER BY id FOR UPDATE
  LOOP
    SELECT estoque INTO v_estoque FROM public.produto WHERE id = v_linha.produto_id FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Produto % não encontrado.', v_linha.produto_id USING ERRCODE = 'P0002';
    END IF;

    UPDATE public.produto
    SET estoque = coalesce(estoque, 0) + v_linha.quantidade,
        updatedat = now()
    WHERE id = v_linha.produto_id;
  END LOOP;

  UPDATE public.estoque_saida
  SET status = 'CANCELADA',
      cancelada_at = now(),
      cancelada_by = p_cancelada_by,
      motivo_cancelamento = v_motivo
  WHERE id = p_saida_id;

  RETURN jsonb_build_object('saida_id', p_saida_id, 'status', 'CANCELADA');
END;
$function$

CREATE OR REPLACE FUNCTION public.cancelar_entrada_usoconsumo(p_entrada_id bigint, p_motivo text, p_cancelada_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_entrada public.usoconsumo_entrada%ROWTYPE; v_linha record; v_saldo integer; v_ultimo_custo numeric;
  v_motivo text := nullif(btrim(p_motivo), '');
BEGIN
  IF v_motivo IS NULL THEN RAISE EXCEPTION 'Informe o motivo do cancelamento.' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_entrada FROM public.usoconsumo_entrada WHERE id=p_entrada_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Entrada nao encontrada.' USING ERRCODE='P0002'; END IF;
  IF v_entrada.status='CANCELADA' THEN RAISE EXCEPTION 'Entrada ja cancelada.' USING ERRCODE='22023'; END IF;
  IF EXISTS(SELECT 1 FROM public.transacao WHERE usoconsumo_entrada_id=p_entrada_id AND NOT pendente AND NOT is_deleted AND estorno_transacao_id IS NULL) THEN
    RAISE EXCEPTION 'Existem pagamentos liquidados. Estorne-os antes de cancelar a entrada.' USING ERRCODE='23514';
  END IF;
  -- Pagamento compartilhado com uma entrada de estoque ainda ativa: a NF-e mista
  -- so pode ser cancelada como um todo, via cancelar_entrada_fiscal_mista.
  IF coalesce(current_setting('app.entrada_mista_cancelamento', true), '') <> 'permitido'
     AND EXISTS(
       SELECT 1 FROM public.transacao t
       JOIN public.entrada e ON e.id = t.entrada_id
       WHERE t.usoconsumo_entrada_id = p_entrada_id
         AND NOT t.is_deleted
         AND t.estorno_transacao_id IS NULL
         AND e.cancelada_at IS NULL
     ) THEN
    RAISE EXCEPTION 'Esta entrada divide o pagamento da NF-e com uma entrada de estoque ainda ativa. Cancele a nota inteira.'
      USING ERRCODE = '23514';
  END IF;
  FOR v_linha IN SELECT * FROM public.usoconsumo_entrada_item WHERE entrada_id=p_entrada_id ORDER BY id FOR UPDATE LOOP
    SELECT estoque INTO v_saldo FROM public.usoconsumo_item WHERE id=v_linha.item_id FOR UPDATE;
    IF v_saldo<v_linha.quantidade THEN
      RAISE EXCEPTION 'Saldo insuficiente para cancelar a entrada do item %.',v_linha.item_id USING ERRCODE='23514';
    END IF;
    PERFORM set_config('app.usoconsumo_movimento','permitido',true);
    UPDATE public.usoconsumo_item SET estoque=estoque-v_linha.quantidade,updated_by=p_cancelada_by WHERE id=v_linha.item_id;
    INSERT INTO public.usoconsumo_movimento_entrada(
      entrada_id,entrada_item_id,item_id,tipo,quantidade,saldo_anterior,saldo_resultante,valor_unitario_compra,created_by
    ) VALUES(p_entrada_id,v_linha.id,v_linha.item_id,'CANCELAMENTO',v_linha.quantidade,v_saldo,
      v_saldo-v_linha.quantidade,v_linha.valor_unitario_compra,p_cancelada_by);
    SELECT ei.valor_unitario_compra INTO v_ultimo_custo
      FROM public.usoconsumo_entrada_item ei JOIN public.usoconsumo_entrada e ON e.id=ei.entrada_id
      WHERE ei.item_id=v_linha.item_id AND e.id<>p_entrada_id AND e.status='CONFIRMADA'
      ORDER BY e.created_at DESC,e.id DESC,ei.id DESC LIMIT 1;
    UPDATE public.usoconsumo_item SET ultimovalordecompra=v_ultimo_custo WHERE id=v_linha.item_id;
  END LOOP;
  UPDATE public.transacao SET is_deleted=true,deleted_at=now(),deleted_by=p_cancelada_by,updated_at=now()
    WHERE usoconsumo_entrada_id=p_entrada_id AND pendente AND NOT is_deleted;
  UPDATE public.fiscal_dfe_item_apropriacao SET cancelada_at=now()
    WHERE usoconsumo_entrada_id=p_entrada_id AND cancelada_at IS NULL;
  UPDATE public.usoconsumo_entrada
    SET status='CANCELADA',cancelada_at=now(),cancelada_by=p_cancelada_by,motivo_cancelamento=v_motivo
    WHERE id=p_entrada_id;
  RETURN jsonb_build_object('entrada_id',p_entrada_id,'status','CANCELADA');
END $function$

CREATE OR REPLACE FUNCTION public.tg_recalcular_documento_do_rateio()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tipo text := CASE WHEN TG_OP = 'DELETE' THEN OLD.tipo_documento ELSE NEW.tipo_documento END;
  v_doc integer := CASE WHEN TG_OP = 'DELETE' THEN OLD.documento_id ELSE NEW.documento_id END;
BEGIN
  IF v_tipo = 'OS' THEN
    PERFORM public.recalcular_status_financeiro_os(v_doc);
  ELSE
    PERFORM public.recalcular_status_financeiro_venda(v_doc);
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.desfazer_adiantamento(p_id bigint, p_deleted_by uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_adiantamento public.transacao%ROWTYPE;
  v_titulos bigint[];
  v_documentos jsonb;
  v_titulo record;
  v_com_lancamento bigint[];
BEGIN
  SELECT * INTO v_adiantamento
    FROM public.transacao
   WHERE id = p_id AND is_deleted = false;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lançamento #% não encontrado.', p_id USING ERRCODE = 'P0002';
  END IF;
  IF NOT coalesce(v_adiantamento.eh_adiantamento, false) THEN
    RAISE EXCEPTION 'O lançamento #% não é uma antecipação.', p_id USING ERRCODE = 'P0001';
  END IF;

  SELECT array_agg(id) INTO v_titulos
    FROM public.transacao
   WHERE adiantamento_id = p_id AND is_deleted = false;

  -- O repasse mora numa transação própria. Reabrir o título em bloco a deixaria
  -- órfã no extrato, com dinheiro sem origem.
  SELECT array_agg(DISTINCT t.id) INTO v_com_lancamento
    FROM public.transacao t
    JOIN public.transacao f ON f.baixa_de_transacao_id = t.id AND f.is_deleted = false
   WHERE t.adiantamento_id = p_id AND t.is_deleted = false;

  IF v_com_lancamento IS NOT NULL THEN
    RAISE EXCEPTION
      'O título #% teve dinheiro lançado na conta pela baixa dele. Estorne essa baixa antes de desfazer a antecipação.',
      v_com_lancamento[1] USING ERRCODE = '22023';
  END IF;

  SELECT coalesce(jsonb_agg(DISTINCT jsonb_build_object(
           'tipo', CASE WHEN t.ordemservicoid IS NOT NULL THEN 'OS' ELSE 'VENDA' END,
           'id', coalesce(t.ordemservicoid, t.vendaid))), '[]'::jsonb)
    INTO v_documentos
    FROM public.transacao t
   WHERE t.id = ANY (coalesce(v_titulos, ARRAY[]::bigint[]))
     AND coalesce(t.ordemservicoid, t.vendaid) IS NOT NULL;

  IF v_titulos IS NOT NULL THEN
    UPDATE public.transacao
       SET pendente = true,
           pago_em = NULL,
           baixado_por = NULL,
           adiantamento_id = NULL,
           updated_at = now()
     WHERE id = ANY (v_titulos);
  END IF;

  UPDATE public.transacao
     SET is_deleted = true,
         deleted_at = now(),
         deleted_by = p_deleted_by,
         updated_at = now()
   WHERE id = p_id;

  FOR v_titulo IN
    SELECT DISTINCT t.ordemservicoid, t.vendaid
      FROM public.transacao t
     WHERE t.id = ANY (coalesce(v_titulos, ARRAY[]::bigint[]))
  LOOP
    IF v_titulo.ordemservicoid IS NOT NULL THEN
      PERFORM public.recalcular_status_financeiro_os(v_titulo.ordemservicoid);
    ELSIF v_titulo.vendaid IS NOT NULL THEN
      PERFORM public.recalcular_status_financeiro_venda(v_titulo.vendaid);
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'id', p_id,
    'titulos_revertidos', coalesce(array_length(v_titulos, 1), 0),
    'titulos', coalesce(to_jsonb(v_titulos), '[]'::jsonb),
    'documentos', v_documentos,
    'tipo', v_adiantamento.tipo::text
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_agendar_resumo_financeiro_telegram()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_endpoint_url text;
  v_bearer_token text;
BEGIN
  SELECT financeiro_endpoint_url, bearer_token
    INTO v_endpoint_url, v_bearer_token
    FROM public.telegram_dispatch_configuracao
   WHERE id = 1 AND ativo = true;

  IF v_endpoint_url IS NULL OR v_bearer_token IS NULL THEN
    RETURN;
  END IF;

  PERFORM net.http_post(
    url := v_endpoint_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_bearer_token
    ),
    body := jsonb_build_object('origem', 'PG_CRON'),
    timeout_milliseconds := 5000
  );
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'Falha ao agendar resumo financeiro Telegram: %', SQLERRM;
END;
$function$

CREATE OR REPLACE FUNCTION public.reverter_venda_para_orcamento(p_venda_id bigint, p_usuario_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_venda public.venda%ROWTYPE;
  v_produtos_devolvidos integer := 0;
  v_transacoes_excluidas integer := 0;
  v_valor_concluido numeric := 0;
BEGIN
  SELECT * INTO v_venda FROM public.venda WHERE id = p_venda_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Venda não encontrada.' USING ERRCODE = 'P0002';
  END IF;

  IF upper(v_venda.status::text) <> 'PAGAMENTO' THEN
    RAISE EXCEPTION 'Somente vendas em PAGAMENTO podem voltar para orçamento (esta está %).', v_venda.status
      USING ERRCODE = '22023';
  END IF;

  -- Mesma trava do cancelamento: nota emitida amarra a venda ao numero fiscal.
  IF EXISTS (
    SELECT 1 FROM public.nfe
    WHERE vendaid = p_venda_id AND status::text NOT IN ('RASCUNHO', 'CANCELADA', 'REJEITADA')
  ) THEN
    RAISE EXCEPTION 'Cancele a NF-e autorizada ou em processamento antes de voltar a venda para orçamento.'
      USING ERRCODE = '23514';
  END IF;

  SELECT count(*)::integer INTO v_produtos_devolvidos
  FROM public.vendaproduto_baixa WHERE venda_id = p_venda_id;
  PERFORM public.fn_estornar_estoque_venda(p_venda_id::integer);

  SELECT count(*)::integer, coalesce(sum(valor) FILTER (WHERE NOT pendente), 0)
    INTO v_transacoes_excluidas, v_valor_concluido
  FROM public.transacao
  WHERE vendaid = p_venda_id AND NOT is_deleted;

  UPDATE public.transacao
  SET pendente = false, is_deleted = true, deleted_at = now(), deleted_by = p_usuario_id,
      updated_at = now(), updated_by = p_usuario_id
  WHERE vendaid = p_venda_id AND NOT is_deleted;

  -- forma_pagamento volta a ser nula porque ela e escolhida na aprovacao: manter
  -- a antiga faria o orcamento exibir um pagamento que ninguem combinou ainda.
  UPDATE public.venda
  SET status = 'ORCAMENTO', forma_pagamento = NULL,
      updated_by = coalesce(p_usuario_id, updated_by), updatedat = now()
  WHERE id = p_venda_id;

  RETURN jsonb_build_object(
    'vendaId', p_venda_id,
    'status', 'ORCAMENTO',
    'produtosDevolvidos', v_produtos_devolvidos,
    'transacoesExcluidas', v_transacoes_excluidas,
    'valorConcluidoRemovido', v_valor_concluido
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.vincular_produto_avulso_os(p_ordem_id integer, p_avulso_id bigint, p_produto_id integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_status text;
  v_modo text := 'ORCAMENTO';
  v_quantidade integer;
BEGIN
  PERFORM public.estoque_definir_contexto('ORDEM_SERVICO', p_ordem_id::bigint, 'OS #' || p_ordem_id);
  PERFORM public.vincular_produto_avulso_os_interna(p_ordem_id, p_avulso_id, p_produto_id);

  SELECT status::text
    INTO v_status
  FROM public.ordemservico
  WHERE id = p_ordem_id;

  SELECT COALESCE(modo_baixa_estoque_os::text, 'ORCAMENTO')
    INTO v_modo
  FROM public.config_geral
  ORDER BY id DESC
  LIMIT 1;

  -- PAGAMENTO acompanha EM_ANDAMENTO pela mesma razao que no PUT do orcamento:
  -- a OS ja consumiu material, entao mexer nos itens tem que mexer no saldo.
  IF v_modo = 'EXECUCAO' AND v_status IN ('EM_ANDAMENTO', 'PAGAMENTO') THEN
    SELECT quantidade::integer
      INTO v_quantidade
    FROM public.osproduto
    WHERE ordemservicoid = p_ordem_id AND produtoid = p_produto_id;

    IF v_quantidade IS NOT NULL AND v_quantidade > 0 THEN
      PERFORM public.sincronizar_baixa_estoque_os_produto(p_ordem_id, p_produto_id, v_quantidade);
    END IF;
  END IF;

  IF v_status IN ('ORCAMENTO_APROVADO', 'EM_ANDAMENTO', 'PAGAMENTO', 'CONCLUIDO') THEN
    PERFORM public.reconciliar_eventos_financeiros_os(
      p_ordem_id,
      v_status IN ('EM_ANDAMENTO', 'PAGAMENTO', 'CONCLUIDO')
    );
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_invalidar_aprovacao_venda_alterada()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_venda_id integer;
  v_invalidacoes integer := 0;
  v_status text;
  v_eh_troca_status boolean := TG_NAME = 'trg_venda_status_invalidar_aprovacao';
  v_status_mudou_na_edicao boolean := false;
BEGIN
  IF TG_NAME = 'trg_venda_invalidar_aprovacao_alterada' THEN
    v_status_mudou_na_edicao :=
      (to_jsonb(OLD)->>'status') IS DISTINCT FROM (to_jsonb(NEW)->>'status');
  END IF;

  IF TG_TABLE_NAME = 'venda' THEN
    IF TG_OP = 'DELETE' THEN
      v_venda_id := OLD.id;
    ELSE
      v_venda_id := NEW.id;
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    v_venda_id := OLD.venda_id;
  ELSE
    v_venda_id := NEW.venda_id;
  END IF;

  v_invalidacoes := public.invalidar_aprovacoes_venda(v_venda_id, 'ORCAMENTO_ALTERADO');

  SELECT status::text INTO v_status FROM public.venda WHERE id = v_venda_id;

  IF v_invalidacoes > 0
     OR (
       NOT v_eh_troca_status
       AND NOT v_status_mudou_na_edicao
       AND v_status IN ('APROVACAO_ORCAMENTO', 'ORCAMENTO_APROVADO', 'ORCAMENTO_RECUSADO')
     ) THEN
    UPDATE public.venda
       SET status = CASE
             WHEN v_status IN ('APROVACAO_ORCAMENTO', 'ORCAMENTO_APROVADO', 'ORCAMENTO_RECUSADO')
               THEN 'ORCAMENTO'::public.enum_status_venda
             ELSE status
           END,
           statusaprovacao = NULL,
           updatedat = now()
     WHERE id = v_venda_id;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.preparar_venda_para_aprovacao(p_venda_id integer, p_novo_token uuid, p_expira_em timestamp with time zone, p_usuario_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_venda public.venda%ROWTYPE;
  v_aprovacao public.vendaaprovacao%ROWTYPE;
  v_documento text;
  v_reutilizado boolean := false;
BEGIN
  SELECT * INTO v_venda
    FROM public.venda
   WHERE id = p_venda_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Venda não encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF v_venda.status::text NOT IN ('ORCAMENTO', 'APROVACAO_ORCAMENTO', 'ORCAMENTO_RECUSADO') THEN
    RAISE EXCEPTION 'Esta venda não pode ser enviada para aprovação no status atual.'
      USING ERRCODE = '22023';
  END IF;

  SELECT regexp_replace(coalesce(c.cpfcnpj, ''), '\D', '', 'g')
    INTO v_documento
    FROM public.cliente c
   WHERE c.id = v_venda.clienteid;
  IF coalesce(v_documento, '') = '' THEN
    RAISE EXCEPTION 'O cliente precisa possuir CPF/CNPJ para receber o link de aprovação.'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_aprovacao
    FROM public.vendaaprovacao
   WHERE vendaid = p_venda_id
     AND usado_em IS NULL
     AND invalidado_em IS NULL
   ORDER BY created_at DESC
   LIMIT 1
   FOR UPDATE;

  IF FOUND
     AND v_venda.status::text = 'APROVACAO_ORCAMENTO'
     AND v_venda.statusaprovacao::text = 'PENDENTE'
     AND v_aprovacao.expira_em > now() THEN
    v_reutilizado := true;
  ELSE
    IF v_aprovacao.id IS NOT NULL THEN
      UPDATE public.vendaaprovacao
         SET invalidado_em = now(),
             motivo_invalidacao = CASE
               WHEN v_aprovacao.expira_em <= now() THEN 'EXPIRADO'
               ELSE 'NOVO_ENVIO'
             END
       WHERE id = v_aprovacao.id;
    END IF;

    UPDATE public.venda
       SET status = 'APROVACAO_ORCAMENTO',
           statusaprovacao = 'PENDENTE',
           updated_by = coalesce(p_usuario_id, updated_by),
           updatedat = now()
     WHERE id = p_venda_id;

    INSERT INTO public.vendaaprovacao (
      vendaid, token, expira_em, created_by
    ) VALUES (
      p_venda_id, p_novo_token, p_expira_em, p_usuario_id
    )
    RETURNING * INTO v_aprovacao;
  END IF;

  RETURN jsonb_build_object(
    'vendaId', p_venda_id,
    'status', 'APROVACAO_ORCAMENTO',
    'statusaprovacao', 'PENDENTE',
    'token', v_aprovacao.token,
    'expiraEm', v_aprovacao.expira_em,
    'reutilizado', v_reutilizado
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_enfileirar_notificacao_estoque()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_evento_tipo text;
  v_quantidade_entregas integer := 0;
  v_endpoint_url text;
  v_bearer_token text;
BEGIN
  v_evento_tipo := public.fn_tipo_evento_notificacao_estoque(
    NEW.origem,
    NEW.acao,
    NEW.sentido
  );

  IF v_evento_tipo IS NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.telegram_estoque_entrega (
    movimento_id,
    usuario_id,
    chat_id,
    evento_tipo
  )
  SELECT
    NEW.id,
    preferencia.usuario_id,
    preferencia.chat_id,
    v_evento_tipo
  FROM public.telegram_usuario_preferencia preferencia
  JOIN public.usuario usuario
    ON usuario.id = preferencia.usuario_id
   AND usuario.ativo = true
  WHERE preferencia.ativo = true
    AND preferencia.chat_id IS NOT NULL
    AND v_evento_tipo = ANY(preferencia.estoque_eventos_selecionados)
    AND EXISTS (
      SELECT 1
      FROM public.perfilpermissao perfil_permissao
      JOIN public.permissao permissao
        ON permissao.id = perfil_permissao.permissaoid
      WHERE perfil_permissao.perfilid = usuario.perfilid
        AND upper(btrim(permissao.nome)) = 'ESTOQUE:VISUALIZAR'
    )
  ON CONFLICT (movimento_id, usuario_id) DO NOTHING;

  GET DIAGNOSTICS v_quantidade_entregas = ROW_COUNT;
  IF v_quantidade_entregas = 0 THEN
    RETURN NEW;
  END IF;

  SELECT endpoint_url, bearer_token
    INTO v_endpoint_url, v_bearer_token
    FROM public.telegram_dispatch_configuracao
   WHERE id = 1 AND ativo = true;

  IF v_endpoint_url IS NULL OR v_bearer_token IS NULL THEN
    RETURN NEW;
  END IF;

  BEGIN
    PERFORM net.http_post(
      url := v_endpoint_url,
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || v_bearer_token
      ),
      body := jsonb_build_object(
        'origem', 'ESTOQUE',
        'movimento_id', NEW.id
      ),
      timeout_milliseconds := 5000
    );
  EXCEPTION WHEN OTHERS THEN
    -- A entrega continua pendente e pode ser recuperada pelo cron ou pelo botao
    -- de processamento manual.
    RAISE WARNING 'Falha ao agendar notificacao Telegram do movimento de estoque %: %', NEW.id, SQLERRM;
  END;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.baixar_transacao_pendente(p_transacao_id bigint, p_pago_em timestamp with time zone, p_banco_id bigint, p_metodopagamento text, p_plano_de_conta_id integer DEFAULT NULL::integer, p_centro_custo_id integer DEFAULT NULL::integer, p_baixado_por uuid DEFAULT NULL::uuid, p_valor numeric DEFAULT NULL::numeric, p_valor_lancado numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_transacao public.transacao%ROWTYPE;
  v_metodo public.metodo_pagamento;
  v_antecipada boolean;
  v_atual public.transacao%ROWTYPE;
  v_liquido numeric(14,2);
  v_saldo numeric(14,2);
  v_filha_id bigint;
  v_lancado numeric(14,2);
  v_valor numeric(14,2);
BEGIN
  IF p_transacao_id IS NULL OR p_transacao_id <= 0 THEN
    RAISE EXCEPTION 'Transação inválida.' USING ERRCODE = '22023';
  END IF;
  IF p_pago_em IS NULL THEN
    RAISE EXCEPTION 'Data do pagamento obrigatória.' USING ERRCODE = '22023';
  END IF;
  IF p_banco_id IS NULL OR p_banco_id <= 0 THEN
    RAISE EXCEPTION 'Banco obrigatório.' USING ERRCODE = '22023';
  END IF;
  IF nullif(btrim(p_metodopagamento), '') IS NULL THEN
    RAISE EXCEPTION 'Método de pagamento obrigatório.' USING ERRCODE = '22023';
  END IF;

  BEGIN
    v_metodo := btrim(p_metodopagamento)::public.metodo_pagamento;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'Método de pagamento inválido: %.', btrim(p_metodopagamento)
      USING ERRCODE = '22023';
  END;

  SELECT * INTO v_atual FROM public.transacao
   WHERE id = p_transacao_id AND is_deleted = false FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Transação não encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF NOT coalesce(v_atual.pendente, false) THEN
    RAISE EXCEPTION 'A transação já foi baixada.' USING ERRCODE = '23505';
  END IF;

  v_antecipada := v_atual.adiantamento_id IS NOT NULL;
  v_liquido := round(coalesce(nullif(v_atual."valorLiquido", 0), v_atual.valor, 0), 2);
  v_saldo := round(v_liquido - coalesce(v_atual.valor_baixado, 0), 2);
  v_lancado := round(coalesce(p_valor_lancado, 0), 2);
  v_valor := p_valor;

  /*
   * Quem já foi pago em partes termina em partes.
   *
   * O título com filhas não pode voltar a carregar banco — seria o mesmo dinheiro
   * no título e nas baixas dele. Então quem chama sem dizer o valor (a tela
   * pagando o restante exato, a baixa em lote) está pedindo "termina de receber",
   * e é isso que a função entrega: o saldo, pelo caminho da filha.
   *
   * Antecipado fica de fora: lá a filha é repasse de caixa e não quitação, e o
   * `valor_baixado` dele não é saldo a pagar.
   */
  IF v_valor IS NULL
     AND NOT coalesce(v_antecipada, false)
     AND coalesce(v_atual.valor_baixado, 0) > 0 THEN
    v_valor := v_saldo;
  END IF;

  IF p_valor_lancado IS NOT NULL THEN
    IF NOT coalesce(v_antecipada, false) THEN
      RAISE EXCEPTION
        'Só título antecipado escolhe quanto da baixa entra no caixa: neste o banco já é sempre gravado.'
        USING ERRCODE = '22023';
    END IF;
    IF v_lancado < 0 THEN
      RAISE EXCEPTION 'O valor lançado não pode ser negativo.' USING ERRCODE = '22023';
    END IF;
    IF v_lancado > v_liquido THEN
      RAISE EXCEPTION
        'O valor lançado (%) passa do valor do título (%).', v_lancado, v_liquido
        USING ERRCODE = '22023';
    END IF;
  END IF;

  IF v_valor IS NOT NULL THEN
    IF round(v_valor, 2) <= 0 THEN
      RAISE EXCEPTION 'O valor da baixa deve ser maior que zero.' USING ERRCODE = '22023';
    END IF;
    IF round(v_valor, 2) > v_saldo THEN
      RAISE EXCEPTION
        'A baixa de % passa do saldo em aberto do título, que é de %.',
        round(v_valor, 2), v_saldo USING ERRCODE = '22023';
    END IF;
    IF coalesce(v_antecipada, false) THEN
      RAISE EXCEPTION
        'Título antecipado ainda não aceita baixa parcial.' USING ERRCODE = '22023';
    END IF;
  END IF;

  -- --------------------------------------------------------------- parcial
  IF v_valor IS NOT NULL
     AND (round(v_valor, 2) < v_saldo OR coalesce(v_atual.valor_baixado, 0) > 0) THEN

    -- O banco que estava no título era a conta PREVISTA, escolhida no
    -- lançamento. A partir daqui o dinheiro mora nas baixas, e cada uma sabe por
    -- onde entrou de verdade.
    IF v_atual.banco_id IS NOT NULL THEN
      UPDATE public.transacao SET banco_id = NULL, updated_at = now()
       WHERE id = p_transacao_id;
    END IF;

    v_filha_id := public.registrar_baixa_filha(
      v_atual, round(v_valor, 2), p_pago_em, p_banco_id, v_metodo,
      p_plano_de_conta_id, p_centro_custo_id, p_baixado_por, false
    );

    INSERT INTO public.transacao_baixa_historico (
      transacao_id, vencimento_em, pago_em, baixado_por, banco_id, metodopagamento
    ) VALUES (
      v_atual.id, coalesce(v_atual.vencimento_em, v_atual.data), p_pago_em,
      p_baixado_por, p_banco_id, v_metodo
    );

    SELECT * INTO v_transacao FROM public.transacao WHERE id = p_transacao_id;

    IF upper(v_transacao.tipo::text) = 'RECEITA' AND v_transacao.evento_financeiro_id IS NULL THEN
      IF v_transacao.ordemservicoid IS NOT NULL THEN
        PERFORM public.recalcular_status_financeiro_os(v_transacao.ordemservicoid);
      END IF;
      IF v_transacao.vendaid IS NOT NULL THEN
        PERFORM public.recalcular_status_financeiro_venda(v_transacao.vendaid);
      END IF;
    END IF;

    RETURN jsonb_build_object(
      'id', v_transacao.id,
      'baixa_id', v_filha_id,
      'valor_baixado', v_transacao.valor_baixado,
      'saldo', round(v_liquido - v_transacao.valor_baixado, 2),
      'pendente', v_transacao.pendente,
      'parcial', true
    );
  END IF;

  -- ------------------------------------------------------------- de uma vez
  UPDATE public.transacao
  SET vencimento_em = coalesce(vencimento_em, data),
      data = p_pago_em,
      pago_em = p_pago_em,
      baixado_por = p_baixado_por,
      banco_id = CASE WHEN coalesce(v_antecipada, false) THEN NULL ELSE p_banco_id END,
      metodopagamento = v_metodo,
      plano_de_conta_id = p_plano_de_conta_id,
      centro_custo_id = p_centro_custo_id,
      pendente = false,
      updated_at = now()
  WHERE id = p_transacao_id
    AND pendente = true
    AND is_deleted = false
  RETURNING * INTO v_transacao;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'A transação já foi baixada.' USING ERRCODE = '23505';
  END IF;

  IF coalesce(v_antecipada, false) AND v_lancado > 0 THEN
    v_filha_id := public.registrar_baixa_filha(
      v_atual, v_lancado, p_pago_em, p_banco_id, v_metodo,
      p_plano_de_conta_id, p_centro_custo_id, p_baixado_por, true
    );
  END IF;

  INSERT INTO public.transacao_baixa_historico (
    transacao_id, vencimento_em, pago_em, baixado_por, banco_id, metodopagamento
  ) VALUES (
    v_transacao.id, v_transacao.vencimento_em, v_transacao.pago_em,
    v_transacao.baixado_por,
    CASE WHEN v_filha_id IS NOT NULL THEN p_banco_id ELSE v_transacao.banco_id END,
    v_transacao.metodopagamento
  );

  IF upper(v_transacao.tipo::text) = 'RECEITA' AND v_transacao.evento_financeiro_id IS NULL THEN
    IF v_transacao.ordemservicoid IS NOT NULL THEN
      PERFORM public.recalcular_status_financeiro_os(v_transacao.ordemservicoid);
    END IF;

    IF v_transacao.vendaid IS NOT NULL THEN
      PERFORM public.recalcular_status_financeiro_venda(v_transacao.vendaid);
    END IF;

    IF v_transacao.pagamento_multiplo_id IS NOT NULL THEN
      PERFORM public.recalcular_documentos_da_transacao(v_transacao.id);
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'id', v_transacao.id,
    'pago_em', v_transacao.pago_em,
    'vencimento_em', v_transacao.vencimento_em,
    'pendente', false,
    'parcial', false,
    'baixa_id', v_filha_id,
    'valor_lancado', coalesce(v_lancado, 0)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.auth_login_rate_limit_register_failure(p_keys text[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_key text;
  v_row public.auth_login_rate_limit%rowtype;
  v_now timestamptz := clock_timestamp();
  v_retry integer := 0;
  v_current_retry integer;
begin
  foreach v_key in array coalesce(p_keys, array[]::text[]) loop
    if v_key is null or length(v_key) < 4 or length(v_key) > 80 then
      continue;
    end if;

    insert into public.auth_login_rate_limit (key_hash)
    values (v_key)
    on conflict (key_hash) do nothing;

    select * into v_row
    from public.auth_login_rate_limit
    where key_hash = v_key
    for update;

    if v_row.window_started_at <= v_now - interval '15 minutes' then
      v_row.failed_count := 0;
      v_row.window_started_at := v_now;
      v_row.blocked_until := null;
    end if;

    v_row.failed_count := v_row.failed_count + 1;

    if v_row.failed_count >= 5 then
      v_row.blocked_until := v_now + interval '15 minutes';
    end if;

    update public.auth_login_rate_limit
    set failed_count = v_row.failed_count,
        window_started_at = v_row.window_started_at,
        blocked_until = v_row.blocked_until,
        updated_at = v_now
    where key_hash = v_key;

    if v_row.blocked_until > v_now then
      v_current_retry := ceil(extract(epoch from (v_row.blocked_until - v_now)))::integer;
      v_retry := greatest(v_retry, v_current_retry);
    end if;
  end loop;

  return v_retry;
end;
$function$
